SEPARATOR = "->"
PROFANITY = "bad"


def parse_time(stamp):
    total = 0
    for i, part in enumerate(reversed(stamp.split(":"))):
        total += int(part) * (60 ** i)
    return total


def format_time(seconds):
    return "{:02d}:{:02d}".format(seconds // 60, seconds % 60)


def format_srt_time(seconds):
    return "{:02d}:{:02d}:{:02d},000".format(
        seconds // 3600, (seconds // 60) % 60, seconds % 60)


def split_segment(segment):
    head, _, tail = segment.partition(SEPARATOR)
    end, _, text = tail.strip().partition(" ")
    return parse_time(head.strip()), parse_time(end), text.strip()


def parse_segments(lines):
    for index, line in enumerate(lines):
        yield index, split_segment(line)[2]


def find_overlaps(segments):
    previous_end = None
    for index, segment in enumerate(segments):
        start, end, _ = split_segment(segment)
        if previous_end is not None and start < previous_end:
            yield index
        previous_end = end


def renumber_segments(segments):
    return ["{}: {}".format(index, segment)
            for index, segment in enumerate(segments)]


def find_long_durations(segments):
    for index, segment in enumerate(segments):
        start, end, _ = split_segment(segment)
        if end - start > 5:
            yield index, segment


def shift_timestamps(segments, offset=1):
    shifted = []
    for index, segment in enumerate(segments):
        start, end, text = split_segment(segment)
        shifted.append((index, "{} {} {} {}".format(
            format_time(start + offset), SEPARATOR,
            format_time(end + offset), text)))
    return shifted


def detect_profanity(segments):
    flagged = []
    for index, segment in enumerate(segments):
        if PROFANITY in split_segment(segment)[2].lower():
            flagged.append(index)
    return flagged


def format_srt(segments):
    blocks = []
    for index, segment in enumerate(segments, start=1):
        start, end, text = split_segment(segment)
        blocks.append("{}\n{} --> {}\n{}\n".format(
            index, format_srt_time(start), format_srt_time(end), text))
    return "\n".join(blocks)


def generate_index_html(segments):
    rows = []
    for index, segment in enumerate(segments):
        rows.append("<span id='{}'>{}</span>".format(
            index, split_segment(segment)[2]))
    return "\n".join(rows)


if __name__ == "__main__":
    data = [
        "00:01 -> 00:05 Hello",
        "00:04 -> 00:12 World",
        "00:12 -> 00:15 That was bad",
    ]
    for index, text in parse_segments(data):
        print("parsed", index, text)
    print("overlaps:", list(find_overlaps(data)))
    print("renumbered:", renumber_segments(data))
    print("long:", list(find_long_durations(data)))
    for index, moved in shift_timestamps(data):
        print("shifted", index, moved)
    print("profanity:", detect_profanity(data))
    print(format_srt(data))
    print(generate_index_html(data))

