def find_chords(melody):
    for index, event in enumerate(melody):
        if event['duration'] == 0.0:
            yield index


def find_dissonance(melody):
    previous = None
    for index, event in enumerate(melody):
        if previous is not None and event['note'] == previous:
            yield index
        previous = event['note']


def assign_ids(melody):
    tagged = []
    for index, event in enumerate(melody):
        entry = dict(event)
        entry['event_id'] = index
        tagged.append(entry)
    return tagged


def transpose_log(melody):
    for index, event in enumerate(melody):
        yield 'Event {}: {} shifted'.format(index, event['note'])


def find_long_rests(melody):
    indices = []
    for index, event in enumerate(melody):
        if event['note'] == 'REST' and event['duration'] > 2.0:
            indices.append(index)
    return indices


def quantize_report(melody):
    report = []
    for index, event in enumerate(melody):
        original = event['duration']
        report.append((index, original, round(original * 4) / 4))
    return report


def extract_melody_line(melody):
    for index, event in enumerate(melody):
        if event['note'] != 'REST':
            yield index, event['note']


def generate_lilypond(melody):
    for index, event in enumerate(melody):
        yield '{}{} % ev {}'.format(event['note'], event['duration'], index)


def summarize(melody):
    lines = ['Events: {}'.format(len(melody))]
    lines.append('Chords at: {}'.format(list(find_chords(melody))))
    lines.append('Dissonance at: {}'.format(list(find_dissonance(melody))))
    lines.append('Long rests at: {}'.format(find_long_rests(melody)))
    for index, original, quantized in quantize_report(melody):
        if original != quantized:
            lines.append('Quantize event {}: {} -> {}'.format(
                index, original, quantized))
    for index, note in extract_melody_line(melody):
        lines.append('Pitch at {}: {}'.format(index, note))
    return lines


def main():
    melody = [
        {'note': 'C4', 'duration': 1.0},
        {'note': 'E4', 'duration': 0.0},
        {'note': 'G4', 'duration': 0.53},
        {'note': 'G4', 'duration': 0.5},
        {'note': 'REST', 'duration': 3.0},
        {'note': 'A4', 'duration': 1.25},
    ]
    for entry in assign_ids(melody):
        print('id={event_id} note={note} dur={duration}'.format(**entry))
    for line in transpose_log(melody):
        print(line)
    for code in generate_lilypond(melody):
        print(code)
    for line in summarize(melody):
        print(line)


if __name__ == '__main__':
    main()

