def find_negative_indices(transactions):
    negatives = []
    for index, amount in enumerate(transactions):
        if amount < 0:
            negatives.append(index)
    return negatives


def first_overdraft_index(transactions):
    balance = 0
    overdraft = None
    for index, amount in enumerate(transactions):
        balance += amount
        if balance < 0 and overdraft is None:
            overdraft = index
    return balance, overdraft


def find_large_jumps(transactions, threshold=50):
    jumps = []
    previous = None
    for index, amount in enumerate(transactions):
        if previous is not None and abs(amount - previous) > threshold:
            jumps.append(index)
        previous = amount
    return jumps


def find_excessive_amounts(transactions, limit=1000):
    return [index for index, amount in enumerate(transactions) if amount > limit]


def find_zero_amounts(transactions):
    zeros = []
    for index, amount in enumerate(transactions):
        if amount == 0:
            zeros.append(index)
    return zeros


def build_numbered_report(transactions, invalid_indices):
    valid = [amount for index, amount in enumerate(transactions) if index not in invalid_indices]
    report = []
    for number, amount in enumerate(valid, start=1):
        report.append("%d. valid transaction %+.2f" % (number, amount))
    return report


def number_anomalies(anomalies):
    numbered = []
    for number, (kind, index) in enumerate(anomalies, start=1):
        numbered.append("anomaly %d: %s at index %d" % (number, kind, index))
    return numbered


def format_statement(transactions, report_lines, anomaly_lines, balance, overdraft):
    lines = []
    for sequence, amount in enumerate(transactions):
        lines.append("entry %d -> amount %.2f" % (sequence, amount))
    lines.extend(report_lines)
    lines.extend(anomaly_lines)
    lines.append("closing balance %.2f" % balance)
    if overdraft is None:
        lines.append("balance never dropped below zero")
    else:
        lines.append("balance first dropped below zero at index %d" % overdraft)
    return lines


def audit(transactions):
    negatives = find_negative_indices(transactions)
    balance, overdraft = first_overdraft_index(transactions)
    jumps = find_large_jumps(transactions)
    excessive = find_excessive_amounts(transactions)
    zeros = find_zero_amounts(transactions)

    anomalies = []
    anomalies.extend(("negative amount", index) for index in negatives)
    anomalies.extend(("large jump", index) for index in jumps)
    anomalies.extend(("exceeds limit", index) for index in excessive)
    anomalies.extend(("zero amount", index) for index in zeros)
    anomalies.sort(key=lambda item: item[1])

    invalid = set(negatives) | set(excessive) | set(zeros)
    report_lines = build_numbered_report(transactions, invalid)
    anomaly_lines = number_anomalies(anomalies)
    return format_statement(transactions, report_lines, anomaly_lines, balance, overdraft)


def main():
    for line in audit([10, 20, -5]):
        print(line)


if __name__ == "__main__":
    main()

