def freezing_days(temperatures):
    below = []
    for index, temperature in enumerate(temperatures):
        if temperature is not None and temperature < 0:
            below.append(index)
    return below


def running_average_breach(temperatures):
    total = 0.0
    counted = 0
    for index, temperature in enumerate(temperatures):
        if temperature is None:
            continue
        total += temperature
        counted += 1
        if total / counted > 40:
            return index
    return None


def sharp_drops(temperatures):
    positions = []
    previous = None
    for index, temperature in enumerate(temperatures):
        if temperature is None:
            continue
        if previous is not None and previous - temperature > 10:
            positions.append(index)
        previous = temperature
    return positions


def first_zero(temperatures):
    for index, temperature in enumerate(temperatures):
        if temperature == 0:
            return index
    return None


def missing_or_negative(temperatures):
    flagged = []
    for index, temperature in enumerate(temperatures):
        if temperature is None or temperature < 0:
            flagged.append(index)
    return flagged


def numbered_readings(temperatures):
    lines = []
    number = 0
    for index, temperature in enumerate(temperatures):
        if temperature is not None and temperature >= 0:
            number += 1
            lines.append("{}. day {} reading {} degrees".format(number, index, temperature))
    return lines


def number_anomalies(anomalies):
    report = []
    for number, description in enumerate(anomalies, start=1):
        report.append("Anomaly {}: {}".format(number, description))
    return report


def reading_summary(temperatures):
    pairs = []
    for sequence, temperature in enumerate(temperatures, start=1):
        label = "missing" if temperature is None else "{} degrees".format(temperature)
        pairs.append("Day {}: {}".format(sequence, label))
    return pairs


def format_report(lines):
    formatted = []
    for position, line in enumerate(lines, start=1):
        formatted.append("{:>2} | {}".format(position, line))
    return formatted


def validate(temperatures):
    anomalies = []
    for index in freezing_days(temperatures):
        anomalies.append("day {} is below freezing".format(index))
    for index in sharp_drops(temperatures):
        anomalies.append("day {} dropped more than ten degrees".format(index))
    for index in missing_or_negative(temperatures):
        anomalies.append("day {} has a missing or negative reading".format(index))

    report = []
    breach = running_average_breach(temperatures)
    if breach is not None:
        report.append("Running average exceeded forty degrees at index {}".format(breach))
    zero_index = first_zero(temperatures)
    if zero_index is not None:
        report.append("First zero reading at index {}".format(zero_index))
    report.extend(reading_summary(temperatures))
    report.extend(numbered_readings(temperatures))
    report.extend(number_anomalies(anomalies))
    return report


def main():
    for line in format_report(validate([20, 50, -5])):
        print(line)


if __name__ == "__main__":
    main()

