VALID = ("strongly agree", "agree", "neutral", "disagree", "strongly disagree", "none")


def normalize(answers):
    cleaned = []
    for i, answer in enumerate(answers):
        if not isinstance(answer, str):
            raise TypeError("answer %d is not a string" % i)
        cleaned.append(answer.strip().lower())
    return cleaned


def find_strongly_agree(answers):
    positions = []
    for i, answer in enumerate(answers):
        if answer == "strongly agree":
            positions.append(i)
    return positions


def find_first_strongly_disagree(answers):
    for i, answer in enumerate(answers):
        if answer == "strongly disagree":
            return i
    return -1


def find_skipped(answers):
    skipped = []
    for i, answer in enumerate(answers):
        if answer == "none":
            skipped.append(i)
    return skipped


def find_invalid(answers):
    invalid = []
    for i, answer in enumerate(answers):
        if answer not in VALID:
            invalid.append((i, answer))
    return invalid


def find_three_neutral_run(answers):
    run = 0
    for i, answer in enumerate(answers):
        run = run + 1 if answer == "neutral" else 0
        if run == 3:
            return i
    return -1


def build_transcript(answers):
    transcript = []
    number = 0
    for i, answer in enumerate(answers):
        if answer in VALID and answer != "none":
            number += 1
            transcript.append("%d. Q%d: %s" % (number, i, answer))
    return transcript


def number_skipped(skipped):
    return ["Follow up %d: question %d was skipped" % (n + 1, q)
            for n, q in enumerate(skipped)]


def format_summary(answers):
    summary = []
    for i, answer in enumerate(answers):
        label = answer if answer in VALID else "invalid (%s)" % answer
        summary.append("Question %d: %s" % (i, label))
    return summary


def score(answers):
    cleaned = normalize(answers)
    find_strongly_agree(cleaned)
    find_first_strongly_disagree(cleaned)
    skipped = find_skipped(cleaned)
    find_invalid(cleaned)
    find_three_neutral_run(cleaned)
    build_transcript(cleaned)
    number_skipped(skipped)
    return format_summary(cleaned)


def main():
    responses = ["agree", "neutral", "none", "strongly agree", "neutral",
                 "neutral", "neutral", "maybe", "strongly disagree", "none"]
    cleaned = normalize(responses)
    print("Strongly agree at:", find_strongly_agree(cleaned))
    print("First strongly disagree at:", find_first_strongly_disagree(cleaned))
    print("Three neutral in a row ends at:", find_three_neutral_run(cleaned))
    for position, text in enumerate(find_invalid(cleaned)):
        print("Invalid entry %d -> question %d says %r" % (position, text[0], text[1]))
    for line in build_transcript(cleaned):
        print(line)
    for line in number_skipped(find_skipped(cleaned)):
        print(line)
    for line in score(responses):
        print(line)


if __name__ == "__main__":
    main()

