"""Review a sequence of order quantities with a set of focused checkers."""


def find_bulk_orders(quantities):
    """Indices of orders larger than fifty units."""
    bulk = []
    for index, quantity in enumerate(quantities):
        if quantity > 50:
            bulk.append(index)
    return bulk


def find_first_zero(quantities):
    """Position of the first zero-quantity order, or None."""
    for index, quantity in enumerate(quantities):
        if quantity == 0:
            return index
    return None


def find_total_breach(quantities):
    """Index at which the running total passes five hundred items."""
    running = 0
    for index, quantity in enumerate(quantities):
        running += quantity
        if running > 500:
            return index
    return None


def find_repeats(quantities):
    """Positions whose quantity equals the previous order's quantity."""
    repeats = []
    for index, quantity in enumerate(quantities):
        if index and quantity == quantities[index - 1]:
            repeats.append(index)
    return repeats


def find_refunds(quantities):
    """Positions holding negative quantities (refunds)."""
    return [index for index, quantity in enumerate(quantities) if quantity < 0]


def build_packing_slip(quantities):
    """Numbered packing slip lines for standard (positive, non-bulk) orders."""
    slip = []
    for index, quantity in enumerate(quantities):
        if 0 < quantity <= 50:
            slip.append("%d. order #%d: pack %d unit(s)" % (len(slip) + 1, index, quantity))
    return slip


def build_bulk_alerts(quantities, bulk_indices):
    """Sequentially numbered alerts for each bulk order."""
    alerts = []
    for number, index in enumerate(bulk_indices, start=1):
        alerts.append("ALERT %d: order #%d requests %d units" % (number, index, quantities[index]))
    return alerts


def build_audit_log(quantities):
    """Pair every order quantity with its sequence index."""
    log = []
    for index, quantity in enumerate(quantities):
        log.append("seq %03d | qty %d" % (index, quantity))
    return log


def detect(quantities):
    bulk_indices = find_bulk_orders(quantities)
    print("bulk orders:", bulk_indices)
    print("first zero order:", find_first_zero(quantities))
    print("total breach at:", find_total_breach(quantities))
    print("repeated quantities:", find_repeats(quantities))
    print("refunds:", find_refunds(quantities))
    for line in build_packing_slip(quantities):
        print(line)
    for line in build_bulk_alerts(quantities, bulk_indices):
        print(line)
    return build_audit_log(quantities)


def main():
    orders = [10, 0, -5, 60, 60, 200, 300, 40]
    audit_log = detect(orders)
    for position, entry in enumerate(audit_log):
        print("audit[%d]: %s" % (position, entry))


if __name__ == "__main__":
    main()

