def derivative(coefficients):
    result = []
    for degree, coefficient in enumerate(coefficients):
        result.append(coefficient * degree)
    return result


def integral(coefficients):
    result = []
    for degree, coefficient in enumerate(coefficients):
        result.append(coefficient / (degree + 1))
    return result


def evaluate_at_two(coefficients):
    total = 0
    for degree, coefficient in enumerate(coefficients):
        total += coefficient * (2 ** degree)
    return total


def format_polynomial(coefficients):
    terms = []
    for degree, coefficient in enumerate(coefficients):
        if degree == 0:
            terms.append(str(coefficient))
        elif degree == 1:
            terms.append("{}x".format(coefficient))
        else:
            terms.append("{}x^{}".format(coefficient, degree))
    return " + ".join(terms)


def shift_degrees(coefficients):
    shifted = [0] * (len(coefficients) + 1)
    for degree, coefficient in enumerate(coefficients):
        shifted[degree + 1] = coefficient
    return shifted


def zero_indices(coefficients):
    indices = []
    for degree, coefficient in enumerate(coefficients):
        if coefficient == 0:
            indices.append(degree)
    return indices


def weighted_polynomial(coefficients):
    weighted = []
    for degree, coefficient in enumerate(coefficients):
        weighted.append(coefficient + degree)
    return weighted


def leading_degree(coefficients):
    highest = -1
    for degree, coefficient in enumerate(coefficients):
        if coefficient != 0:
            highest = degree
    return highest


def calculate(polynomials):
    if not polynomials:
        raise ValueError("at least one polynomial is required")
    coefficients = polynomials[0]
    return (derivative(coefficients), integral(coefficients),
            evaluate_at_two(coefficients), format_polynomial(coefficients),
            shift_degrees(coefficients), zero_indices(coefficients),
            weighted_polynomial(coefficients), leading_degree(coefficients))


def main():
    labels = ["derivative", "integral", "value at 2", "formatted",
              "shifted", "zero indices", "weighted", "leading degree"]
    results = calculate([[1, 2, 3], [0, 5]])
    for position, value in enumerate(results):
        print("{}. {}: {}".format(position + 1, labels[position], value))


if __name__ == "__main__":
    main()

