TERM = "search"


def build_inverted_index(documents):
    index = {}
    for doc_id, document in enumerate(documents):
        for raw_word in document.lower().split():
            word = raw_word.strip(".,;:!?\"'()[]")
            if not word:
                continue
            postings = index.setdefault(word, [])
            if doc_id not in postings:
                postings.append(doc_id)
    return index


def format_results(doc_indices):
    lines = []
    for rank, doc_id in enumerate(doc_indices, start=1):
        lines.append("{0}. document {1}".format(rank, doc_id))
    return lines


def relevance_scores(documents, term):
    scores = []
    for position, document in enumerate(documents):
        hits = document.lower().split().count(term)
        scores.append((position, round(hits / (1.0 + position), 4)))
    return scores


def highlight_matches(documents, term):
    highlights = []
    for doc_id, document in enumerate(documents):
        words = document.split()
        for word_index, word in enumerate(words):
            if word.lower().strip(".,;:!?\"'()[]") != term:
                continue
            start = max(0, word_index - 2)
            snippet = " ".join(words[start:word_index] + ["[" + word + "]"] + words[word_index + 1:word_index + 3])
            highlights.append((doc_id, word_index, snippet))
    return highlights


def find_empty_documents(documents):
    return [doc_id for doc_id, document in enumerate(documents) if not document.strip()]


def summarize_first_words(documents):
    summary = []
    for doc_id, document in enumerate(documents):
        words = document.split()
        summary.append((words[0] if words else "", doc_id))
    return summary


def find_long_documents(documents):
    positions = []
    for doc_id, document in enumerate(documents):
        if len(document.split()) > 100:
            positions.append(doc_id)
    return positions


def build_citations(documents):
    citations = []
    for doc_id, document in enumerate(documents):
        words = document.split()
        title = " ".join(words[:5]) if words else "untitled"
        citations.append("[{0}] {1}".format(doc_id, title))
    return citations


def search(documents):
    inverted_index = build_inverted_index(documents)
    matches = inverted_index.get(TERM, [])
    return (
        inverted_index,
        format_results(matches),
        relevance_scores(documents, TERM),
        highlight_matches(documents, TERM),
        find_empty_documents(documents),
        summarize_first_words(documents),
        find_long_documents(documents),
        build_citations(documents),
    )


def main():
    corpus = [
        "hello world",
        "",
        "full text search engines rank each search result by relevance",
        " ".join("token%d" % n for n in range(120)) + " search",
    ]
    analysis = search(corpus)
    labels = (
        "inverted index",
        "ranked results",
        "relevance scores",
        "highlights",
        "empty documents",
        "first-word summary",
        "long documents",
        "citations",
    )
    for section, label in enumerate(labels, start=1):
        print("{0}) {1}: {2}".format(section, label, analysis[section - 1]))


if __name__ == "__main__":
    main()

