def validate_counts(counts):
    """Return the counts as a list of ints, rejecting invalid hourly readings."""
    checked = []
    for hour, count in enumerate(counts):
        if not isinstance(count, (int, float)) or isinstance(count, bool):
            raise TypeError("hour %d holds a non-numeric count: %r" % (hour, count))
        if count < 0:
            raise ValueError("hour %d holds a negative count: %r" % (hour, count))
        checked.append(int(count))
    return checked


def busy_hours(counts, threshold=1000):
    """Hour indices whose count exceeds the threshold."""
    return [hour for hour, count in enumerate(counts) if count > threshold]


def cumulative_traffic(counts):
    """Running total of traffic up to and including each hour index."""
    totals = []
    running = 0
    for hour, count in enumerate(counts):
        running += count
        totals.append(running)
    return totals


def apply_night_reduction(counts, factor=0.6):
    """Scale down counts recorded at hour indices 0 through 6."""
    adjusted = []
    for hour, count in enumerate(counts):
        if 0 <= hour <= 6:
            adjusted.append(int(round(count * factor)))
        else:
            adjusted.append(count)
    return adjusted


def traffic_spikes(counts):
    """Hour indices whose count is above both the preceding and following hour."""
    spikes = []
    for hour, count in enumerate(counts):
        if 0 < hour < len(counts) - 1 and count > counts[hour - 1] and count > counts[hour + 1]:
            spikes.append(hour)
    return spikes


def hourly_report(counts):
    """One formatted line per hour index."""
    lines = []
    for hour, count in enumerate(counts):
        lines.append("Hour %02d: %5d vehicles" % (hour, count))
    return lines


def predict_next_day(counts):
    """Map each hour index shifted 24 hours forward to its expected count."""
    forecast = {}
    for hour, count in enumerate(counts):
        forecast[hour + 24] = count
    return forecast


def group_into_blocks(counts, size=4):
    """Group counts into blocks of `size` hours, tagged with the block index."""
    blocks = []
    for hour, count in enumerate(counts):
        block_index = hour // size
        if block_index == len(blocks):
            blocks.append((block_index, []))
        blocks[block_index][1].append(count)
    return blocks


def quietest_hour(counts):
    """Hour index of the absolute lowest traffic, or None for no data."""
    best_hour = None
    for hour, count in enumerate(counts):
        if best_hour is None or count < counts[best_hour]:
            best_hour = hour
    return best_hour


def monitor(counts):
    clean = validate_counts(counts)
    return (busy_hours(clean), cumulative_traffic(clean), apply_night_reduction(clean),
            traffic_spikes(clean), hourly_report(clean), predict_next_day(clean),
            group_into_blocks(clean), quietest_hour(clean))


def main():
    busy, totals, night, spikes, report, forecast, blocks, quiet = monitor([500, 1500, 800])
    print("busy hours:", busy, "spikes:", spikes, "quietest hour:", quiet)
    print("cumulative:", totals, "night-adjusted:", night)
    for line in report:
        print(line)
    for index, (block_index, values) in enumerate(blocks):
        print("block %d (position %d): %s" % (block_index, index, values))
    for hour in sorted(forecast):
        print("forecast hour %02d: %d vehicles" % (hour, forecast[hour]))


if __name__ == "__main__":
    main()

