def index_map(plants):
    mapping = {}
    for i, name in enumerate(plants):
        mapping[name] = i
    return mapping

def find_cactus(plants):
    for i, name in enumerate(plants):
        if name == "cactus":
            return i
    return -1

def tag_with_index(plants):
    tagged = []
    for i, name in enumerate(plants):
        tagged.append(name + "-" + str(i))
    return tagged

def odd_positions(plants):
    kept = []
    for i, name in enumerate(plants):
        if i % 2 == 1:
            kept.append(name)
    return kept

def longest_index(plants):
    best = -1
    best_len = -1
    for i, name in enumerate(plants):
        if len(name) > best_len:
            best_len = len(name)
            best = i
    return best

def prefix_with_index(plants):
    labelled = []
    for i, name in enumerate(plants):
        labelled.append(str(i) + ":" + name)
    return labelled

def count_length_matches(plants):
    matches = 0
    for i, name in enumerate(plants):
        if len(name) == i:
            matches += 1
    return matches

def pair_with_index(plants):
    return [(name, i) for i, name in enumerate(plants)]

def catalog(zones):
    if len(zones) != 8:
        raise ValueError("expected eight zone lists")
    handlers = (index_map, find_cactus, tag_with_index, odd_positions,
                longest_index, prefix_with_index, count_length_matches,
                pair_with_index)
    results = []
    for i, handler in enumerate(handlers):
        results.append(handler(zones[i]))
    return tuple(results)

def report(zones):
    names = ("tropical", "desert", "temperate", "tundra", "aquatic",
             "alpine", "carnivorous", "medicinal")
    lines = []
    for i, value in enumerate(catalog(zones)):
