def pair_with_index(events):
    pairs = []
    for i in range(len(events)):
        pairs.append((events[i], i + 1))
    return pairs


def map_to_hundreds(events):
    scaled = {}
    for i in range(len(events)):
        scaled[events[i]] = (i + 1) * 100
    return scaled


def prefix_with_index(events):
    labelled = []
    for i in range(len(events)):
        labelled.append("{}-{}".format(i + 1, events[i]))
    return labelled


def find_art_index(events):
    for i in range(len(events)):
        if "art" in events[i].lower():
            return i + 1
    return None


def keep_odd_positions(events):
    return [events[i] for i in range(len(events)) if (i + 1) % 2 == 1]


def suffix_with_index(events):
    return ["{}:{}".format(events[i], i + 1) for i in range(len(events))]


def shortest_index(events):
    best_index = None
    best_length = None
    for i in range(len(events)):
        if best_length is None or len(events[i]) < best_length:
            best_index = i + 1
            best_length = len(events[i])
    return best_index


def index_to_event(events):
    catalogue = {}
    for i in range(len(events)):
        catalogue[i + 1] = events[i]
    return catalogue


def build(eras):
    if len(eras) != 8:
        raise ValueError("expected eight era lists, got {}".format(len(eras)))
    handlers = (
        pair_with_index,
        map_to_hundreds,
        prefix_with_index,
        find_art_index,
        keep_odd_positions,
        suffix_with_index,
        shortest_index,
        index_to_event,
    )
    results = []
    for i in range(len(handlers)):
        results.append(handlers[i](eras[i]))
