DEPARTMENTS = (
    "trauma", "pediatrics", "cardiology", "neurology",
    "oncology", "orthopedics", "radiology", "pharmacy",
)


def validate(departments):
    if len(departments) != len(DEPARTMENTS):
        raise ValueError("expected eight patient lists")
    for position, patients in enumerate(departments):
        if not isinstance(patients, list):
            raise TypeError("%s roster must be a list" % DEPARTMENTS[position])


def tag_triage(patients):
    return ["%s%d" % (surname, index) for index, surname in enumerate(patients, start=1)]


def find_first_smith(patients):
    for index, surname in enumerate(patients, start=1):
        if surname == "Smith":
            return index
    return None


def map_cardiology(patients):
    return {index: surname for index, surname in enumerate(patients, start=1)}


def filter_neurology(patients):
    kept = []
    for index, surname in enumerate(patients, start=1):
        if index % 4:
            kept.append(surname)
    return kept


def wristbands(patients):
    return ["#%d %s" % (index, surname) for index, surname in enumerate(patients, start=1)]


def ortho_pairs(patients):
    return [(index, surname) for index, surname in enumerate(patients, start=1)]


def shortest_radiology(patients):
    best_index = None
    best_length = None
    for index, surname in enumerate(patients, start=1):
        if best_length is None or len(surname) < best_length:
            best_index, best_length = index, len(surname)
    return best_index


def pharmacy_ids(patients):
    ids = {}
    for index, surname in enumerate(patients, start=1):
        ids[index] = "RX-%03d-%s" % (index, surname[:3].upper())
    return ids


def coordinate(departments):
    validate(departments)
    trauma, pediatrics, cardiology, neurology, oncology, orthopedics, radiology, pharmacy = departments
    return (
        tag_triage(trauma),
        find_first_smith(pediatrics),
        map_cardiology(cardiology),
        filter_neurology(neurology),
        wristbands(oncology),
        ortho_pairs(orthopedics),
        shortest_radiology(radiology),
        pharmacy_ids(pharmacy),
    )


def report(results):
    lines = []
    for position, outcome in enumerate(results):
        lines.append("%d. %-12s %s" % (position + 1, DEPARTMENTS[position], outcome))
    return "\n".join(lines)


