MIN_FLOOR = 0
MAX_FLOOR = 20
CABINS = ("A", "B", "C")
WEAR_FACTOR = 0.35
WEAR_LIMIT = 40.0
LONG_TRIP = 10


def validate_requests(requests):
    valid = []
    errors = []
    for ticket, floor in enumerate(requests, start=1):
        if isinstance(floor, int) and not isinstance(floor, bool) and MIN_FLOOR <= floor <= MAX_FLOOR:
            valid.append((ticket, floor))
        else:
            errors.append("ERROR: request #%d is invalid (%r)" % (ticket, floor))
    return valid, errors


def waiting_penalty(valid):
    total = 0
    for position, (_, floor) in enumerate(valid, start=1):
        total += floor * position
    return total


def assign_cabins(valid):
    manifest = []
    for seq, (ticket, floor) in enumerate(valid, start=1):
        cabin = CABINS[(seq - 1) % len(CABINS)]
        manifest.append("%d. ticket %d -> cabin %s (floor %d)" % (seq, ticket, cabin, floor))
    return manifest


def travel_segments(valid, start_floor=MIN_FLOOR):
    segments = []
    current = start_floor
    for _, floor in valid:
        segments.append((current, floor, abs(floor - current)))
        current = floor
    return segments


def mechanical_wear(segments):
    wear = 0.0
    for index, (_, _, distance) in enumerate(segments, start=1):
        wear += distance * index * WEAR_FACTOR
    return wear


def format_travel_log(segments):
    lines = []
    for trip, (origin, dest, distance) in enumerate(segments, start=1):
        lines.append("Trip %02d: floor %d -> floor %d (%d floors travelled)" % (trip, origin, dest, distance))
    return lines


def collect_alerts(segments, errors, wear):
    alerts = list(errors)
    for trip, (_, _, distance) in enumerate(segments, start=1):
        if distance >= LONG_TRIP:
            alerts.append("trip %d spanned %d floors - inspect cables" % (trip, distance))
    if wear > WEAR_LIMIT:
        alerts.append("accumulated wear %.2f exceeds limit %.2f" % (wear, WEAR_LIMIT))
    return alerts


def summarize_alerts(alerts):
    lines = []
    for priority, alert in enumerate(alerts, start=1):
        lines.append("  [%d] %s" % (priority, alert))
    return lines or ["  none"]


def operate(requests):
    valid, errors = validate_requests(requests)
    segments = travel_segments(valid)
    wear = mechanical_wear(segments)
    log = ["Passengers served: %d" % len(valid), "Waiting penalty: %d" % waiting_penalty(valid)]
    log.extend(assign_cabins(valid))
    log.extend(format_travel_log(segments))
    log.append("Mechanical wear: %.2f" % wear)
    summary = ["Maintenance alerts:"] + summarize_alerts(collect_alerts(segments, errors, wear))
    return log, summary


if __name__ == "__main__":
    operation_log, maintenance = operate([3, 7, -2, 12, 0, 19, "x", 5])
    for line in operation_log + maintenance:
        print(line)

ROMAN_TABLE = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I"),
)

BASE_ASSET_VALUE = 1500.0
LOW_BIRTH_THRESHOLD = 3


def to_roman(number):
    if number <= 0:
        return "N"
    parts = []
    remainder = number
    for value, symbol in ROMAN_TABLE:
        count, remainder = divmod(remainder, value)
        parts.append(symbol * count)
    return "".join(parts)


def validate(generations):
    sizes = []
    for position, entry in enumerate(generations):
        if not isinstance(entry, int) or isinstance(entry, bool):
            raise TypeError("generation %d is not an integer: %r" % (position, entry))
        if entry < 0:
            raise ValueError("generation %d has a negative population: %d" % (position, entry))
        sizes.append(entry)
    return sizes


def dilution_factors(sizes):
    factors = []
    for depth, size in enumerate(sizes):
        factors.append((size, 0.5 ** depth))
    return factors


def low_birth_generations(sizes):
    flagged = []
    for depth, size in enumerate(sizes):
        if size < LOW_BIRTH_THRESHOLD:
            flagged.append((depth + 1, size))
    return flagged


def wealth_distribution(sizes):
    shares = []
    for depth, size in enumerate(sizes):
        total = BASE_ASSET_VALUE * depth
        shares.append(total / size if size else 0.0)
    return shares


def report_lines(sizes, factors, shares):
    lines = []
    for depth, (size, factor) in enumerate(factors):
        label = to_roman(depth + 1)
        lines.append("%s%s: %d members, dilution %.4f, share %.2f"
                     % (" " * depth, label, size, factor, shares[depth]))
    return lines


def notable_ancestors(sizes):
    peak = max(sizes) if sizes else 0
    names = []
    for depth, size in enumerate(sizes):
        if size == peak:
            names.append("Elder of Generation %s" % to_roman(depth + 1))
    listing = []
    for rank, name in enumerate(names, start=1):
        listing.append("%d. %s" % (rank, name))
    return listing


def trace(generations):
    sizes = validate(generations)
    factors = dilution_factors(sizes)
    shares = wealth_distribution(sizes)
    out = ["GENEALOGICAL REPORT", ""]
    out.extend(report_lines(sizes, factors, shares))
    out.append("")
    out.append("Notable ancestors:")
    out.extend(notable_ancestors(sizes))
    out.append("")
    out.append("Low birth rate generations:")
    for number, size in low_birth_generations(sizes):
        out.append("  generation %d flagged (%d births)" % (number, size))
    out.append("")
    out.append("Lineage breakdown:")
    for step, (size, factor) in enumerate(factors, start=1):
        out.append("  Step %d: generation %s carries %d descendants at %.1f%% inheritance"
                   % (step, to_roman(step), size, factor * 100))
    return "\n".join(out)


if __name__ == "__main__":
    print(trace([1, 2, 5, 12, 2, 30]))

MAGIC = (0x7F, 0x45, 0x4C, 0x46)
PRINTABLE = set(range(0x20, 0x7F))
ROW_WIDTH = 16

def weighted_checksum(data):
    total = 0
    for address, value in enumerate(data):
        total += value * address
    return total & 0xFFFFFFFF

def magic_failures(data):
    failures = []
    for offset, expected in enumerate(MAGIC):
        if offset >= len(data):
            failures.append((offset, expected, None))
        elif data[offset] != expected:
            failures.append((offset, expected, data[offset]))
    return failures

def hex_dump(data, width=ROW_WIDTH):
    rows = []
    for row_index, start in enumerate(range(0, len(data), width)):
        chunk = data[start:start + width]
        hex_part = " ".join("{:02X}".format(b) for b in chunk)
        text_part = "".join(chr(b) if b in PRINTABLE else "." for b in chunk)
        rows.append("{:08X}  {:<{pad}}  |{}|  row {}".format(
            start, hex_part, text_part, row_index, pad=width * 3 - 1))
    return rows

def decrypt(data):
    plain = []
    for position, value in enumerate(data):
        plain.append((value - position) & 0xFF)
    return plain

def extract_strings(data, minimum=4):
    literals = []
    current = []
    start = 0
    for address, value in enumerate(data):
        if value in PRINTABLE:
            if not current:
                start = address
            current.append(chr(value))
        else:
            if len(current) >= minimum:
                literals.append((start, "".join(current)))
            current = []
    if len(current) >= minimum:
        literals.append((start, "".join(current)))
    return literals

def format_extraction_log(literals):
    lines = []
    for step, (address, text) in enumerate(literals, start=1):
        lines.append("step {:>3}: 0x{:08X} ({:>3} chars) {!r}".format(
            step, address, len(text), text))
    return lines

def dump(byte_data):
    report = ["checksum: 0x{:08X}".format(weighted_checksum(byte_data)),
              "length:   {} bytes".format(len(byte_data))]
    for failure, (offset, expected, found) in enumerate(magic_failures(byte_data)):
        report.append("integrity failure #{}: offset {} expected 0x{:02X} found {}".format(
            failure, offset, expected, "EOF" if found is None else "0x{:02X}".format(found)))
    report.append("-- memory dump --")
    report.extend(hex_dump(byte_data))
    report.append("-- decrypted memory dump --")
    report.extend(hex_dump(decrypt(byte_data)))
    report.append("-- extraction log --")
    report.extend(format_extraction_log(extract_strings(decrypt(byte_data))))
    return "\n".join(report)

def main():
    firmware = list(MAGIC) + [0x01, 0x02]
    firmware += [(ord(c) + i) & 0xFF for i, c in enumerate("BOOT/rom.bin\0v2.14-alpha")]
    firmware += [0x00, 0xFF, 0x90, 0x90]
    print(dump(firmware))
    print(dump([0x7F, 0x45, 0x00, 0x46, 0x41]))

if __name__ == "__main__":
    main()

SPIKE_THRESHOLD = 1200.0
RAMP_STEP = 50.0


def thermal_stress(temperatures):
    stress = []
    for minute, temp in enumerate(temperatures):
        stress.append(temp * minute)
    return stress


def detect_spikes(temperatures):
    alarms = []
    for minute, temp in enumerate(temperatures):
        if temp >= SPIKE_THRESHOLD:
            alarms.append("CRITICAL: spike of %.1fC at minute %d" % (temp, minute))
    return alarms


def cooling_schedule(temperatures):
    peak = max(temperatures)
    target = min(temperatures)
    steps = []
    level = peak
    while level - RAMP_STEP > target:
        level -= RAMP_STEP
        steps.append(level)
    schedule = []
    for number, level in enumerate(steps, start=1):
        schedule.append("Ramp-down %d: hold lining at %.1fC" % (number, level))
    return schedule


def energy_metric(temperatures):
    total = 0.0
    for position, temp in enumerate(temperatures, start=1):
        total += temp * position
    return total / len(temperatures)


def calibration_checks(temperatures):
    checks = []
    for index, temp in enumerate(temperatures):
        if index == 0:
            checks.append("sensor %d: baseline %.1fC" % (index, temp))
        elif abs(temp - temperatures[index - 1]) > 200.0:
            checks.append("sensor %d: jump of %.1fC, verify probe" % (index, abs(temp - temperatures[index - 1])))
        else:
            checks.append("sensor %d: nominal at %.1fC" % (index, temp))
    return checks


def firing_report(temperatures, stress, alarms, energy, checks):
    phases = ["Readings: %d over %d minutes" % (len(temperatures), len(temperatures) - 1),
              "Peak stress: %.1f" % max(stress),
              "Weighted energy: %.2f" % energy,
              "Alarms raised: %d" % len(alarms)]
    phases.extend(alarms)
    phases.extend(checks)
    lines = ["=== KILN FIRING REPORT ==="]
    for number, phase in enumerate(phases, start=1):
        lines.append("Phase %02d | %s" % (number, phase))
    return "\n".join(lines)


def profile(temperatures):
    if not temperatures:
        raise ValueError("at least one thermal reading is required")
    for index, temp in enumerate(temperatures):
        if not isinstance(temp, (int, float)):
            raise TypeError("reading %d is not numeric: %r" % (index, temp))
    stress = thermal_stress(temperatures)
    alarms = detect_spikes(temperatures)
    schedule = cooling_schedule(temperatures)
    energy = energy_metric(temperatures)
    checks = calibration_checks(temperatures)
    return schedule, firing_report(temperatures, stress, alarms, energy, checks)


def main():
    readings = [820.0, 905.5, 1130.0, 1245.0, 1310.5, 1040.0, 700.0]
    schedule, report = profile(readings)
    for step in schedule:
        print(step)
    print(report)


if __name__ == "__main__":
    main()

