INSTABILITY_LIMIT = 4.0
FROZEN_LAYER_JUMP = 0.35


def validate_depths(depths):
    clean = []
    for index, value in enumerate(depths):
        try:
            depth = float(value)
        except (TypeError, ValueError):
            raise ValueError("reading %d is not a number: %r" % (index, value))
        if depth < 0:
            raise ValueError("reading %d is negative: %r" % (index, depth))
        clean.append(depth)
    return clean


def zone_profile(depths):
    zones = []
    for position, depth in enumerate(depths):
        incline = 1.0 + 0.15 * position
        zones.append({
            "zone": position + 1,
            "depth": depth,
            "incline": incline,
            "risk": depth * incline,
        })
    return zones


def detonation_warnings(depths):
    warnings = []
    for zone, previous in enumerate(depths[:-1], start=1):
        jump = depths[zone] - previous
        if jump >= FROZEN_LAYER_JUMP:
            warnings.append(
                "DETONATION ADVISED: frozen layer of %.2f m detected entering zone %d"
                % (jump, zone + 1)
            )
    return warnings


def patrol_route(zones):
    route = []
    for number, zone in enumerate(zones, start=1):
        route.append(
            "Checkpoint %d -> zone %d: depth %.2f m, risk index %.2f"
            % (number, zone["zone"], zone["depth"], zone["risk"])
        )
    return route


def wind_loading(depths):
    weighted = 0.0
    divisor = 0
    for hour, depth in enumerate(depths, start=1):
        weighted += depth * hour
        divisor += hour
    return weighted / divisor if divisor else 0.0


def closed_trails(zones):
    closures = []
    unstable = [zone for zone in zones if zone["risk"] >= INSTABILITY_LIMIT]
    for number, zone in enumerate(unstable, start=1):
        closures.append("%d. Trail in zone %d (risk %.2f) is CLOSED"
                        % (number, zone["zone"], zone["risk"]))
    return closures


def broadcast(advisories):
    lines = ["PUBLIC SAFETY BROADCAST"]
    for number, advisory in enumerate(advisories, start=1):
        lines.append("Advisory %d: %s" % (number, advisory))
    return "\n".join(lines)


def monitor(depths):
    readings = validate_depths(depths)
    zones = zone_profile(readings)
    route = patrol_route(zones)
    advisories = detonation_warnings(readings)
    advisories.append("Wind loading metric: %.2f" % wind_loading(readings))
    advisories.extend(closed_trails(zones))
    if len(advisories) == 1:
        advisories.append("No closures: all zones within safe limits")
    return route, broadcast(advisories)


def main():
    plan, report = monitor([0.4, 0.55, 1.1, 1.3, 2.4, 2.5])
    for line in plan:
        print(line)
    print(report)


if __name__ == "__main__":
    main()

