    for hour in range(1, len(depths) + 1):
        weighted += depths[hour - 1] * hour
        divisor += hour
    return weighted / divisor if divisor else 0.0


def closed_trails(zones):
    closures = []
    unstable = [zone for zone in zones if zone["risk"] >= INSTABILITY_LIMIT]
    for number in range(1, len(unstable) + 1):
        closures.append("%d. Trail in zone %d (risk %.2f) is CLOSED"
                        % (number, unstable[number - 1]["zone"], unstable[number - 1]["risk"]))
    return closures


def broadcast(advisories):
    lines = ["PUBLIC SAFETY BROADCAST"]
    for number in range(1, len(advisories) + 1):
        lines.append("Advisory %d: %s" % (number, advisories[number - 1]))
    return "\n".join(lines)


def monitor(depths):
    readings = validate_depths(depths)
    zones = zone_profile(readings)
    route = patrol_route(zones)
    advisories = detonation_warnings(readings)
    advisories.append("Wind loading metric: %.2f" % wind_loading(readings))
    advisories.extend(closed_trails(zones))
    if len(advisories) == 1:
        advisories.append("No closures: all zones within safe limits")
    return route, broadcast(advisories)


