    return invalid_indices, triple_index


def weigh_skills(skills):
    total = 0
    for k, skill in enumerate(skills):
        total += len(skill) * k

    labels = []
    for n, skill in enumerate(skills):
        labels.append("{}: {}".format(n, skill))

    return total, labels


def compare_skills(skills, baseline):
    mismatches = []
    for p, skill in enumerate(skills):
        if p >= len(baseline) or baseline[p] != skill:
            mismatches.append(p)

    repeats = []
    for q, skill in enumerate(skills[:-1]):
        if skills[q + 1] == skill:
            repeats.append(q)

    return mismatches, repeats


