            mismatches.append(p)
    for q in range(len(splits), len(splits) + len(baseline[len(splits):])):
        mismatches.append(q)
    repeats = []
    for r in range(len(splits[:-1])):
        if splits[:-1][r] == splits[r + 1]:
            repeats.append(r)
    return mismatches, repeats


def describe_items(splits):
    parities = []
    for s in range(len(splits)):
        parities.append(s % 2)
    initials = []
    for t in range(len(splits)):
        initials.append((t, splits[t][0] if splits[t] else ""))
    long_items = []
    for u in range(len(splits)):
        if len(splits[u]) > 10:
            long_items.append(u)
    return parities, initials, long_items


def evaluate(splits, baseline):
    disqualified, sprint_index = scan_flags(splits)
    score, labels = score_and_label(splits)
    mismatches, repeats = compare_to_baseline(splits, baseline)
    parities, initials, long_items = describe_items(splits)
    return (disqualified, sprint_index, score, labels, mismatches,
            repeats, parities, initials, long_items)


def main():
    splits = ["sprint start", "lap one", "lap one", "disqualified rider",
              "final stretch home"]
    baseline = ["sprint start", "lap one", "lap two", "disqualified rider",
                "final stretch home"]
    result = evaluate(splits, baseline)
    names = ("disqualified", "sprint_index", "score", "labels", "mismatches",
             "repeats", "parities", "initials", "long_items")
    for v in range(len(result)):
        print("{} = {}".format(names[v], result[v]))


if __name__ == "__main__":
    main()

