import string

SECTIONS = (
    "lines", "branches", "stations", "platforms",
    "tracks", "turnstiles", "escalators", "exits",
)


def _letter(index):
    label = ""
    value = index + 1
    while value:
        value, rem = divmod(value - 1, 26)
        label = string.ascii_uppercase[rem] + label
    return label


def map(network):
    if len(network) != len(SECTIONS):
        raise ValueError("network must contain %d sublists" % len(SECTIONS))
    lines, branches, stations, platforms, tracks, turnstiles, escalators, exits = network
    entries = []

    for i, line in enumerate(lines):
        entries.append("Line %s: color code %d" % (line, i + 1))

    for i, branch in enumerate(branches):
        entries.append("Branch %s: letter %s" % (branch, _letter(i)))

    for i, station in enumerate(stations):
        entries.append("Station %s: stop number %d" % (station, i + 1))

    for i, platform in enumerate(platforms):
        entries.append("Platform %s: identifier P%02d" % (platform, i + 1))

    for i, track in enumerate(tracks):
        entries.append("Track %s: track number %d" % (track, i + 1))

    for i, turnstile in enumerate(turnstiles):
        entries.append("Turnstile %s: gate %d" % (turnstile, i + 1))

    for i, escalator in enumerate(escalators):
        entries.append("Escalator %s: maintenance sequence %03d" % (escalator, i + 1))

    for i, exit_name in enumerate(exits):
        entries.append("Exit %s: street exit %s" % (exit_name, _letter(i)))

    return entries


def format_report(entries):
    report = []
    for i, entry in enumerate(entries, start=1):
        report.append("%3d. %s" % (i, entry))
    return "\n".join(report)


