        entries.append({"kind": "session", "detail": "{0} in the {1}".format(session, label)})
    return entries


def channel_feeds(matches):
    entries = []
    for offset, match in enumerate(matches):
        channel = 100 + offset
        entries.append({"kind": "match", "detail": "{0} on feed channel {1}".format(match, channel)})
    return entries


def number_sets(sets_played):
    entries = []
    for number, played in enumerate(sets_played, start=1):
        entries.append({"kind": "set", "detail": "{0} is set {1}".format(played, number)})
    return entries


def game_sequence(games):
    entries = []
    for step, game in enumerate(games, start=1):
        entries.append({"kind": "game", "detail": "game {0} of {1}: {2}".format(step, len(games), game)})
    return entries


def reel_positions(highlights):
    entries = []
    for position, highlight in enumerate(highlights, start=1):
        entries.append({"kind": "highlight", "detail": "{0} at reel position {1}".format(highlight, position)})
    return entries


