GROUP_NAMES = (
    "sites", "holes", "sections", "strata",
    "fossils", "minerals", "fluids", "markers",
)


def _validate(drill):
    if len(drill) != len(GROUP_NAMES):
        raise ValueError("drill must contain exactly eight sublists")
    for position, group in enumerate(drill):
        if not isinstance(group, (list, tuple)):
            raise TypeError(
                "group %d (%s) must be a list of strings"
                % (position, GROUP_NAMES[position])
            )


def label_sites(sites):
    lines = []
    for index, site in enumerate(sites):
        letter = chr(ord("A") + index % 26)
        lines.append("Site %s: %s" % (letter, site))
    return lines


def number_holes(holes):
    lines = []
    for index, hole in enumerate(holes, start=1):
        lines.append("Bore %03d drilled at %s" % (index, hole))
    return lines


def tier_sections(sections):
    lines = []
    for index, section in enumerate(sections):
        lines.append("Section %s logged at depth tier %d" % (section, index * 5))
    return lines


def sequence_strata(strata):
    lines = []
    for index, layer in enumerate(strata, start=1):
        lines.append("Layer %d of %d: %s" % (index, len(strata), layer))
    return lines


def catalog_fossils(fossils):
    lines = []
    for index, fossil in enumerate(fossils):
        lines.append("Fossil %s filed as F-%04d" % (fossil, 1000 + index))
    return lines


def rank_minerals(minerals):
    lines = []
    total = max(len(minerals), 1)
    for index, mineral in enumerate(minerals):
        lines.append(
            "Mineral %s concentration rank %d/%d" % (mineral, total - index, total)
        )
    return lines


def vial_fluids(fluids):
    lines = []
    for index, fluid in enumerate(fluids, start=1):
        lines.append("Fluid %s sealed in vial V%02d" % (fluid, index))
    return lines


def flag_markers(markers):
    lines = []
    for index, marker in enumerate(markers):
        lines.append("Marker %s flagged at position %d cm" % (marker, index * 25))
    return lines


def sample(drill):
    _validate(drill)
    handlers = (
        label_sites, number_holes, tier_sections, sequence_strata,
        catalog_fossils, rank_minerals, vial_fluids, flag_markers,
    )
    log = []
    for index, handler in enumerate(handlers):
        log.extend(handler(drill[index]))
    return log


def main():
    drill = [
        ["Ridgeline", "Salt Flat"],
        ["North Shaft", "South Shaft", "Test Pit"],
        ["Top", "Middle", "Base"],
        ["silt", "clay", "basalt"],
        ["trilobite", "ammonite"],
        ["quartz", "pyrite", "calcite"],
        ["brine", "meltwater"],
        ["red tape", "blue tape"],
    ]
    for line_number, entry in enumerate(sample(drill), start=1):
        print("%3d | %s" % (line_number, entry))


if __name__ == "__main__":
    main()

