        print("== %s ==" % name)
        sectors = build_sectors(speeds)
        for line_index, line in enumerate(energy_report(sectors), start=1):
            print("%2d. %s" % (line_index, line))
        for sector_index, bonus in enumerate(sector_bonuses(sectors)):
