def check_integers(trades):
    """Phase 0: reject anything that is not a plain integer trade value."""
    for position, value in enumerate(trades):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError(
                "trade at position {} is not an integer: {!r}".format(position, value)
            )
    return list(trades)


def count_valid_steps(trades):
    """Phase 1: a step is valid when it stays within 20% of the previous value."""
    valid = 0
    for position, value in enumerate(trades):
        if position == 0:
            continue
        previous = trades[position - 1]
        if abs(value - previous) <= abs(previous) * 0.2:
            valid += 1
    return valid


def flag_collapses(trades):
    """Phase 2: positions whose value fell to less than half of the opening trade."""
    if not trades:
        return []
    opening = trades[0]
    flagged = []
    for position, value in enumerate(trades):
        if position > 0 and value * 2 < opening:
            flagged.append(position)
    return flagged


def find_local_maxima(trades):
    """Phase 3: (position, value) pairs that top both immediate neighbours."""
    peaks = []
    last = len(trades) - 1
    for position, value in enumerate(trades):
        if 0 < position < last and value > trades[position - 1] and value > trades[position + 1]:
            peaks.append((position, value))
    return peaks


def build_audit_trail(trades, peak_positions, flagged_positions):
    """Phase 4: one human readable line per trade, joined into a single string."""
    lines = []
    for position, value in enumerate(trades):
        line = "step {}: value {}".format(position + 1, value)
        if position in peak_positions:
            line += " [local max]"
        if position in flagged_positions:
            line += " [flagged]"
        lines.append(line)
    return "\n".join(lines)


def validate(trades):
    checked = check_integers(trades)
    valid_steps = count_valid_steps(checked)
    flagged = flag_collapses(checked)
    peaks = find_local_maxima(checked)
    peak_positions = {position for position, value in peaks}
    trail = build_audit_trail(checked, peak_positions, set(flagged))
    return trail, valid_steps, flagged


def main():
    samples = [
        [100, 110, 95, 40, 42, 90, 30],
        [50, 52, 51, 53, 52],
    ]
    for index, trades in enumerate(samples):
        trail, valid_steps, flagged = validate(trades)
        print("run {} ({} trades)".format(index + 1, len(trades)))
        print(trail)
        print("valid steps: {}".format(valid_steps))
        print("flagged positions: {}".format(flagged))
        peaks = find_local_maxima(trades)
        print("peaks: {}".format(
            ", ".join("step {} value {}".format(pos + 1, val) for pos, val in peaks)
        ))
        print()


if __name__ == "__main__":
    main()

