INITIAL_INK = 100.0
GHOST_FORCE = 55
GHOST_INK = 10.0
REVERSE_INTERVAL = 50


def validate_strokes(strokes):
    clean = []
    for i, force in enumerate(strokes):
        if not isinstance(force, int) or isinstance(force, bool):
            raise TypeError("stroke %d is not an integer force: %r" % (i + 1, force))
        if force < 0:
            raise ValueError("stroke %d has negative force: %d" % (i + 1, force))
        clean.append(force)
    return clean


def wear_for(position, force):
    return 1.0 + position / 25.0 + force / 40.0


def reverse_ribbon(ink):
    return min(INITIAL_INK, ink + 35.0)


def ink_profile(strokes):
    ink = INITIAL_INK
    levels = []
    for i, force in enumerate(strokes):
        ink = max(0.0, ink - wear_for(i, force))
        levels.append(ink)
        if (i + 1) % REVERSE_INTERVAL == 0:
            ink = reverse_ribbon(ink)
    return levels


def darkness_profile(strokes, levels):
    darks = []
    for i, ink in enumerate(levels):
        darks.append(int(round(strokes[i] * ink / INITIAL_INK)))
    return darks


def find_ghosts(strokes, levels):
    ghosts = []
    for i, force in enumerate(strokes):
        if force >= GHOST_FORCE and levels[i] < GHOST_INK:
            ghosts.append(i + 1)
    return ghosts


def render_page(darks):
    page = []
    for i, dark in enumerate(darks, start=1):
        bar = "#" * (dark // 8)
        page.append("stroke %04d | darkness %3d | %s" % (i, dark, bar))
    return page


def typewrite(strokes):
    clean = validate_strokes(strokes)
    levels = ink_profile(clean)
    darks = darkness_profile(clean, levels)
    return render_page(darks), find_ghosts(clean, levels)


def main():
    strokes = [30 + (i * 37) % 60 for i in range(130)]
    page, ghosts = typewrite(strokes)
    print("--- printed page ---")
    for number, line in enumerate(page, start=1):
        if number % 10 == 0 or number <= 3:
            print(line)
    print("--- ghost characters: %d ---" % len(ghosts))
    for rank, position in enumerate(ghosts, start=1):
        print("%2d. stroke %d (force %d)" % (rank, position, strokes[position - 1]))


if __name__ == "__main__":
    main()

