def validate_pages(pages):
    for index, page in enumerate(pages):
        if not isinstance(page, int) or isinstance(page, bool):
            raise TypeError("page at feed position %d is not an integer" % index)
        if page < 0:
            raise ValueError("page at feed position %d is negative" % index)
    return list(pages)


def split_into_sets(pages):
    sets = []
    starts = []
    current = []
    previous = None
    for index, page in enumerate(pages):
        if previous is not None and page < previous:
            sets.append(current)
            current = []
        if not current:
            starts.append(index)
        current.append(page)
        previous = page
    if current:
        sets.append(current)
    return sets, starts


def find_blank_positions(pages):
    blanks = []
    for index, page in enumerate(pages):
        if page == 0:
            blanks.append(index)
    return blanks


def build_manifest(sets, starts):
    manifest = []
    for set_number, document in enumerate(sets, start=1):
        offset = starts[set_number - 1]
        for position, page in enumerate(document):
            manifest.append((offset + 1 + position, page, set_number))
    return manifest


def largest_document_set(sets, starts):
    best_number = 0
    best_size = -1
    for set_number, document in enumerate(sets, start=1):
        if len(document) > best_size:
            best_size = len(document)
            best_number = set_number
    if best_number == 0:
        return None
    return best_number, best_size, starts[best_number - 1] + 1


def format_manifest(manifest):
    lines = ["SEQ  PAGE  SET"]
    for seq, page, set_number in manifest:
        label = "blank" if page == 0 else str(page)
        lines.append("%3d  %5s  %3d" % (seq, label, set_number))
    return lines


def collate(pages):
    checked = validate_pages(pages)
    sets, starts = split_into_sets(checked)
    manifest = build_manifest(sets, starts)
    return sets, manifest


def main():
    pages = [1, 2, 3, 0, 5, 1, 2, 0, 1, 2, 3, 4, 0, 6]
    sets, manifest = collate(pages)
    _, starts = split_into_sets(pages)
    for set_number, document in enumerate(sets, start=1):
        print("set %d (feed %d): %s" % (set_number, starts[set_number - 1] + 1, document))
    for line in format_manifest(manifest):
        print(line)
    for rank, position in enumerate(find_blank_positions(pages), start=1):
        print("blank #%d at absolute feed position %d" % (rank, position + 1))
    biggest = largest_document_set(sets, starts)
    if biggest is not None:
        number, size, start_seq = biggest
