MAPPING = {"L": "L", "LEFT": "L", "R": "R", "RIGHT": "R"}


def normalize_touches(touches):
    hits = []
    for position, raw in enumerate(touches, start=1):
        if not isinstance(raw, str):
            raise TypeError(f"touch {position} is not a string: {raw!r}")
        key = raw.strip().upper()
        if key not in MAPPING:
            raise ValueError(f"touch {position} is not a valid target hit: {raw!r}")
        hits.append(MAPPING[key])
    return hits


def find_momentum_bouts(hits):
    bouts = []
    streak = 0
    for bout, hit in enumerate(hits, start=1):
        streak = streak + 1 if hit == "R" else 0
        if streak == 3:
            bouts.append(bout)
            streak = 0
    return bouts


def momentum_points(hits):
    total = len(hits)
    points = {}
    for bout in find_momentum_bouts(hits):
        points[bout] = 2 if bout * 2 > total else 1
    return points


def find_double_touches(hits):
    starts = []
    run = 1
    for index, hit in enumerate(hits):
        if index and hit != hits[index - 1]:
            run += 1
        else:
            run = 1
        if run >= 4:
            starts.append(index - 2)
    return starts


def build_bout_log(hits, momentum, doubles):
    alternating = set(doubles)
    left = right = 0
    log = []
    for bout, hit in enumerate(hits, start=1):
        if hit == "L":
            left += 1
        else:
            right += 1
        notes = []
        bonus = momentum.get(bout)
        if bonus:
            right += bonus
            notes.append(f"momentum +{bonus} to right")
        if bout in alternating:
            notes.append("double touch sequence begins")
        line = f"Bout {bout}: {hit} touch - left {left}, right {right}"
        if notes:
            line += " (" + "; ".join(notes) + ")"
        log.append(line)
    return {"left": left, "right": right}, log


def score(touches):
    hits = normalize_touches(touches)
    momentum = momentum_points(hits)
    doubles = find_double_touches(hits)
    final, log = build_bout_log(hits, momentum, doubles)
    return final, log


def main():
    touches = ["L", "right", "L", "R", "L", "R", "R", "R", "left", "R", "R", "R"]
    final, log = score(touches)
    for number, line in enumerate(log, start=1):
        print(f"{number:>2} | {line}")
    print(f"Final score: left {final['left']} - right {final['right']}")
    for count, start in enumerate(find_double_touches(normalize_touches(touches)), start=1):
        print(f"Double touch {count}: bouts {start}-{start + 3}")


if __name__ == "__main__":
    main()

