def has_duplicates(row):
    seen = set()
    for value in row:
        if value == 0:
            continue
        if value in seen:
            return True
        seen.add(value)
    return False


def find_invalid_rows(rows):
    invalid = []
    for index in range(len(rows)):
        if has_duplicates(rows[index]):
            invalid.append(index)
    return invalid


def missing_cells(row):
    missing = []
    for column in range(len(row)):
        if row[column] == 0:
            missing.append(column)
