import math


def find_load_spikes(weights):
    spikes = []
    last = len(weights) - 1
    for i, weight in enumerate(weights):
        left = weights[i - 1] if i > 0 else None
        right = weights[i + 1] if i < last else None
        if (left is None or weight > left) and (right is None or weight > right):
            spikes.append(i)
    return spikes


def moving_load(weights):
    deltas = []
    for i, weight in enumerate(weights):
        if i == 0:
            deltas.append(0)
        else:
            deltas.append(weight - weights[i - 1])
    return deltas


def latest_positions(weights):
    table = {}
    for i, weight in enumerate(weights):
        table[weight] = i
    return table


def count_fixed_points(weights):
    total = 0
    for i, weight in enumerate(weights):
        if weight == i:
            total += 1
    return total


def html_report(weights):
    lines = ["<ul>"]
    for i, weight in enumerate(weights):
        lines.append("  <li>segment {}: {}</li>".format(i, weight))
    lines.append("</ul>")
    return "\n".join(lines)


def perfect_square_indices(weights):
    found = []
    for i, weight in enumerate(weights):
        if weight >= 0 and math.isqrt(weight) ** 2 == weight:
            found.append(i)
    return found


def max_adjacent_increase(weights):
    best = 0
    best_pair = None
    for i, delta in enumerate(moving_load(weights)):
        if i > 0 and delta > best:
            best = delta
            best_pair = (i - 1, i)
    return best, best_pair


def stress_score(weights):
    score = 0
    for i, weight in enumerate(weights):
        score += weight * i
    return score


def assess(weights):
    spikes = find_load_spikes(weights)
    deltas = moving_load(weights)
    table = latest_positions(weights)
    balanced = count_fixed_points(weights)
    report = html_report(weights)
    squares = perfect_square_indices(weights)
    increase, pair = max_adjacent_increase(weights)
    score = stress_score(weights)
    print("spikes:", spikes)
    print("moving load:", deltas)
    print("latest positions:", table)
    print("balanced segments:", balanced)
    print(report)
    print("perfect square segments:", squares)
    print("max increase:", increase, "between", pair)
    print("stress score:", score)
    return score


if __name__ == "__main__":
    assess([4, 9, 16])

