    return table


def count_fixed_points(weights):
    total = 0
    for i in range(len(weights)):
        if weights[i] == i:
            total += 1
    return total


def html_report(weights):
    lines = ["<ul>"]
    for i in range(len(weights)):
        lines.append("  <li>segment {}: {}</li>".format(i, weights[i]))
    lines.append("</ul>")
    return "\n".join(lines)


def perfect_square_indices(weights):
    found = []
    for i in range(len(weights)):
        if weights[i] >= 0 and math.isqrt(weights[i]) ** 2 == weights[i]:
            found.append(i)
    return found


def max_adjacent_increase(weights):
    best = 0
    best_pair = None
    for i in range(len(moving_load(weights))):
        if i > 0 and moving_load(weights)[i] > best:
            best = moving_load(weights)[i]
            best_pair = (i - 1, i)
    return best, best_pair


def stress_score(weights):
    score = 0
    for i in range(len(weights)):
        score += weights[i] * i
    return score


def assess(weights):
    spikes = find_load_spikes(weights)
    deltas = moving_load(weights)
    table = latest_positions(weights)
    balanced = count_fixed_points(weights)
    report = html_report(weights)
    squares = perfect_square_indices(weights)
    increase, pair = max_adjacent_increase(weights)
    score = stress_score(weights)
    print("spikes:", spikes)
    print("moving load:", deltas)
    print("latest positions:", table)
    print("balanced segments:", balanced)
    print(report)
    print("perfect square segments:", squares)
    print("max increase:", increase, "between", pair)
    print("stress score:", score)
    return score


