HEADERS = ("n", "n!", "digits", "trailing zeros")


def validate_inputs(values):
    """Return the values as ints, rejecting anything that is not a non-negative integer."""
    cleaned = []
    for index, value in enumerate(values):
        try:
            number = int(value)
        except (TypeError, ValueError):
            raise ValueError("input %d is not an integer: %r" % (index, value))
        if number < 0:
            raise ValueError("input %d is negative: %d" % (index, number))
        cleaned.append(number)
    return cleaned


def calculate_factorial(n):
    """Compute n! for a non-negative integer n; 0! is 1."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    result = 1
    for factor in range(2, n + 1):
        result *= factor
    return result


def count_trailing_zeros(digits):
    """Number of zeros at the end of a decimal string."""
    for position, digit in enumerate(digits[::-1]):
        if digit != "0":
            return position
    return len(digits)


def build_rows(numbers):
    """One text row per requested n, describing its factorial."""
    rows = []
    for number in numbers:
        digits = str(calculate_factorial(number))
        rows.append((str(number), digits, str(len(digits)), str(count_trailing_zeros(digits))))
    return rows


def column_widths(rows):
    """Width of each table column, wide enough for its header and every cell."""
    widths = [len(header) for header in HEADERS]
    for row in rows:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    return widths


def format_table(rows):
    """Render the rows as an aligned text table."""
    widths = column_widths(rows)
    lines = [" | ".join(head.ljust(widths[i]) for i, head in enumerate(HEADERS))]
    lines.append("-+-".join("-" * width for width in widths))
    for row in rows:
        lines.append(" | ".join(cell.rjust(widths[i]) for i, cell in enumerate(row)))
    return lines


def main(argv=None):
    raw = argv if argv else ["0", "1", "5", "10", "20"]
    numbers = validate_inputs(raw)
    for line in format_table(build_rows(numbers)):
        print(line)
    largest = max(numbers)
