def _check_hashable(items):
    """Raise TypeError if any element cannot be used as a dictionary key."""
    for index, item in enumerate(items):
        try:
            hash(item)
        except TypeError:
            raise TypeError(f"item at index {index} is unhashable: {item!r}") from None


def first_occurrences(items):
    """Map each element to the index where it first shows up."""
    positions = {}
    for index, item in enumerate(items):
        if item not in positions:
            positions[item] = index
    return positions


def remove_duplicates(items):
    """Return a new list without duplicates, keeping first-occurrence order."""
    _check_hashable(items)
    firsts = first_occurrences(items)
    return [item for index, item in enumerate(items) if firsts[item] == index]


def duplicate_positions(items):
    """Map each repeated element to the indexes of its redundant copies."""
    _check_hashable(items)
    firsts = first_occurrences(items)
    repeats = {}
    for index, item in enumerate(items):
        if firsts[item] != index:
            repeats.setdefault(item, []).append(index)
    return repeats


def format_unique(unique):
    """Render the deduplicated list with the index each item now sits at."""
    lines = []
    for index, item in enumerate(unique):
        lines.append(f"  [{index}] {item!r}")
    return lines


def format_duplicates(repeats):
    """Describe where every discarded copy was found."""
    lines = []
    for item, positions in repeats.items():
        spots = ", ".join(str(position) for position in positions)
        lines.append(f"  {item!r} repeated at index {spots}")
    return lines


def report(items):
    """Build a human readable summary of the deduplication of `items`."""
    unique = remove_duplicates(items)
    repeats = duplicate_positions(items)
    lines = [f"input  ({len(items)} items): {items!r}",
             f"unique ({len(unique)} items): {unique!r}"]
    lines.extend(format_unique(unique))
    if repeats:
        lines.append("removed copies:")
        lines.extend(format_duplicates(repeats))
    return lines


def main():
    datasets = [
        ("numbers", [1, 2, 2, 3, 1, 4]),
        ("letters", ['a', 'b', 'a']),
        ("empty", []),
        ("all same", [7, 7, 7, 7]),
        ("mixed types", ['x', 3, 'x', None, 3, None, True]),
    ]
    for label, data in datasets:
        print(f"--- {label} ---")
        for line in report(data):
            print(line)


if __name__ == "__main__":
