def is_prime(n):
    """Return True if the positive integer n is a prime number."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an integer")
    if n < 1:
        raise ValueError("n must be a positive integer")
    if n < 4:
        return n > 1
    if n % 2 == 0:
        return False
    divisor = 3
    while divisor * divisor <= n:
        if n % divisor == 0:
            return False
        divisor += 2
    return True


def primes_upto(limit):
    """Return every prime <= limit using a sieve of Eratosthenes."""
    flags = [True] * (limit + 1)
    if limit >= 0:
        flags[0] = False
    if limit >= 1:
        flags[1] = False
    step = 2
    while step * step <= limit:
        if flags[step]:
            for multiple in range(step * step, limit + 1, step):
                flags[multiple] = False
        step += 1
    return [value for value, prime in enumerate(flags) if prime]


def prime_factors(n):
    """Return the prime factors of n in non-decreasing order."""
    remaining = n
    factors = []
    candidate = 2
    while candidate * candidate <= remaining:
        while remaining % candidate == 0:
            factors.append(candidate)
            remaining //= candidate
        candidate += 1 if candidate == 2 else 2
    if remaining > 1:
        factors.append(remaining)
    return factors


def format_factorization(n):
    """Render n as a product of prime powers, e.g. 360 -> 2^3 * 3^2 * 5."""
    if n == 1:
        return "1"
    groups = []
    factors = prime_factors(n)
    for position, prime in enumerate(factors):
        if position and prime == factors[position - 1]:
            groups[-1][1] += 1
        else:
            groups.append([prime, 1])
    return " * ".join(str(p) if e == 1 else "{}^{}".format(p, e) for p, e in groups)


def render_table(rows):
    """Render rows of strings as a left-aligned text table."""
    widths = [0] * max(len(row) for row in rows)
    for row in rows:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    lines = []
    for row in rows:
        cells = [cell.ljust(widths[column]) for column, cell in enumerate(row)]
        lines.append("  ".join(cells).rstrip())
    return "\n".join(lines)


