    """Turn raw text readings into floats, reporting the offending position."""
    readings = []
    for index, raw in enumerate(raw_values):
        try:
            readings.append(float(raw))
        except (TypeError, ValueError):
            raise ValueError("reading %d is not a number: %r" % (index + 1, raw))
    return readings


def split_valid(readings):
    """Separate physically possible readings from those below absolute zero."""
    valid = []
    rejected = []
    for index, celsius in enumerate(readings):
        if celsius < ABSOLUTE_ZERO_C:
            rejected.append((index, celsius))
        else:
            valid.append(celsius)
    return valid, rejected


def format_table(readings):
    """Build a numbered conversion table as a list of text lines."""
    lines = ["  #  Celsius  Fahrenheit"]
    for index, celsius in enumerate(readings):
        lines.append("%3d %8.2f %11.2f" % (index + 1, celsius, celsius_to_fahrenheit(celsius)))
