def calculate_age(birth_year, current_year):
    """Return the age of a person born in birth_year as of current_year."""
    if not isinstance(birth_year, int) or isinstance(birth_year, bool):
        raise TypeError("birth_year must be an integer")
    if not isinstance(current_year, int) or isinstance(current_year, bool):
        raise TypeError("current_year must be an integer")
    if current_year < birth_year:
        raise ValueError("current_year must not precede birth_year")
    return current_year - birth_year


def parse_year(text):
    """Convert a year string to an int, pointing at the first bad character."""
    for position, char in enumerate(text):
        if char.isdigit() or (position == 0 and char in "+-"):
            continue
        raise ValueError("bad character %r at position %d in year" % (char, position))
    if not text.lstrip("+-"):
        raise ValueError("year must contain at least one digit")
    return int(text)


def parse_record(line):
    """Turn 'Name,birth_year' into a (name, birth_year) pair."""
    fields = [field.strip() for field in line.split(",")]
    if len(fields) != 2:
        raise ValueError("expected exactly two fields, got %d" % len(fields))
    for position, field in enumerate(fields, start=1):
        if not field:
            raise ValueError("field %d must not be empty" % position)
    name, raw_year = fields
    return name, parse_year(raw_year)


def load_records(lines):
    """Parse non-empty lines, reporting the source line number on failure."""
    records = []
    for number, line in enumerate(lines, start=1):
        if not line.strip():
            continue
        try:
            records.append(parse_record(line))
        except ValueError as error:
            raise ValueError("line %d: %s" % (number, error))
    return records


def ages_for(records, current_year):
    """Compute (name, age) pairs, naming the record that fails."""
    aged = []
    for position, (name, year) in enumerate(records, start=1):
        try:
            aged.append((name, calculate_age(year, current_year)))
        except ValueError as error:
            raise ValueError("record %d (%s): %s" % (position, name, error))
    return aged


def oldest_index(aged):
    """Return the position of the greatest age, or None for empty input."""
    best = None
    for index, (_, age) in enumerate(aged):
        if best is None or age > aged[best][1]:
            best = index
    return best


def format_report(aged, current_year):
    """Build a numbered listing of ages, marking the oldest entry."""
    if not aged:
        return "No records to report."
    oldest = oldest_index(aged)
    width = max(len(name) for name, _ in aged)
    lines = ["Ages as of %d:" % current_year]
    for position, (name, age) in enumerate(aged):
        marker = " <- oldest" if position == oldest else ""
        lines.append("%2d. %-*s %3d%s" % (position + 1, width, name, age, marker))
    return "\n".join(lines)


