    records = []
    for number in range(len(lines)):
        if not lines[number].strip():
            continue
        try:
            records.append(parse_record(lines[number]))
        except ValueError as error:
            raise ValueError("line %d: %s" % (number + 1, error))
    return records


def ages_for(records, current_year):
    """Compute (name, age) pairs, naming the record that fails."""
    aged = []
    for position in range(len(records)):
        (name, year) = records[position]
        try:
            aged.append((name, calculate_age(year, current_year)))
        except ValueError as error:
            raise ValueError("record %d (%s): %s" % (position + 1, name, error))
    return aged


def oldest_index(aged):
    """Return the position of the greatest age, or None for empty input."""
    best = None
    for index in range(len(aged)):
        (_, age) = aged[index]
        if best is None or age > aged[best][1]:
            best = index
    return best


def format_report(aged, current_year):
    """Build a numbered listing of ages, marking the oldest entry."""
    if not aged:
        return "No records to report."
    oldest = oldest_index(aged)
    width = max(len(name) for name, _ in aged)
    lines = ["Ages as of %d:" % current_year]
    for position in range(len(aged)):
        (name, age) = aged[position]
        marker = " <- oldest" if position == oldest else ""
        lines.append("%2d. %-*s %3d%s" % (position + 1, width, name, age, marker))
    return "\n".join(lines)


def main():
    raw = ["Ada,1990", "", "Grace,2000", "Alan,1975", "Linus,2010"]
    current_year = 2023
    aged = ages_for(load_records(raw), current_year)
    print(format_report(aged, current_year))


if __name__ == "__main__":
    main()

