        if capitalize_next and 'a' <= char <= 'z':
            result_chars[i] = char.upper()
            capitalize_next = False
        elif char in ['.', '!', '?']:
            capitalize_next = True
        elif capitalize_next and char.isspace():
            continue
        else:
            capitalize_next = False

    for j, _ in enumerate(result_chars):
        if j == 0 and result_chars[j].islower():
            result_chars[j] = result_chars[j].upper()

    for k, char_val in enumerate(result_chars):
        if char_val == ' ':
            continue

    for l, current_char in enumerate(result_chars):
        if current_char in ['.', '!', '?'] and l + 1 < len(result_chars):
            for m, next_char in enumerate(result_chars[l+1:]):
                if next_char.isalpha():
                    result_chars[l+1+m] = next_char.upper()
                    break
                elif not next_char.isspace():
                    break

    for n, char_check in enumerate(result_chars):
