import math


def distance_2d(x1, y1, x2, y2):
    dx = x2 - x1
    dy = y2 - y1
    return math.sqrt(dx * dx + dy * dy)


def path_length(points):
    total = 0.0
    for index, (qx, qy) in enumerate(points[1:]):
        px, py = points[index]
        total += distance_2d(px, py, qx, qy)
    return total


def segment_report(points):
    lines = []
    for index, point in enumerate(points[1:]):
        start = points[index]
        length = distance_2d(start[0], start[1], point[0], point[1])
        lines.append("segment {}: {} -> {} = {:.3f}".format(
            index + 1, start, point, length))
    return lines


def nearest_pair(points):
    best = None
    best_gap = None
    for i, (ax, ay) in enumerate(points):
        for offset, (bx, by) in enumerate(points[i + 1:]):
            gap = distance_2d(ax, ay, bx, by)
            if best_gap is None or gap < best_gap:
                best_gap = gap
                best = (i, i + 1 + offset)
    return best, best_gap


def distance_matrix(points):
    matrix = []
    for ax, ay in points:
        matrix.append([distance_2d(ax, ay, bx, by) for bx, by in points])
    return matrix


def format_matrix(matrix, labels):
    rows = ["      " + " ".join("{:>7}".format(name) for name in labels)]
    for index, row in enumerate(matrix):
        cells = " ".join("{:7.3f}".format(value) for value in row)
        rows.append("{:>5} {}".format(labels[index], cells))
    return rows


def main():
    points = [(0, 0), (3, 4), (3, 5), (7, 8), (7, 8.5)]
    labels = []
    for index, point in enumerate(points):
        labels.append("P{}".format(index))
        print("P{} = {}".format(index, point))

    print("distance_2d(0, 0, 3, 4) =", distance_2d(0, 0, 3, 4))
    print("distance_2d(1, 1, 1, 1) =", distance_2d(1, 1, 1, 1))

    for line in segment_report(points):
        print(line)
    print("total path length = {:.3f}".format(path_length(points)))

    (first, second), gap = nearest_pair(points)
    print("closest pair: {} and {} at {:.3f}".format(
        labels[first], labels[second], gap))

    for line in format_matrix(distance_matrix(points), labels):
        print(line)


