import random
import string

ALPHABET = string.ascii_lowercase + string.ascii_uppercase + string.digits
SAMPLE_LENGTHS = [8, 12, 16]


def generate_password(length):
    if not isinstance(length, int) or isinstance(length, bool):
        raise TypeError("length must be an integer")
    if length < 1:
        raise ValueError("length must be at least 1")
    return "".join(random.choice(ALPHABET) for _ in range(length))


def classify(char):
    if char in string.ascii_lowercase:
        return "lowercase"
    if char in string.ascii_uppercase:
        return "uppercase"
    return "digit"


def positions_of_digits(password):
    found = []
    for index, char in enumerate(password):
        if char in string.digits:
            found.append(index)
    return found


def find_repeats(password):
    repeats = []
    for index, char in enumerate(password):
        if index and char == password[index - 1]:
            repeats.append((index, char))
    return repeats


def describe(password):
    counts = {"lowercase": 0, "uppercase": 0, "digit": 0}
    for char in password:
        counts[classify(char)] += 1
    return counts


def format_report(password):
    lines = ["password: " + password]
    for index, char in enumerate(password):
        lines.append("  {:>2}: {} ({})".format(index, char, classify(char)))
    counts = describe(password)
    for kind in sorted(counts):
        lines.append("{:<9} {}".format(kind, counts[kind]))
    digits = positions_of_digits(password)
    lines.append("digit positions: " + (", ".join(str(p) for p in digits) or "none"))
    for spot, char in find_repeats(password):
        lines.append("repeat at {}: {}{}".format(spot, char, char))
    return "\n".join(lines)


def main():
    for index, length in enumerate(SAMPLE_LENGTHS):
        print("=== sample {} (length {}) ===".format(index + 1, length))
        print(format_report(generate_password(length)))
    batch = [generate_password(6) for _ in range(4)]
    for index, password in enumerate(batch):
        counts = describe(password)
        kinds = "/".join("{}={}".format(kind, counts[kind]) for kind in sorted(counts))
        print("batch {}: {} -> {}".format(index, password, kinds))


if __name__ == "__main__":
    main()

