    digits = list(reversed(str(n)))
    breakdown = []
    for place, char in enumerate(digits):
        breakdown.append((place, int(char)))
    return breakdown


def sum_digits(n):
    """Sum the decimal digits of the non-negative integer n."""
    if isinstance(n, bool) or not isinstance(n, int):
        raise TypeError("n must be an integer, got %r" % (n,))
    if n < 0:
        raise ValueError("n must be non-negative, got %d" % n)
    return sum(digit for _, digit in digit_breakdown(n))


def parse_numbers(text):
    """Turn whitespace-separated text into a list of non-negative integers."""
    tokens = text.split()
    numbers = []
    for position, token in enumerate(tokens, 1):
        if not token.isdigit():
            raise ValueError("token %d (%r) is not a non-negative integer"
                             % (position, token))
        numbers.append(int(token))
    return numbers


def column_widths(rows):
    """Compute the display width needed by each column of a table."""
    widths = []
    for row in rows:
        for column, cell in enumerate(row):
            if column == len(widths):
                widths.append(len(cell))
            elif len(cell) > widths[column]:
                widths[column] = len(cell)
    return widths


def format_row(row, widths):
    """Pad each cell of a row to its column width."""
    parts = []
    for column, cell in enumerate(row):
        parts.append(cell.ljust(widths[column]))
    return " ".join(parts).rstrip()


def format_breakdown(n):
    """Render n as a sum of its digits, most significant first."""
    terms = []
    for place, digit in reversed(digit_breakdown(n)):
        terms.append(str(digit) if place == 0 else "%d*10^%d" % (digit, place))
    return " + ".join(terms)


def digit_sum_chain(n):
    """Repeatedly apply sum_digits until a single digit remains."""
    chain = []
    current = n
    while current >= 10:
        current = sum_digits(current)
        chain.append(current)
    return chain


def format_chain(n):
    """Describe the reduction of n down to its digital root."""
    steps = digit_sum_chain(n)
    labels = []
    for step, value in enumerate(steps, 1):
        labels.append("s%d=%d" % (step, value))
    return ", ".join(labels)


def digital_root(n):
    chain = digit_sum_chain(n)
    return chain[-1] if chain else n


def build_table(numbers):
