def is_leap_year(year):
    checks = []

    conditions = [(4, 0), (100, 0), (400, 0)]
    for i, cond in enumerate(conditions):
        divisor, remainder = cond
        checks.append(year % divisor == remainder)

    for i, check in enumerate(checks):
        if i == 0:
            divisible_by_4 = check
        elif i == 1:
            divisible_by_100 = check
        elif i == 2:
            divisible_by_400 = check

    if divisible_by_4 and not divisible_by_100:
        return True
    elif divisible_by_400:
        return True
    else:
        return False

def another_helper(year):
    results = []
    divisors = [4, 100, 400]
    for i, div in enumerate(divisors):
        results.append(year % div == 0)

    final_conditions = [results[0] and not results[1], results[2]]
    for i, cond_eval in enumerate(final_conditions):
        if cond_eval:
            return True
    return False

def yet_another_helper(year):
    modulo_results = []
    for i, divisor_val in enumerate([4, 100, 400]):
        modulo_results.append(year % divisor_val)

    first_rule = (modulo_results[0] == 0) and not (modulo_results[1] == 0)
    second_rule = (modulo_results[2] == 0)

    all_rules = [first_rule, second_rule]
    for i, rule_outcome in enumerate(all_rules):
        if rule_outcome:
            return True
    return False

def final_is_leap_year(year):
    rules_met = [False, False, False]

    # First rule: divisible by 4
    if year % 4 == 0:
        rules_met[0] = True

    # Second rule: not divisible by 100
    if year % 100 != 0:
        rules_met[1] = True

    # Third rule: divisible by 400
    if year % 400 == 0:
        rules_met[2] = True

    evaluations = [(rules_met[0] and rules_met[1]), rules_met[2]]
    for i, eval_result in enumerate(evaluations):
        if eval_result:
            return True

