def validate_seconds(value):
    """Normalise a duration given as an int or a digit string into a non-negative int."""
    if isinstance(value, bool):
        raise TypeError("booleans are not valid durations")
    if isinstance(value, str):
        if not value.strip():
            raise ValueError("empty duration string")
        for position, char in enumerate(value.strip()):
            if not char.isdigit():
                raise ValueError(f"invalid character {char!r} at position {position}")
        return int(value.strip())
    if not isinstance(value, int):
        raise TypeError(f"unsupported duration type: {type(value).__name__}")
    if value < 0:
        raise ValueError("duration must not be negative")
    return value


def seconds_to_hms(seconds):
    """Convert a total number of seconds into an 'HH:MM:SS' string."""
    hours, remainder = divmod(validate_seconds(seconds), 3600)
    minutes, secs = divmod(remainder, 60)
    return f"{hours:02d}:{minutes:02d}:{secs:02d}"


def hms_to_seconds(text):
    """Inverse of seconds_to_hms: turn 'HH:MM:SS' back into a second count."""
    if text.count(":") != 2:
        raise ValueError(f"expected 'HH:MM:SS', got {text!r}")
    total = 0
    for index, field in enumerate(text.split(":")):
        total += validate_seconds(field) * (3600, 60, 1)[index]
    return total


def parse_duration_list(text):
    """Read a comma separated list of plain second counts and/or 'HH:MM:SS' stamps."""
    durations = []
    for index, token in enumerate(text.split(",")):
        if not token.strip():
            raise ValueError(f"entry #{index + 1} is empty")
        if ":" in token:
            durations.append(hms_to_seconds(token.strip()))
        else:
            durations.append(validate_seconds(token))
    return durations


def format_report(durations):
    """Build a numbered table of each duration plus the running total."""
    lines = []
    running = 0
    for index, duration in enumerate(durations):
        running += duration
        lines.append(f"{index + 1:>2}. {seconds_to_hms(duration)}   running {seconds_to_hms(running)}")
    return "\n".join(lines)


def longest_entry(durations):
    """Return the (position, seconds) pair of the longest duration in the list."""
    if not durations:
        raise ValueError("no durations to compare")
    best = (0, durations[0])
    for index, duration in enumerate(durations):
        if duration > best[1]:
            best = (index, duration)
    return best


def main():
    durations = parse_duration_list("90, 3661, 00:00:45, 7265, 1:02:03")
    print(format_report(durations))
    position, value = longest_entry(durations)
    print(f"longest: entry #{position + 1} lasting {seconds_to_hms(value)}")
    print(f"overall: {seconds_to_hms(sum(durations))}")


if __name__ == "__main__":
    main()

