def flatten_list(list_of_lists):
    """Flatten one level of nesting, returning a single list."""
    flat = []
    for index, inner in enumerate(list_of_lists):
        if not isinstance(inner, (list, tuple)):
            raise TypeError(
                "element at position {0} is not a list: {1!r}".format(index, inner)
            )
        flat.extend(inner)
    return flat


def trace_origins(list_of_lists):
    """Return (row, column, value) for every element of the flat result."""
    origins = []
    for row, inner in enumerate(list_of_lists):
        for column, value in enumerate(inner):
            origins.append((row, column, value))
    return origins


def flatten_deep(nested):
    """Flatten arbitrarily nested lists/tuples into a single flat list."""
    flat = []
    for item in nested:
        if isinstance(item, (list, tuple)):
            flat.extend(flatten_deep(item))
        else:
            flat.append(item)
    return flat


def row_offsets(list_of_lists):
    """Starting offset of every sublist inside the flattened result."""
    offsets = []
    running = 0
    for inner in list_of_lists:
        offsets.append(running)
        running += len(inner)
    return offsets


def describe(list_of_lists):
    """Build human readable lines summarising the flattening."""
    offsets = row_offsets(list_of_lists)
    lines = ["  flattened: {0}".format(flatten_list(list_of_lists))]
    for row, inner in enumerate(list_of_lists):
        start = offsets[row]
        end = start + len(inner) - 1 if inner else start
        lines.append(
            "  row {0}: {1} item(s) at flat positions {2}..{3}".format(
                row, len(inner), start, end
            )
        )
    return lines


def format_origins(list_of_lists):
    """Build one line per flattened element naming its source coordinates."""
    lines = []
    origins = trace_origins(list_of_lists)
    for position, origin in enumerate(origins):
        lines.append(
            "  flat[{0}] = {1!r} came from [{2}][{3}]".format(
                position, origin[2], origin[0], origin[1]
            )
        )
    return lines


def main():
    samples = [
        [[1, 2], [3, 4, 5]],
        [[]],
        [["a"], [], ["b", "c"]],
    ]
    for number, sample in enumerate(samples):
        print("sample {0}: {1}".format(number, sample))
        for line in describe(sample) + format_origins(sample):
            print(line)
        print()
    tangled = [1, [2, [3, [4, 5]]], (6, 7)]
    print("deep input: {0}".format(tangled))
    deep = flatten_deep(tangled)
    for position, value in enumerate(deep):
        print("  deep[{0}] = {1!r}".format(position, value))


if __name__ == "__main__":
    main()

