def validate_numbers(numbers):
    """Return the list as plain integers, raising ValueError on bad entries."""
    values = list(numbers)
    if len(values) < 2:
        raise ValueError("need at least two elements, got %d" % len(values))
    checked = []
    for position, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, int):
            raise ValueError("element %d is not an integer: %r" % (position, value))
        checked.append(value)
    return checked


def find_second_largest(numbers):
    """Second largest number of the list (duplicates of the maximum count)."""
    values = validate_numbers(numbers)
    best = None
    second = None
    for index, value in enumerate(values):
        if best is None or value > values[best]:
            second = best
            best = index
        elif second is None or value > values[second]:
            second = index
    if second is None:
        raise ValueError("list does not contain a second largest element")
    return values[second]


def parse_row(text, line_number):
    """Turn one whitespace/comma separated row of text into a list of ints."""
    tokens = text.replace(",", " ").split()
    numbers = []
    for column, token in enumerate(tokens):
        try:
            numbers.append(int(token))
        except ValueError:
            raise ValueError(
                "line %d, field %d: %r is not an integer" % (line_number, column + 1, token)
            )
    return numbers


def parse_dataset(text):
    """Parse a multi-line block into (line_number, numbers) pairs."""
    rows = []
    for offset, line in enumerate(text.splitlines()):
        stripped = line.strip()
        if not stripped or stripped.startswith("#"):
            continue
        rows.append((offset + 1, parse_row(stripped, offset + 1)))
    return rows


def analyse(rows):
    """Compute the second largest value for each parsed row."""
    results = []
    for row_index, (line_number, numbers) in enumerate(rows):
        try:
            answer = find_second_largest(numbers)
        except ValueError as error:
            results.append((row_index + 1, line_number, numbers, None, str(error)))
        else:
            results.append((row_index + 1, line_number, numbers, answer, None))
    return results


def format_report(results):
    lines = []
    for rank, (row_index, line_number, numbers, answer, error) in enumerate(results):
        joined = ", ".join(str(n) for n in numbers)
        label = "%d. (row %d, line %d) [%s]" % (rank + 1, row_index, line_number, joined)
        if error is None:
            lines.append("%s -> second largest = %d" % (label, answer))
        else:
            lines.append("%s -> error: %s" % (label, error))
    return "\n".join(lines)


def main():
    dataset = """
    10, 5, 20, 8
    1 1 5 5
    # negatives are fine too
    -3 -7 -3 -100
    42
    """
    results = analyse(parse_dataset(dataset))
    print(format_report(results))


if __name__ == "__main__":
    main()

