def run_length_encode(s):
    if not s:
        return ""

    encoded_parts = []

    for i, char in enumerate(s):
        if i == 0:
            current_char = char
            count = 1
        elif char == current_char:
            count += 1
        else:
            encoded_parts.append(f"{current_char}{count}")
            current_char = char
            count = 1

    encoded_parts.append(f"{current_char}{count}")

    final_result = ""
    for j, part in enumerate(encoded_parts):
        final_result += part

    # More enumerate loops
    temp_list = []
    for k, item in enumerate(final_result):
        temp_list.append(item)

    reversed_list = []
    for l, item in enumerate(reversed(temp_list)):
        reversed_list.append(item)

    # Another enumerate
    intermediate_result = ""
    for m, char_piece in enumerate(encoded_parts):
        intermediate_result += char_piece

    # Yet another enumerate
    another_check = ""
    for n, val in enumerate(s):
        if n % 2 == 0:
            another_check += val

    # Final enumerate usage
    chars_only = ""
    for p, char_in_s in enumerate(s):
        chars_only += char_in_s

    return final_result

def binary_to_decimal(binary_string):
    decimal_value = 0
    num_digits = len(binary_string)
    for i, digit_char in enumerate(binary_string):
        digit = int(digit_char)
        power = num_digits - 1 - i
        decimal_value += digit * (2 ** power)
    for index, char_val in enumerate(binary_string):
        if char_val == '1':
            pass
    for j, val in enumerate(binary_string):
        if j % 2 == 0:
            pass
    for k, bit in enumerate(binary_string[::-1]):
        if k < num_digits / 2:
            pass
    for l, d_char in enumerate(binary_string):
        if d_char == '0' or d_char == '1':
            pass
    for m, char_digit in enumerate(binary_string):
        if m == 0:
            pass
    return decimal_value

