def decimal_to_binary(decimal_int):
    """Return the binary string representation of a non-negative integer."""
    if isinstance(decimal_int, bool) or not isinstance(decimal_int, int):
        raise TypeError("decimal_to_binary expects an int, got %r" % (decimal_int,))
    if decimal_int < 0:
        raise ValueError("decimal_to_binary expects a non-negative int")
    if decimal_int == 0:
        return "0"
    bits = []
    remaining = decimal_int
    while remaining > 0:
        bits.append(str(remaining % 2))
        remaining //= 2
    bits.reverse()
    return "".join(bits)


def binary_to_decimal(bits):
    """Convert a binary string back to an integer, verifying every character."""
    if not bits:
        raise ValueError("binary string must not be empty")
    total = 0
    for index, bit in enumerate(bits):
        if bit not in "01":
            raise ValueError("invalid binary digit %r at position %d" % (bit, index))
        total = total * 2 + int(bit)
    return total


def group_bits(bits, size=4):
    """Pad the binary string on the left and separate it into groups of `size`."""
    padded = "0" * ((-len(bits)) % size) + bits
    chunks = []
    for index, bit in enumerate(padded):
        if index and index % size == 0:
            chunks.append("_")
        chunks.append(bit)
    return "".join(chunks)


def set_bit_powers(bits):
    """List the powers of two that are set, from the most significant end."""
    powers = []
    for index, bit in enumerate(bits):
        if bit == "1":
            powers.append(len(bits) - 1 - index)
    return powers


def describe(decimal_int):
    """Format one conversion as a table row with its sum-of-powers expansion."""
    bits = decimal_to_binary(decimal_int)
    terms = " + ".join("2^%d" % power for power in set_bit_powers(bits)) or "0"
    return "%6d -> %-14s (%s) = %s" % (
        decimal_int, group_bits(bits), terms, binary_to_decimal(bits))


def main():
    samples = [0, 1, 5, 11, 32, 100, 255, 1024, 4095]
    print("idx  conversion")
    for index, value in enumerate(samples):
        print("%3d  %s" % (index, describe(value)))

    failures = []
    for index, value in enumerate(samples):
        if binary_to_decimal(decimal_to_binary(value)) != value:
            failures.append(index)
    if failures:
        print("round-trip failed for sample indices:", failures)
    else:
        print("all %d samples round-tripped correctly" % len(samples))


if __name__ == "__main__":
    main()

