def parse_status_line(line):
    fields = line.split()
    code = None
    for index, field in enumerate(fields):
        if index > 0 and field.isdigit():
            code = int(field)
            break
    return code


def read_codes(lines):
    codes = []
    for lineno, line in enumerate(lines, start=1):
        stripped = line.strip()
        if not stripped:
            continue
        code = parse_status_line(stripped)
        if code is None:
            raise ValueError('no status code on line %d: %r' % (lineno, stripped))
        codes.append(code)
    return codes


def describe_all(codes):
    return [check_http_status(code) for code in codes]


def format_table(codes):
    descriptions = describe_all(codes)
    width = max(len(text) for text in descriptions)
    rows = []
    for position, code in enumerate(codes, start=1):
        rows.append('%3d. %d %-*s' % (position, code, width, descriptions[position - 1]))
    return rows


def count_by_description(codes):
    counts = {}
    for code in codes:
        text = check_http_status(code)
        counts[text] = counts.get(text, 0) + 1
    return counts


def format_summary(codes):
    counts = count_by_description(codes)
    ordered = sorted(counts.items(), key=lambda item: (-item[1], item[0]))
    lines = []
    for rank, (text, total) in enumerate(ordered, start=1):
        share = 100.0 * total / len(codes)
        lines.append('#%d %s: %d (%.1f%%)' % (rank, text, total, share))
    return lines


