import random


def roll_dice(num_dice, sides):
    """Roll `num_dice` dice with `sides` faces each and return the outcomes."""
    if num_dice < 0:
        raise ValueError("num_dice must be non-negative")
    if sides < 1:
        raise ValueError("sides must be at least 1")
    return [random.randint(1, sides) for _ in range(num_dice)]


def describe_rolls(rolls):
    """Return one human readable line per die, numbered from one."""
    lines = []
    for position, value in enumerate(rolls, start=1):
        lines.append("die {}: {}".format(position, value))
    return lines


def cumulative_report(rolls):
    """Describe how the running total grows as each die is counted."""
    lines = []
    running = 0
    for position, value in enumerate(rolls, start=1):
        running += value
        lines.append("after {} dice: total {}".format(position, running))
    return lines


def tally_faces(rolls, sides):
    """Count how often each face from 1..sides appeared."""
    counts = [0] * sides
    for value in rolls:
        counts[value - 1] += 1
    return counts


def merge_counts(aggregate, counts):
    """Add per-face counts into an existing aggregate list, in place."""
    for index, count in enumerate(counts):
        aggregate[index] += count


def format_tally(counts, width=40):
    """Render face counts as a simple text histogram."""
    total = sum(counts) or 1
    lines = []
    for index, count in enumerate(counts):
        bar = "#" * round(width * count / total)
        lines.append("{:>2} | {:<{w}} {}".format(index + 1, bar, count, w=width))
    return lines


def best_face(counts):
    """Return (face, count) for the most frequent face, lowest face wins ties."""
    winner = (1, -1)
    for index, count in enumerate(counts):
        if count > winner[1]:
            winner = (index + 1, count)
    return winner


def run_trials(trials, num_dice, sides):
    """Roll several times, print each trial and return the pooled face counts."""
    aggregate = [0] * sides
    for trial in range(1, trials + 1):
        rolls = roll_dice(num_dice, sides)
        merge_counts(aggregate, tally_faces(rolls, sides))
        print("trial {}: {} (sum {})".format(trial, rolls, sum(rolls)))
    return aggregate


def main():
    random.seed(7)
    rolls = roll_dice(2, 6)
    for line in describe_rolls(rolls):
        print(line)
    for line in cumulative_report(rolls):
        print(line)

    aggregate = run_trials(5, 4, 6)
    print("aggregate distribution:")
    for line in format_tally(aggregate):
        print(line)
    face, count = best_face(aggregate)
    print("most frequent face: {} ({} times)".format(face, count))


if __name__ == "__main__":
    main()

