ROMAN_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def normalize(roman_numeral):
    """Strip surrounding blanks, upper-case, and reject unknown symbols."""
    if not isinstance(roman_numeral, str):
        raise TypeError("roman numeral must be a string")
    cleaned = roman_numeral.strip().upper()
    if not cleaned:
        raise ValueError("roman numeral must not be empty")
    for position, symbol in enumerate(cleaned):
        if symbol not in ROMAN_VALUES:
            raise ValueError(
                "invalid symbol %r at position %d in %r" % (symbol, position, cleaned)
            )
    return cleaned


def roman_to_int(roman_numeral):
    """Convert a Roman numeral string to its integer value."""
    cleaned = normalize(roman_numeral)
    total = 0
    for index, symbol in enumerate(cleaned):
        value = ROMAN_VALUES[symbol]
        following = cleaned[index + 1:index + 2]
        if following and ROMAN_VALUES[following] > value:
            total -= value
        else:
            total += value
    return total


def breakdown(roman_numeral):
    """Return the signed terms that make up the numeral, e.g. [('C', -100), ...]."""
    cleaned = normalize(roman_numeral)
    terms = []
    for index, symbol in enumerate(cleaned):
        value = ROMAN_VALUES[symbol]
        following = cleaned[index + 1:index + 2]
        if following and ROMAN_VALUES[following] > value:
            terms.append((symbol, -value))
        else:
            terms.append((symbol, value))
    return terms


def format_breakdown(terms):
    """Render signed terms as a readable arithmetic expression."""
    pieces = []
    for slot, (_symbol, value) in enumerate(terms):
        if value < 0:
            pieces.append("- %d" % -value)
        elif slot:
            pieces.append("+ %d" % value)
        else:
            pieces.append(str(value))
    return " ".join(pieces)


def report(numerals):
    """Print a numbered table of numerals, their arithmetic and their totals."""
    width = max(len(text.strip()) for text in numerals)
    lines = []
    for number, text in enumerate(numerals, start=1):
        terms = breakdown(text)
        total = sum(value for _symbol, value in terms)
        lines.append(
            "%2d. %-*s = %-30s = %d"
            % (number, width, text.strip().upper(), format_breakdown(terms), total)
        )
    return "\n".join(lines)


def main():
    samples = ["IV", "IX", "XLII", "MCMXCIV", "mmxxv", " DCCCXC "]
    print(report(samples))
    print("direct calls:")
    for slot, text in enumerate(samples):
        print("  [%d] roman_to_int(%r) -> %d" % (slot, text, roman_to_int(text)))


if __name__ == "__main__":
    main()

