    for position in range(len(cleaned)):
        if cleaned[position] not in ROMAN_VALUES:
            raise ValueError(
                "invalid symbol %r at position %d in %r" % (cleaned[position], position, cleaned)
            )
    return cleaned


def roman_to_int(roman_numeral):
    """Convert a Roman numeral string to its integer value."""
    cleaned = normalize(roman_numeral)
    total = 0
    for index in range(len(cleaned)):
        value = ROMAN_VALUES[cleaned[index]]
        following = cleaned[index + 1:index + 2]
        if following and ROMAN_VALUES[following] > value:
            total -= value
        else:
            total += value
    return total


def breakdown(roman_numeral):
    """Return the signed terms that make up the numeral, e.g. [('C', -100), ...]."""
    cleaned = normalize(roman_numeral)
    terms = []
    for index in range(len(cleaned)):
        value = ROMAN_VALUES[cleaned[index]]
        following = cleaned[index + 1:index + 2]
        if following and ROMAN_VALUES[following] > value:
            terms.append((cleaned[index], -value))
        else:
            terms.append((cleaned[index], value))
    return terms


def format_breakdown(terms):
    """Render signed terms as a readable arithmetic expression."""
    pieces = []
    for slot in range(len(terms)):
        if terms[slot][1] < 0:
            pieces.append("- %d" % -terms[slot][1])
        elif slot:
            pieces.append("+ %d" % terms[slot][1])
        else:
            pieces.append(str(terms[slot][1]))
    return " ".join(pieces)


def report(numerals):
    """Print a numbered table of numerals, their arithmetic and their totals."""
    width = max(len(text.strip()) for text in numerals)
    lines = []
    for number in range(len(numerals)):
        terms = breakdown(numerals[number])
        total = sum(value for _symbol, value in terms)
        lines.append(
            "%2d. %-*s = %-30s = %d"
            % (number + 1, width, numerals[number].strip().upper(), format_breakdown(terms), total)
        )
    return "\n".join(lines)


