def validate_numbers(numbers):
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    checked = []
    for index in range(len(numbers)):
        if isinstance(numbers[index], bool) or not isinstance(numbers[index], int):
            raise TypeError("element %d is not an int: %r" % (index, numbers[index]))
        checked.append(numbers[index])
    return checked


def filter_odd(numbers):
    values = validate_numbers(numbers)
    odd_numbers = []
    for value in values:
        if value % 2 != 0:
            odd_numbers.append(value)
    return odd_numbers


def odd_positions(numbers):
    values = validate_numbers(numbers)
    positions = {}
    for index in range(len(values)):
        if values[index] % 2 != 0:
            positions.setdefault(values[index], []).append(index)
    return positions


def format_table(numbers):
    values = validate_numbers(numbers)
    lines = ["idx  value  parity"]
    for index in range(len(values)):
        parity = "odd" if values[index] % 2 != 0 else "even"
        lines.append("%3d  %5d  %s" % (index, values[index], parity))
    return "\n".join(lines)


def summarize(numbers):
    odds = filter_odd(numbers)
    positions = odd_positions(numbers)
    parts = []
    for rank in range(len(odds)):
        where = ", ".join(str(p) for p in positions[odds[rank]])
        parts.append("#%d: %d at [%s]" % (rank + 1, odds[rank], where))
    if not parts:
        return "no odd numbers found"
    return "; ".join(parts)


def main():
    datasets = [
        [1, 2, 3, 4, 5],
        [2, 4, 6],
        [-7, 0, 7, 7, 12, 15],
    ]
    for case_number in range(len(datasets)):
        print("Case %d: input = %r" % (case_number + 1, datasets[case_number]))
        print(format_table(datasets[case_number]))
        print("odd numbers:", filter_odd(datasets[case_number]))
        print("summary:", summarize(datasets[case_number]))
        print()

    try:
        filter_odd([1, "three", 5])
    except TypeError as error:
        print("rejected bad input:", error)


if __name__ == "__main__":
