import os
import sys


def read_lines(filepath):
    """Return the file's lines, terminators included."""
    with open(filepath, 'r', encoding='utf-8', errors='replace') as handle:
        return handle.readlines()


def count_file_lines(filepath):
    """Return the number of lines in the file at filepath."""
    return len(read_lines(filepath))


def longest_line(lines):
    """Return (line_number, length) of the longest line, or (0, 0)."""
    best_number = 0
    best_length = 0
    for index, line in enumerate(lines):
        length = len(line.rstrip('\n'))
        if length > best_length:
            best_number = index + 1
            best_length = length
    return best_number, best_length


def blank_line_numbers(lines):
    """Return the numbers of the lines that hold only whitespace."""
    blanks = []
    for index, line in enumerate(lines):
        if not line.strip():
            blanks.append(index + 1)
    return blanks


def trailing_space_numbers(lines):
    """Return the numbers of the lines ending in stray whitespace."""
    flagged = []
    for index, line in enumerate(lines):
        stripped = line.rstrip('\n')
        if stripped != stripped.rstrip():
            flagged.append(index + 1)
    return flagged


def duplicate_line_numbers(lines):
    """Return the numbers of lines whose text appeared earlier in the file."""
    seen = {}
    repeats = []
    for index, line in enumerate(lines):
        text = line.rstrip('\n')
        if text in seen:
            repeats.append((index + 1, seen[text]))
        else:
            seen[text] = index + 1
    return repeats


def numbered_preview(lines, limit=5):
    """Return 'n: text' strings for at most the first `limit` lines."""
    head = lines[:limit]
    preview = []
    for index, line in enumerate(head):
        preview.append('{:>4}: {}'.format(index + 1, line.rstrip('\n')))
    return preview


def describe_file(filepath):
    """Build a multi-line report about the given file."""
    lines = read_lines(filepath)
    blanks = blank_line_numbers(lines)
    number, length = longest_line(lines)
    rows = [
        '{} -> {} line(s)'.format(filepath, len(lines)),
        '  non-blank:   {}'.format(len(lines) - len(blanks)),
        '  blank:       {} {}'.format(len(blanks), blanks),
        '  trailing ws: {}'.format(trailing_space_numbers(lines)),
        '  repeats:     {}'.format(duplicate_line_numbers(lines)),
        '  longest:     line {} ({} chars)'.format(number, length),
    ]
    rows.extend('  ' + row for row in numbered_preview(lines))
    return '\n'.join(rows)


def main(argv):
    paths = argv[1:]
    if not paths:
        print('usage: {} FILE [FILE ...]'.format(os.path.basename(argv[0])))
        return 1
    status = 0
    for index, path in enumerate(paths):
        if not os.path.isfile(path):
            print('{}. {}: not a readable file'.format(index + 1, path))
            status = 1
            continue
        print('{}. {}'.format(index + 1, describe_file(path)))
    return status


if __name__ == '__main__':
    sys.exit(main(sys.argv))

