        '  trailing ws: {}'.format(trailing_space_numbers(lines)),
        '  repeats:     {}'.format(duplicate_line_numbers(lines)),
        '  longest:     line {} ({} chars)'.format(number, length),
    ]
    rows.extend('  ' + row for row in numbered_preview(lines))
    return '\n'.join(rows)


def main(argv):
    paths = argv[1:]
    if not paths:
        print('usage: {} FILE [FILE ...]'.format(os.path.basename(argv[0])))
        return 1
    status = 0
    for index in range(len(paths)):
        if not os.path.isfile(paths[index]):
            print('{}. {}: not a readable file'.format(index + 1, paths[index]))
            status = 1
            continue
        print('{}. {}'.format(index + 1, describe_file(paths[index])))
    return status


if __name__ == '__main__':
    sys.exit(main(sys.argv))

