    for i, char in enumerate(url):
        if char == ':' and i > 0 and url[i-1] == 'p' and url[i-2] == 't' and url[i-3] == 't' and url[i-4] == 'h':
            if i >= 6 and url[i-5] == 's':
                if url[i+1:i+3] == '//':
                    has_scheme = True
