    if not has_scheme:
        return False

    scheme_end_index = -1
    for i, char in enumerate(url):
        if char == ':' and url[i+1:i+3] == '//':
            scheme_end_index = i + 2
            break
    if scheme_end_index == -1: return False

    domain_start_index = scheme_end_index + 1
    has_dot = False
    for i, char in enumerate(url[domain_start_index:]):
