    text = ["1 2 4", "10 10 10", "", "2 3 6 12"]
    datasets = parse_datasets(text)
    print(format_report(datasets))
    print("summary")
    for index, values in enumerate(datasets):
        print("  [%d] n=%d mean=%r" % (index, len(values), harmonic_mean(values)))


if __name__ == "__main__":
    main()

