def rectangle_area(width, height):
    """Return the area of a rectangle with the given width and height."""
    for name, value in (("width", width), ("height", height)):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must be a number, got %r" % (name, value))
        if value < 0:
            raise ValueError("%s must not be negative, got %r" % (name, value))
    return float(width) * float(height)


def parse_dimensions(text):
    """Parse lines of 'width height' into a list of (width, height) pairs."""
    pairs = []
    for lineno, line in enumerate(text.splitlines(), start=1):
        stripped = line.strip()
        if not stripped:
            continue
        fields = stripped.replace(",", " ").split()
        if len(fields) != 2:
            raise ValueError("line %d: expected two values, got %d" % (lineno, len(fields)))
        numbers = []
        for position, field in enumerate(fields):
            try:
                numbers.append(float(field))
            except ValueError:
                raise ValueError("line %d: field %d is not a number: %r"
                                 % (lineno, position + 1, field))
        pairs.append((numbers[0], numbers[1]))
    return pairs


def areas(pairs):
    """Compute the area of every (width, height) pair."""
    result = []
    for index, (width, height) in enumerate(pairs):
        try:
            result.append(rectangle_area(width, height))
        except (TypeError, ValueError) as exc:
            raise ValueError("rectangle %d: %s" % (index + 1, exc))
    return result


def largest(pairs, computed):
    """Return the 1-based index of the rectangle with the greatest area."""
    best_index = 0
    best_area = float("-inf")
    for index, area in enumerate(computed):
        if area > best_area:
            best_area = area
            best_index = index
    return best_index + 1, pairs[best_index], best_area


def format_report(pairs, computed):
    """Build a per-rectangle table plus a total line."""
    lines = ["  #   width   height       area"]
    for index, area in enumerate(computed, start=1):
        width, height = pairs[index - 1]
        lines.append("%3d %7.2f %8.2f %10.2f" % (index, width, height, area))
    lines.append("total area: %.2f" % sum(computed))
    return "\n".join(lines)


def main():
    data = "5 10\n2.5 4\n3, 3\n0.5 12\n"
    pairs = parse_dimensions(data)
    computed = areas(pairs)
    print(format_report(pairs, computed))
    rank, dims, area = largest(pairs, computed)
    print("largest: rectangle %d (%g x %g) with area %.2f" % (rank, dims[0], dims[1], area))
    for index, area in enumerate(computed, start=1):
        if area < 10.0:
            print("rectangle %d is smaller than 10 square units" % index)


if __name__ == "__main__":
    main()

