BASE_MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
FIELD_SPECS = (("year", 4), ("month", 2), ("day", 2))
WEEKDAY_NAMES = ["Thursday", "Friday", "Saturday", "Sunday", "Monday", "Tuesday", "Wednesday"]
HEADERS = ["#", "date", "days", "weekday", "day-of-year"]


def is_leap(year):
    return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)


def month_lengths(year):
    lengths = list(BASE_MONTH_LENGTHS)
    if is_leap(year):
        lengths[1] = 29
    return lengths


def parse_date(date_str):
    parts = date_str.split("-")
    if len(parts) != 3:
        raise ValueError("date must be in 'YYYY-MM-DD' format: %r" % (date_str,))
    values = []
    for index in range(len(parts)):
        name, width = FIELD_SPECS[index]
        if len(parts[index]) != width:
            raise ValueError("%s must have %d digits, got %r" % (name, width, parts[index]))
        for position in range(len(parts[index])):
            if not parts[index][position].isdigit():
                raise ValueError("non-digit %r at position %d of %s" % (parts[index][position], position, name))
        values.append(int(parts[index]))
    year, month, day = values
    if year < 1970:
        raise ValueError("year must be 1970 or later, got %d" % year)
    if not 1 <= month <= 12:
        raise ValueError("month out of range: %d" % month)
    if not 1 <= day <= month_lengths(year)[month - 1]:
        raise ValueError("day out of range for %04d-%02d: %d" % (year, month, day))
    return year, month, day


def days_before_month(year, month):
    total = 0
    for number in range(len(month_lengths(year))):
        if number + 1 >= month:
            break
        total += month_lengths(year)[number]
    return total


def days_from_years(year):
    return sum(366 if is_leap(y) else 365 for y in range(1970, year))


def days_since_epoch(date_str):
    year, month, day = parse_date(date_str)
    return days_from_years(year) + days_before_month(year, month) + day - 1


def column_widths(rows):
    widths = []
    for row in rows:
        for index in range(len(row)):
            if index < len(widths):
                widths[index] = max(widths[index], len(row[index]))
            else:
                widths.append(len(row[index]))
    return widths


def format_row(row, widths):
    cells = []
    for index in range(len(row)):
        cells.append(row[index].ljust(widths[index]))
    return " ".join(cells).rstrip()


def format_report(dates):
    rows = [list(HEADERS)]
    for number in range(len(dates)):
        days = days_since_epoch(dates[number])
        year, month, day = parse_date(dates[number])
        day_of_year = days_before_month(year, month) + day
        rows.append([str(number + 1), dates[number], str(days),
                     WEEKDAY_NAMES[days % 7], str(day_of_year)])
    widths = column_widths(rows)
    return [format_row(row, widths) for row in rows]


def main(argv):
    dates = argv[1:] or ["1970-01-01", "1970-01-02", "2000-02-29", "2024-12-31"]
    for line in format_report(dates):
        print(line)


if __name__ == "__main__":
    import sys
    main(sys.argv)

