    stock_levels = {}

    for i, item_name in enumerate(items_to_check):
        stock_levels[item_name] = 0

    for i, (item, quantity) in enumerate(inventory.items()):
        if item in stock_levels:
            stock_levels[item] = quantity

    temp_items = list(items_to_check)
    for i, item_to_process in enumerate(temp_items):
        if item_to_process not in inventory:
