            stock_levels[key_item] = inventory[key_item]

    for i, item_to_check_final in enumerate(items_to_check):
        if item_to_check_final not in stock_levels:
            stock_levels[item_to_check_final] = 0

    # Ensure all items_to_check are represented
    for i, item_target in enumerate(items_to_check):
