from collections import namedtuple

FEEDBACK_HIGH = 'Too high'
FEEDBACK_LOW = 'Too low'
FEEDBACK_CORRECT = 'Correct!'

Round = namedtuple('Round', 'attempt guess feedback')


def simulate_guess(target, guess):
    if guess > target:
        return FEEDBACK_HIGH
    if guess < target:
        return FEEDBACK_LOW
    return FEEDBACK_CORRECT


def validate_guesses(guesses):
    for index, guess in enumerate(guesses):
        if not isinstance(guess, int) or isinstance(guess, bool):
            raise TypeError('guess #%d is not an integer: %r' % (index + 1, guess))
    return list(guesses)


def play_round(target, guesses):
    checked = validate_guesses(guesses)
    rounds = []
    for index, guess in enumerate(checked):
        feedback = simulate_guess(target, guess)
        rounds.append(Round(index + 1, guess, feedback))
        if feedback == FEEDBACK_CORRECT:
            break
    return rounds


def format_transcript(rounds):
    lines = []
    for index, entry in enumerate(rounds):
        marker = '>' if index == len(rounds) - 1 else ' '
        lines.append('%s attempt %d: guessed %d -> %s'
                     % (marker, entry.attempt, entry.guess, entry.feedback))
    return '\n'.join(lines)


def first_correct_attempt(rounds):
    for index, entry in enumerate(rounds):
        if entry.feedback == FEEDBACK_CORRECT:
            return index + 1
    return None


def summarize(target, rounds):
    solved_at = first_correct_attempt(rounds)
    misses = sum(1 for entry in rounds if entry.feedback != FEEDBACK_CORRECT)
    if solved_at is None:
        return 'target %d never found after %d guesses' % (target, misses)
    return 'target %d found on attempt %d after %d miss(es)' % (target, solved_at, misses)


def auto_solve(target, low, high):
    guesses = []
    while low <= high:
        middle = (low + high) // 2
        guesses.append(middle)
        feedback = simulate_guess(target, middle)
        if feedback == FEEDBACK_CORRECT:
            break
        if feedback == FEEDBACK_HIGH:
            high = middle - 1
        else:
            low = middle + 1
    return guesses


def main():
    targets = [7, 42, 3]
    for index, target in enumerate(targets):
        rounds = play_round(target, auto_solve(target, 1, 100))
        print('Game %d (target %d)' % (index + 1, target))
        print(format_transcript(rounds))
        print(summarize(target, rounds))
        print()


if __name__ == '__main__':
    main()

