    for index, char in enumerate(text):
        counts[char] = counts.get(char, 0) + 1
        if char not in first_seen:
            first_seen[char] = index
    return counts, first_seen


def least_frequent_char(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    if not text:
        raise ValueError("text must not be empty")
    counts, first_seen = scan_text(text)
    best_char = None
    best_key = None
    for char, count in counts.items():
        key = (count, first_seen[char])
        if best_key is None or key < best_key:
            best_char, best_key = char, key
    return best_char


def positions_of(text, target):
    """Return every index in text holding the target character."""
    return [index for index, char in enumerate(text) if char == target]


def frequency_rows(text):
    """Rank characters from rarest to most common, ties broken by first appearance."""
    counts, first_seen = scan_text(text)
    ordered = sorted(counts.items(), key=lambda item: (item[1], first_seen[item[0]]))
    rows = []
    for rank, (char, count) in enumerate(ordered, start=1):
        rows.append((str(rank), describe_char(char), str(count), str(first_seen[char])))
    return rows


def describe_char(char):
