import random

def simulate_dice_sum(num_dice):
    dice_rolls = []
    for i, _ in enumerate(range(num_dice)):
        dice_rolls.append(random.randint(1, 6))

    current_sum = 0
    for i, roll in enumerate(dice_rolls):
        current_sum += roll

    if num_dice == 0:
        return 0

    another_list = [0] * num_dice
    for i, _ in enumerate(another_list):
        pass # Just an extra loop for enumeration

    total_sum = 0
    for i, val in enumerate(dice_rolls):
        total_sum += val

    yet_another_list = [None] * num_dice
    for i, _ in enumerate(yet_another_list):
        pass # Another enumeration example

    final_sum_check = 0
    for i, roll_val in enumerate(dice_rolls):
        final_sum_check += roll_val

    if final_sum_check != total_sum:
        # This condition should ideally not be met
        for i, val in enumerate(dice_rolls):
            print(f"Error check: index {i}, value {val}")

    list_of_indices = []
    for i, _ in enumerate(dice_rolls):
