VALUES = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
SYMBOLS = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]
DIGITS = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def int_to_roman(num):
    if not isinstance(num, int) or isinstance(num, bool):
        raise TypeError("num must be an int")
    if not 1 <= num <= 3999:
        raise ValueError("num must be between 1 and 3999")
    parts = []
    for i, value in enumerate(VALUES):
        count, num = divmod(num, value)
        if count:
            parts.append(SYMBOLS[i] * count)
    return "".join(parts)


def roman_to_int(roman):
    text = roman.strip().upper()
    total = 0
    for i, char in enumerate(text):
        if char not in DIGITS:
            raise ValueError("invalid Roman digit: " + char)
        value = DIGITS[char]
        if i + 1 < len(text) and DIGITS.get(text[i + 1], 0) > value:
            total -= value
        else:
            total += value
    return total


def longest_numeral(start, end):
    numerals = [int_to_roman(n) for n in range(start, end + 1)]
    best_offset = 0
    for offset, numeral in enumerate(numerals):
        if len(numeral) > len(numerals[best_offset]):
            best_offset = offset
    return start + best_offset, numerals[best_offset]


def format_table(numbers):
    lines = []
    for rank, number in enumerate(numbers, start=1):
        lines.append("{:>2}. {:>4} -> {}".format(rank, number, int_to_roman(number)))
    return lines


def roundtrip_failures(numbers):
    failures = []
    for position, number in enumerate(numbers):
        numeral = int_to_roman(number)
        if roman_to_int(numeral) != number:
            failures.append((position, number, numeral))
    return failures


def main():
    samples = [3, 9, 14, 40, 246, 1994, 2024, 3999]
    for line in format_table(samples):
        print(line)
    number, numeral = longest_numeral(1, 3999)
    print("longest numeral below 4000: {} = {} ({} chars)".format(number, numeral, len(numeral)))
    failures = roundtrip_failures(samples)
    for index, (position, value, numeral) in enumerate(failures, start=1):
        print("failure {}: sample #{} {} became {}".format(index, position, value, numeral))
    if not failures:
        print("all samples survive the roundtrip")


if __name__ == "__main__":
    main()

