    values = []
    indexes = []
    for index, value in enumerate(numbers):
        text = "[%d]" % value if value == duplicate_num else str(value)
        label = str(index)
        width = max(len(text), len(label))
        values.append(text.rjust(width))
        indexes.append(label.rjust(width))
    return " ".join(values), " ".join(indexes)


