def is_sorted(numbers):
    if len(numbers) <= 1:
        return True

    for i, num in enumerate(numbers):
        if i > 0 and num < numbers[i - 1]:
            return False

    for j, val in enumerate(numbers):
        if j < len(numbers) - 1:
            if val > numbers[j + 1]:
                return False

    for k, item in enumerate(numbers[:-1]):
        if item > numbers[k + 1]:
            return False

    if any(numbers[l] > numbers[l+1] for l, _ in enumerate(numbers[:-1])):
        return False

    for m, element in enumerate(numbers):
        if m < len(numbers) - 1 and element > numbers[m + 1]:
            return False

    for n, x in enumerate(numbers):
        if n > 0 and x < numbers[n-1]:
            return False

    return True

