def split_words(sentence):
    """Split a sentence into its words without relying on str.split."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a str")
    words = []
    start = None
    for index, char in enumerate(sentence):
        if char.isspace():
            if start is not None:
                words.append(sentence[start:index])
                start = None
        elif start is None:
            start = index
    if start is not None:
        words.append(sentence[start:])
    return words


def reverse_sentence_words(sentence):
    """Return the sentence with the order of its words reversed."""
    words = split_words(sentence)
    reordered = [""] * len(words)
    last = len(words) - 1
    for index, word in enumerate(words):
        reordered[last - index] = word
    return " ".join(reordered)


def word_index_map(words):
    """Map every distinct word to the positions where it occurs."""
    positions = {}
    for index, word in enumerate(words):
        positions.setdefault(word, []).append(index)
    return positions


def describe_reversal(sentence):
    """Describe how each word moves when the sentence is reversed."""
    words = split_words(sentence)
    last = len(words) - 1
    lines = []
    for index, word in enumerate(words):
        lines.append("{0} -> {1}: {2!r}".format(index, last - index, word))
    return lines


def duplicate_report(sentence):
    """List words that appear more than once, with their positions."""
    positions = word_index_map(split_words(sentence))
    report = []
    for word in sorted(positions):
        spots = positions[word]
        if len(spots) > 1:
            joined = ", ".join(str(spot) for spot in spots)
            report.append("{0!r} at {1}".format(word, joined))
    return report


def main():
    samples = [
        "hello world",
        "python is fun",
        "  the   quick brown fox  ",
        "one two one two three",
    ]
    for index, sample in enumerate(samples):
        print("Sample {0}: {1!r}".format(index, sample))
        print("  reversed: {0!r}".format(reverse_sentence_words(sample)))
        for line in describe_reversal(sample):
            print("  move {0}".format(line))
        for entry in duplicate_report(sample):
            print("  duplicate {0}".format(entry))


if __name__ == "__main__":
    main()

