def count_all_chars(text):
    """Return a dict mapping each character of text to its occurrence count."""
    counts = {}
    for character in text:
        counts[character] = counts.get(character, 0) + 1
    return counts


def most_frequent(text):
    """Return (character, count) for the most frequent character, ties by first appearance."""
    best_char = None
    best_count = 0
    for character, count in count_all_chars(text).items():
        if count > best_count:
            best_char = character
            best_count = count
    return best_char, best_count


def build_report(pairs):
    """Turn (text, char) pairs into numbered report lines."""
    lines = []
    for number in range(len(pairs)):
        (text, char) = pairs[number]
        count = count_char(text, char)
        lines.append("%d. %r contains %r %d time(s)" % (number + 1, text, char, count))
        if "\n" in text:
            for lineno, line_count in count_per_line(text, char):
                lines.append("   line %d: %d" % (lineno, line_count))
        else:
            lines.append("   " + text)
            lines.append("   " + format_positions(text, char))
        top_char, top_count = most_frequent(text)
        lines.append("   most frequent: %r (%d)" % (top_char, top_count))
    return lines


def main():
    samples = [("banana", "a"), ("Mississippi", "s"), ("one\ntwo\nthree", "e")]
    for line in build_report(samples):
        print(line)
    for order in range(len(find_positions("Mississippi", "i"))):
        print("occurrence %d of 'i' is at index %d" % (order + 1, find_positions("Mississippi", "i")[order]))


if __name__ == "__main__":
    main()

