import random


def roll_die(num_sides):
    """Return a random integer from 1 to num_sides inclusive."""
    if not isinstance(num_sides, int) or isinstance(num_sides, bool):
        raise TypeError("num_sides must be an int")
    if num_sides < 1:
        raise ValueError("num_sides must be at least 1")
    return random.randint(1, num_sides)


def roll_many(num_sides, times):
    """Roll an N-sided die `times` times and return the list of results."""
    if times < 0:
        raise ValueError("times must be non-negative")
    return [roll_die(num_sides) for _ in range(times)]


def roll_pool(specs):
    """Roll one die per (num_sides, label) spec, returning labelled results."""
    return [(label, roll_die(num_sides)) for num_sides, label in specs]


def format_pool(results):
    """Render labelled pool results as numbered, aligned lines."""
    width = max((len(label) for label, _ in results), default=0)
    lines = []
    for position, (label, value) in enumerate(results, start=1):
        lines.append("#{} {:<{w}} -> {}".format(position, label, value, w=width))
    return lines


def tally(rolls, num_sides):
    """Count how often each face appeared; index 0 holds face 1."""
    counts = [0] * num_sides
    for value in rolls:
        counts[value - 1] += 1
    return counts


def histogram(counts, scale=40):
    """Build bar-chart lines for a tally, one line per face."""
    biggest = max(counts) if counts else 0
    total = sum(counts)
    lines = []
    for offset, count in enumerate(counts):
        bar_len = 0 if biggest == 0 else round(count * scale / biggest)
        share = 0.0 if total == 0 else 100.0 * count / total
        lines.append("{:>3} | {:<{s}} {:>4} ({:4.1f}%)".format(
            offset + 1, "#" * bar_len, count, share, s=scale))
    return lines


def first_appearance(rolls, num_sides):
    """Return, per face, the 1-based roll number where it first showed up."""
    seen = [None] * num_sides
    missing = num_sides
    for index, value in enumerate(rolls):
        if seen[value - 1] is None:
            seen[value - 1] = index + 1
            missing -= 1
            if missing == 0:
                break
    return seen


def positions_of(rolls, face):
    """Return the 1-based roll numbers on which `face` came up."""
    return [index + 1 for index, value in enumerate(rolls) if value == face]


def longest_streak(rolls):
    """Return (face, length, start_index) of the longest run of equal rolls."""
    best = (None, 0, 0)
    start = 0
    for index, value in enumerate(rolls):
        if index and value != rolls[index - 1]:
            start = index
        length = index - start + 1
        if length > best[1]:
            best = (value, length, start)
    return best


def main():
    random.seed(20260918)
    for line in format_pool(roll_pool([(6, "damage"), (20, "attack"),
                                       (4, "bonus"), (100, "loot")])):
        print(line)

    sides, trials = 6, 300
    rolls = roll_many(sides, trials)
    counts = tally(rolls, sides)
    print("\n{} rolls of a d{}".format(trials, sides))
    for line in histogram(counts):
        print(line)

    face, length, start = longest_streak(rolls)
    print("longest streak: {} x face {} from roll {}".format(length, face, start + 1))
    print("every face seen by roll {}".format(max(first_appearance(rolls, sides))))
    top = counts.index(max(counts)) + 1
    print("face {} landed on rolls {}".format(top, positions_of(rolls, top)[:8]))
    preview = rolls[:10]
    for number, value in enumerate(preview, start=1):
        print("roll {:>2}: {}".format(number, value))


if __name__ == "__main__":
    main()

def validate_coordinates(values, labels):
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, int):
            raise TypeError(f"{labels[index]} must be an int, got {type(value).__name__}")


def normalize_rectangle(x1, y1, x2, y2):
    return min(x1, x2), min(y1, y2), max(x1, x2), max(y1, y2)


def is_point_in_rectangle(px, py, x1, y1, x2, y2):
    validate_coordinates((px, py, x1, y1, x2, y2), ("px", "py", "x1", "y1", "x2", "y2"))
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    return left <= px <= right and bottom <= py <= top


def describe_position(px, py, x1, y1, x2, y2):
    if not is_point_in_rectangle(px, py, x1, y1, x2, y2):
        return "outside"
    left, bottom, right, top = normalize_rectangle(x1, y1, x2, y2)
    if px in (left, right) or py in (bottom, top):
        return "edge"
    return "inside"


def indices_inside(points, rect):
    return [index for index, (px, py) in enumerate(points) if is_point_in_rectangle(px, py, *rect)]


def first_outside_index(points, rect):
    for index, (px, py) in enumerate(points):
        if not is_point_in_rectangle(px, py, *rect):
            return index
    return -1


def format_table(points, rect):
    lines = ["idx  point     position"]
    for index, (px, py) in enumerate(points):
        position = describe_position(px, py, *rect)
        lines.append(f"{index:<4} ({px:>2},{py:>2})   {position}")
    return "\n".join(lines)


def render_grid(points, rect, width, height):
    grid = [["." for _ in range(width)] for _ in range(height)]
    for row_index, row in enumerate(grid):
        y = height - 1 - row_index
        for x in range(width):
            if is_point_in_rectangle(x, y, *rect):
                row[x] = "#"
    for index, (px, py) in enumerate(points):
        if 0 <= px < width and 0 <= py < height:
            grid[height - 1 - py][px] = str(index % 10)
    return "\n".join("".join(row) for row in grid)


