        rows.append("%2d. %-10s %4d  (%s)" % (position, requested[i], quantity, status))
    return rows


def low_stock_items(inventory, threshold):
    return sorted(name for name in inventory if get_item_quantity(inventory, name) < threshold)


def restock_plan(inventory, threshold):
    plan = []
    low_stock = low_stock_items(inventory, threshold)
    for i in range(len(low_stock)):
        rank = i + 1
        plan.append((rank, low_stock[i], threshold - get_item_quantity(inventory, low_stock[i])))
    return plan


def main():
