def validate_interval(start, end, label):
    for value in (start, end):
        if not isinstance(value, int) or isinstance(value, bool):
            raise TypeError("%s times must be ints" % label)
        if not 0 <= value <= 24:
            raise ValueError("%s times must fall within 0..24" % label)
    if start >= end:
        raise ValueError("%s must start before it ends" % label)


def has_overlap(task1_start, task1_end, task2_start, task2_end):
    validate_interval(task1_start, task1_end, "task1")
    validate_interval(task2_start, task2_end, "task2")
    return task1_start < task2_end and task2_start < task1_end


def find_conflicts(tasks):
    conflicts = []
    for i, (name_a, start_a, end_a) in enumerate(tasks):
        for j in range(i + 1, len(tasks)):
            name_b, start_b, end_b = tasks[j]
            if has_overlap(start_a, end_a, start_b, end_b):
                conflicts.append((name_a, name_b,
                                  max(start_a, start_b), min(end_a, end_b)))
    return conflicts


def hourly_load(tasks):
    load = [0] * 24
    for task in tasks:
        for hour in range(task[1], task[2]):
            load[hour] += 1
    return load


def busiest_hours(load):
    peak = max(load)
    if peak == 0:
        return 0, []
    return peak, [hour for hour, count in enumerate(load) if count == peak]


def format_timeline(load):
    lines = []
    for hour, count in enumerate(load):
        if count:
            lines.append("  %02d:00 %s" % (hour, "#" * count))
    return "\n".join(lines)


def format_schedule(tasks):
    lines = []
    for number, (name, start, end) in enumerate(tasks, start=1):
        lines.append("%d. %-14s %02d:00-%02d:00 (%dh)"
                     % (number, name, start, end, end - start))
    return "\n".join(lines)


def format_conflicts(conflicts):
    if not conflicts:
        return "No conflicts detected."
    lines = ["Conflicts:"]
    for number, (name_a, name_b, start, end) in enumerate(conflicts, start=1):
        lines.append("  %d) '%s' and '%s' clash %02d:00-%02d:00"
                     % (number, name_a, name_b, start, end))
    return "\n".join(lines)


def main():
    tasks = [
