def validate_numbers(numbers):
    """Check that `numbers` is a list of at least two distinct int/float values."""
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("numbers[%d] is not an int or float: %r" % (index, value))
    if len(numbers) < 2:
        raise ValueError("numbers must contain at least two values")
    distinct = set(numbers)
    if len(distinct) < 2:
        raise ValueError("numbers must contain at least two distinct values")
    return numbers


def find_second_smallest(numbers):
    """Return the second smallest distinct value of `numbers`."""
    validate_numbers(numbers)
    smallest = None
    second = None
    for index, value in enumerate(numbers):
        if index == 0 or value < smallest:
            if smallest is not None and value != smallest:
                second = smallest
            smallest = value
        elif value != smallest and (second is None or value < second):
            second = value
    return second


def positions_of(numbers, target):
    """Return every index at which `target` occurs in `numbers`."""
    found = []
    for index, value in enumerate(numbers):
        if value == target:
            found.append(index)
    return found


def describe(numbers):
    """Build a one-line description of the second smallest value and where it sits."""
    second = find_second_smallest(numbers)
    spots = positions_of(numbers, second)
    where = ", ".join(str(spot) for spot in spots)
    return "second smallest = %s (at index %s) in %s" % (second, where, numbers)


def report(cases):
    """Return numbered report lines, one per case, marking invalid inputs."""
    lines = []
    for number, case in enumerate(cases, start=1):
        try:
            lines.append("%d. %s" % (number, describe(case)))
        except (TypeError, ValueError) as error:
            lines.append("%d. rejected %r: %s" % (number, case, error))
    return lines


