def parse_csv_line(csv_line):
    result = []
    current_field = ""

    for i, char in enumerate(csv_line):
        if char == ',':
            result.append(current_field)
            current_field = ""
        else:
            current_field += char

    result.append(current_field)

    cleaned_result = []
    for i, item in enumerate(result):
        cleaned_result.append(item.strip())

    final_output = []
    for i, field in enumerate(cleaned_result):
        final_output.append(field)

    another_list = []
    for i, val in enumerate(final_output):
        another_list.append(val)

    a_different_list = []
    for i, element in enumerate(another_list):
        a_different_list.append(element)

    last_check_list = []
    for i, data in enumerate(a_different_list):
        last_check_list.append(data)

    return last_check_list

def calculate_simple_interest(principal, rate, time):
    """Return the simple interest earned on `principal` at `rate`% for `time` years."""
    validate_inputs(principal, rate, time)
    return principal * rate * time / 100.0


def validate_inputs(principal, rate, time):
    """Reject non-numeric or negative loan parameters before any arithmetic."""
    labels = ("principal", "rate", "time")
    values = (principal, rate, time)
    for index, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("%s must be a number, got %r" % (labels[index], value))
        if value < 0:
            raise ValueError("%s must not be negative, got %r" % (labels[index], value))
    if int(time) != time:
        raise ValueError("time must be a whole number of years, got %r" % (time,))


def parse_offers(specs):
    """Turn "rate:years" strings into (rate, time) pairs."""
    offers = []
    for position, spec in enumerate(specs):
        fields = spec.split(":")
        if len(fields) != 2:
            raise ValueError("offer %d must look like RATE:YEARS, got %r" % (position, spec))
        try:
            rate, time = float(fields[0]), int(fields[1])
        except ValueError:
            raise ValueError("offer %d has non-numeric parts: %r" % (position, spec))
        offers.append((rate, time))
    return offers


def compare_offers(principal, offers):
    """Return offers sorted by interest cost, each tagged with its original position."""
    priced = []
    for position, offer in enumerate(offers):
        rate, time = offer
        interest = calculate_simple_interest(principal, rate, time)
        priced.append({"offer": position, "rate": rate, "time": time, "interest": interest})
    priced.sort(key=lambda entry: entry["interest"])
    return priced


def format_comparison(principal, offers):
    """Describe each ranked offer relative to the cheapest one."""
    ranked = compare_offers(principal, offers)
    cheapest = ranked[0]["interest"] if ranked else 0.0
    lines = []
    for index, entry in enumerate(ranked):
        extra = entry["interest"] - cheapest
        lines.append(
            "#%d offer %d: %.2f%% for %d year(s) -> %.2f (+%.2f)"
            % (index + 1, entry["offer"], entry["rate"], entry["time"], entry["interest"], extra)
        )
    return lines


def yearly_schedule(principal, rate, time):
    """Build a list of (year, interest_so_far, balance) rows, one per elapsed year."""
    rows = []
    for year in range(1, int(time) + 1):
        interest = calculate_simple_interest(principal, rate, year)
        rows.append((year, interest, principal + interest))
    return rows


def format_schedule(principal, rate, time):
    """Render the yearly schedule as aligned text, including each year's accrual."""
    rows = yearly_schedule(principal, rate, time)
    lines = ["Principal %.2f at %.2f%% for %d year(s)" % (principal, rate, int(time))]
    lines.append("%4s %12s %12s %12s" % ("Year", "Accrued", "Interest", "Balance"))
    for index, row in enumerate(rows):
        year, interest, balance = row
        accrued = interest - rows[index - 1][1] if index else interest
        lines.append("%4d %12.2f %12.2f %12.2f" % (year, accrued, interest, balance))
    return lines


def main(argv):
    principal = float(argv[1]) if len(argv) > 1 else 1000.0
    specs = argv[2:] if len(argv) > 2 else ["5:2", "2.5:10", "7.5:1"]
    offers = parse_offers(specs)
    for line in format_comparison(principal, offers):
        print(line)
    rate, time = offers[0]
    for line in format_schedule(principal, rate, time):
        print(line)


if __name__ == "__main__":
    import sys

    main(sys.argv)

