def validate_inputs(principal, rate, compounding_frequency, time_years):
    """Check the four inputs and raise ValueError naming the offending argument."""
    spec = [
        ("principal", principal, (int, float)),
        ("rate", rate, (int, float)),
        ("compounding_frequency", compounding_frequency, int),
        ("time_years", time_years, int),
    ]
    for position, (name, value, expected) in enumerate(spec, start=1):
        if isinstance(value, bool) or not isinstance(value, expected):
            raise TypeError(
                "argument %d (%s) must be %s, got %r"
                % (position, name, getattr(expected, "__name__", "a number"), value)
            )
        if value < 0:
            raise ValueError("argument %d (%s) must not be negative" % (position, name))
    if compounding_frequency == 0:
        raise ValueError("argument 3 (compounding_frequency) must be at least 1")


def calculate_compound_interest(principal, rate, compounding_frequency, time_years):
    """Return the total amount after compounding, principal included."""
    validate_inputs(principal, rate, compounding_frequency, time_years)
    periodic_rate = 1.0 + rate / compounding_frequency
    return float(principal) * periodic_rate ** (compounding_frequency * time_years)


def yearly_balances(principal, rate, compounding_frequency, time_years):
    """Total amount at the end of each year, from year 1 to time_years."""
    return [
        calculate_compound_interest(principal, rate, compounding_frequency, year)
        for year in range(1, time_years + 1)
    ]


def format_schedule(principal, balances):
    lines = []
    for year, amount in enumerate(balances, start=1):
        interest = amount - principal
        lines.append("  year %2d: balance %12.2f  interest earned %10.2f" % (year, amount, interest))
    return lines


def compare_frequencies(principal, rate, time_years, frequencies):
    """Pair each compounding frequency with its final amount and the gain over the previous one."""
    results = []
    for index, frequency in enumerate(frequencies):
        amount = calculate_compound_interest(principal, rate, frequency, time_years)
        gain = amount - results[index - 1][1] if index else 0.0
        results.append((frequency, amount, gain))
    return results


def format_comparison(results):
    lines = []
    for rank, (frequency, amount, gain) in enumerate(results, start=1):
        lines.append("  %d) %4d/year -> %12.2f  (+%.4f vs previous)" % (rank, frequency, amount, gain))
    return lines


def main():
    scenarios = [
        (1000.0, 0.05, 1, 1),
        (1000.0, 0.05, 4, 1),
        (2500.0, 0.07, 12, 5),
    ]
    for number, (principal, rate, frequency, years) in enumerate(scenarios, start=1):
        total = calculate_compound_interest(principal, rate, frequency, years)
        print(
            "Scenario %d: %.2f at %.2f%% compounded %d time(s)/year for %d year(s) -> %r"
            % (number, principal, rate * 100, frequency, years, total)
        )
        for line in format_schedule(principal, yearly_balances(principal, rate, frequency, years)):
            print(line)

    principal, rate, years = 1000.0, 0.05, 10
    print("Frequency comparison for %.2f at %.2f%% over %d years:" % (principal, rate * 100, years))
    for line in format_comparison(compare_frequencies(principal, rate, years, [1, 2, 4, 12, 365])):
        print(line)


if __name__ == "__main__":
    main()

