def parse_url_params(query_string):
    """Parse a URL query string into a dictionary of key-value pairs."""
    params = {}
    for index, chunk in enumerate(query_string.split('&')):
        chunk = chunk.strip()
        if not chunk:
            continue
        key, separator, value = chunk.partition('=')
        key = key.strip()
        if not key:
            raise ValueError('parameter %d has an empty key: %r' % (index, chunk))
        params[key] = value if separator else ''
    return params


def find_duplicate_keys(query_string):
    """Return keys that appear more than once, with the positions where they occur."""
    positions = {}
    for index, chunk in enumerate(query_string.split('&')):
        chunk = chunk.strip()
        if chunk:
            key = chunk.partition('=')[0].strip()
            positions.setdefault(key, []).append(index)
    return {key: spots for key, spots in positions.items() if len(spots) > 1}


def find_flag_params(query_string):
    """Return (position, key) for parameters written without an '=' separator."""
    flags = []
    for index, chunk in enumerate(query_string.split('&')):
        chunk = chunk.strip()
        if chunk and '=' not in chunk:
            flags.append((index, chunk))
    return flags


def format_params(params):
    """Render parsed parameters as a numbered, aligned report."""
    if not params:
        return '  (no parameters)'
    width = max(len(key) for key in params)
    lines = []
    for index, (key, value) in enumerate(params.items()):
        shown = value if value else '<empty>'
        lines.append('  %d. %-*s = %s' % (index + 1, width, key, shown))
    return '\n'.join(lines)


def rebuild_query(params):
    """Rebuild a canonical query string from parsed parameters."""
    return '&'.join('%s=%s' % (key, value) for key, value in params.items())


def main():
    samples = [
        'name=John&age=30',
        'q=python+programming',
        'a=1&b=&a=2&flag',
        '=broken&x=1',
        '',
    ]
    for index, query in enumerate(samples):
        print('Sample %d: %r' % (index + 1, query))
        try:
            params = parse_url_params(query)
        except ValueError as error:
            print('  error: %s' % error)
            continue
        print(format_params(params))
        for key, spots in find_duplicate_keys(query).items():
            print('  duplicate key %r at positions %s (last value kept)' % (key, spots))
        for position, key in find_flag_params(query):
            print('  parameter %d (%r) has no value' % (position, key))
        print('  rebuilt: %r' % rebuild_query(params))


if __name__ == '__main__':
    main()

