def validate_strings(strings):
    """Return the input as a list of str, raising TypeError on bad entries."""
    if not isinstance(strings, (list, tuple)):
        raise TypeError("strings must be a list of str")
    checked = []
    for index, item in enumerate(strings):
        if not isinstance(item, str):
            raise TypeError("item at position {} is {}, not str".format(index, type(item).__name__))
        checked.append(item)
    return checked


def longest_common_prefix(strings):
    """Longest common prefix shared by every string in the list."""
    items = validate_strings(strings)
    if not items:
        return ""
    shortest = min(items, key=len)
    for index, char in enumerate(shortest):
        for other in items:
            if other[index] != char:
                return shortest[:index]
    return shortest


def divergence_points(strings, prefix):
    """Map each string's position to the character that ends its agreement."""
    points = {}
    for index, item in enumerate(strings):
        if len(item) > len(prefix):
            points[index] = item[len(prefix)]
    return points


def format_report(strings, prefix):
    """Build a human-readable summary of the prefix search."""
    shown = prefix if prefix else "(none)"
    lines = ["common prefix: {}".format(shown)]
    points = divergence_points(strings, prefix)
    for index, item in enumerate(strings):
        marker = points.get(index)
        tail = " -> diverges at '{}'".format(marker) if marker else " -> fully covered"
        lines.append("  {}. {!r}{}".format(index + 1, item, tail))
    return "\n".join(lines)


def main():
    datasets = [
        ['flower', 'flow', 'flight'],
        ['dog', 'racecar', 'car'],
        ['interspecies', 'interstellar', 'interstate'],
        ['same', 'same', 'same'],
        [],
    ]
    for index, dataset in enumerate(datasets):
        prefix = longest_common_prefix(dataset)
        print("case {}: {!r}".format(index + 1, prefix))
        if dataset:
            print(format_report(dataset, prefix))


if __name__ == "__main__":
    main()

