def validate_input(data, window_size):
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an integer")
    if window_size <= 0:
        raise ValueError("window_size must be positive")
    if not isinstance(data, (list, tuple)):
        raise TypeError("data must be a list of numbers")
    for index, value in enumerate(data):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("data[%d] is not a number: %r" % (index, value))
    if len(data) < window_size:
        raise ValueError("data has %d points, fewer than window_size %d" % (len(data), window_size))


def calculate_sma(data, window_size):
    validate_input(data, window_size)
    averages = []
    window_sum = 0.0
    for index, value in enumerate(data):
        window_sum += value
        if index >= window_size:
            window_sum -= data[index - window_size]
        if index >= window_size - 1:
            averages.append(window_sum / window_size)
    return averages


def describe_trend(averages):
    labels = []
    for index, average in enumerate(averages):
        if index == 0:
            labels.append("start")
        elif average > averages[index - 1]:
            labels.append("rising")
        elif average < averages[index - 1]:
            labels.append("falling")
        else:
            labels.append("flat")
    return labels


def find_extremes(averages):
    highest = 0
    lowest = 0
    for index, average in enumerate(averages):
        if average > averages[highest]:
            highest = index
        if average < averages[lowest]:
            lowest = index
    return highest, lowest


def format_report(data, window_size, averages):
    trend = describe_trend(averages)
    highest, lowest = find_extremes(averages)
    lines = ["window=%d over %d points" % (window_size, len(data))]
    for offset, average in enumerate(averages):
        end = offset + window_size - 1
        span = ", ".join(str(value) for value in data[offset:end + 1])
        notes = trend[offset]
        if offset == highest:
            notes += ", peak"
        if offset == lowest:
            notes += ", trough"
        lines.append("  points[%d..%d] = [%s] -> %.2f (%s)" % (offset, end, span, average, notes))
    return "\n".join(lines)


def main():
    datasets = [
        ([1, 2, 3, 4, 5], 3),
        ([10, 20, 30, 40], 2),
        ([4.5, 4.5, 3.0, 7.5, 6.0, 6.0], 3),
        ([7], 1),
        ([1, 2], 5),
    ]
    for data, window_size in datasets:
        print("input: %s" % (data,))
        try:
            averages = calculate_sma(data, window_size)
        except (TypeError, ValueError) as error:
            print("  rejected: %s" % error)
            continue
        print(format_report(data, window_size, averages))
        print("  result: %s" % averages)


if __name__ == "__main__":
    main()

