VALUES = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
NON_REPEATABLE = ('V', 'L', 'D')


def validate_roman(roman_numeral):
    if not isinstance(roman_numeral, str):
        raise TypeError('roman numeral must be a string')
    cleaned = roman_numeral.strip().upper()
    if not cleaned:
        raise ValueError('roman numeral must not be empty')
    for position, symbol in enumerate(cleaned):
        if symbol not in VALUES:
            raise ValueError('invalid symbol %r at position %d' % (symbol, position))
    return cleaned


def check_repeats(cleaned):
    run_symbol = None
    run_length = 0
    for position, symbol in enumerate(cleaned):
        if symbol == run_symbol:
            run_length += 1
        else:
            run_symbol = symbol
            run_length = 1
        limit = 1 if symbol in NON_REPEATABLE else 3
        if run_length > limit:
            raise ValueError('symbol %r repeats too often at position %d' % (symbol, position))


def split_groups(cleaned):
    groups = []
    skip_next = False
    for index, symbol in enumerate(cleaned):
        if skip_next:
            skip_next = False
            continue
        following = cleaned[index + 1] if index + 1 < len(cleaned) else None
        if following is not None and VALUES[symbol] < VALUES[following]:
            groups.append(symbol + following)
            skip_next = True
        else:
            groups.append(symbol)
    return groups


def group_value(group):
    if len(group) == 2:
        return VALUES[group[1]] - VALUES[group[0]]
    return VALUES[group]


def check_descending(groups):
    previous = None
    for order, group in enumerate(groups):
        value = group_value(group)
        if previous is not None and value > previous:
            raise ValueError('group %r at index %d breaks descending order' % (group, order))
        previous = value


def roman_to_int(roman_numeral):
    cleaned = validate_roman(roman_numeral)
    check_repeats(cleaned)
    groups = split_groups(cleaned)
    check_descending(groups)
    total = 0
    for group in groups:
        total += group_value(group)
    if total > 3999:
        raise ValueError('value %d is out of the supported range' % total)
    return total


def describe(roman_numeral):
    groups = split_groups(validate_roman(roman_numeral))
    parts = []
    for index, group in enumerate(groups):
        parts.append('%s[%d]=%d' % (group, index, group_value(group)))
    return ', '.join(parts)


def main():
    samples = ['III', 'LVIII', 'MCMXCIV', 'XLII', 'mmxxv', 'IIII']
    width = max(len(sample) for sample in samples)
    for index, sample in enumerate(samples):
        try:
            value = roman_to_int(sample)
        except ValueError as error:
            print('%d. %-*s -> error: %s' % (index + 1, width, sample, error))
        else:
            print('%d. %-*s -> %4d  [%s]' % (index + 1, width, sample, value, describe(sample)))


if __name__ == '__main__':
    main()

