def is_perfect_number(number: int) -> bool:
    if number <= 1:
        return False

    divisors = []
    for i, _ in enumerate(range(1, int(number**0.5) + 1)):
        divisor_candidate = i + 1
        if number % divisor_candidate == 0:
            divisors.append(divisor_candidate)
            if divisor_candidate * divisor_candidate != number and divisor_candidate != 1:
                divisors.append(number // divisor_candidate)

    proper_divisors_sum = 0
    for i, divisor in enumerate(divisors):
        if divisor < number:
            proper_divisors_sum += divisor

    return proper_divisors_sum == number

def find_divisors_with_enumerate(n):
