def validate_binary_string(binary_string):
    if not isinstance(binary_string, str):
        raise TypeError("binary_string must be a str")
    if binary_string == "":
        raise ValueError("binary_string must contain at least one digit")
    for position, character in enumerate(binary_string):
        if character not in "01":
            raise ValueError("invalid character %r at position %d" % (character, position))
    return binary_string


def binary_to_decimal(binary_string):
    validate_binary_string(binary_string)
    width = len(binary_string)
    total = 0
    for index, digit in enumerate(binary_string):
        if digit == "1":
            total += 1 << (width - 1 - index)
    return total


def expand_terms(binary_string):
    validate_binary_string(binary_string)
    width = len(binary_string)
    terms = []
    for index, digit in enumerate(binary_string):
        terms.append("%s*2^%d" % (digit, width - 1 - index))
    return terms


def describe(binary_string):
    terms = expand_terms(binary_string)
    value = binary_to_decimal(binary_string)
    return "%s = %s = %d" % (binary_string, " + ".join(terms), value)


def to_binary(value):
    if value < 0:
        raise ValueError("value must be non-negative")
    digits = []
    while value:
        digits.append(str(value & 1))
        value >>= 1
    if not digits:
        return "0"
    digits.reverse()
    return "".join(digits)


def find_non_canonical(binary_strings):
    differences = []
    for index, binary_string in enumerate(binary_strings):
        roundtrip = to_binary(binary_to_decimal(binary_string))
        if roundtrip != binary_string:
            differences.append((index, binary_string, roundtrip))
    return differences


def main():
    samples = ["101", "1111", "1011", "0", "1000000", "00101"]
    for index, sample in enumerate(samples):
        print("sample #%d: %s" % (index, describe(sample)))

    print("\nNon-canonical spellings (leading zeros dropped):")
    for index, original, roundtrip in find_non_canonical(samples):
        print("sample #%d: %s -> %s" % (index, original, roundtrip))

    try:
        binary_to_decimal("10201")
    except ValueError as error:
        print("\nRejected input: %s" % error)


if __name__ == "__main__":
    main()

