def char_counts(s):
    """Count how often each character appears in s."""
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts


def first_occurrences(s):
    """Map each character to the index where it first shows up."""
    positions = {}
    for index, ch in enumerate(s):
        if ch not in positions:
            positions[ch] = index
    return positions


def first_unique_char(s):
    """Return the index of the first character occurring exactly once, else -1."""
    counts = char_counts(s)
    positions = first_occurrences(s)
    best = -1
    for ch, count in counts.items():
        if count == 1 and (best == -1 or positions[ch] < best):
            best = positions[ch]
    return best


def unique_indices(s):
    """Return the indices of every character that occurs exactly once."""
    counts = char_counts(s)
    return [index for index, ch in enumerate(s) if counts[ch] == 1]


def highlight(s, index):
    """Return s with the character at index upper-cased for emphasis."""
    marked = []
    for position, ch in enumerate(s):
        marked.append(ch.upper() if position == index else ch)
    return "".join(marked)


def describe(s):
    """Build a one-line summary of the first unique character of s."""
    index = first_unique_char(s)
    if index < 0:
        return "{!r}: no unique character".format(s)
    return "{!r}: index {} is {!r} -> {}".format(s, index, s[index],
                                                 highlight(s, index))


def report(words):
    """Number and describe each word, one result per line."""
    lines = []
    for number, word in enumerate(words):
        lines.append("{}. {}".format(number + 1, describe(word)))
    return "\n".join(lines)


def main():
    words = ["leetcode", "loveleetcode", "aabb", "", "swiss"]
    print(report(words))
    sample = "loveleetcode"
    indices = unique_indices(sample)
    for rank, index in enumerate(indices):
        print("unique #{} at index {}: {!r}".format(rank + 1, index,
                                                    sample[index]))


if __name__ == "__main__":
    main()

