import math


def calculate_sphere_volume(radius):
    if radius < 0:
        raise ValueError("radius must be non-negative")
    return 4.0 / 3.0 * math.pi * float(radius) ** 3


def parse_radii(tokens):
    radii = []
    errors = []
    for index, token in enumerate(tokens):
        text = token.strip()
        try:
            value = float(text)
        except ValueError:
            errors.append((index, text, "not a number"))
            continue
        if value < 0:
            errors.append((index, text, "negative radius"))
            continue
        radii.append(value)
    return radii, errors


def format_table(radii):
    lines = ["idx   radius       volume"]
    for index, radius in enumerate(radii):
        volume = calculate_sphere_volume(radius)
        lines.append("{:<5d} {:<12.4f} {:<14.4f}".format(index, radius, volume))
    return "\n".join(lines)


def cumulative_totals(radii):
    totals = []
    running = 0.0
    for index, radius in enumerate(radii):
        running += calculate_sphere_volume(radius)
        totals.append((index, running))
    return totals


def largest_sphere(radii):
    best = None
    for index, radius in enumerate(radii):
        volume = calculate_sphere_volume(radius)
        if best is None or volume > best[2]:
            best = (index, radius, volume)
    return best


def spheres_above(radii, threshold):
    found = []
    for index, radius in enumerate(radii):
        volume = calculate_sphere_volume(radius)
        if volume > threshold:
            found.append((index, volume))
    return found


def report_errors(errors):
    lines = []
    for index, text, reason in errors:
        lines.append("token #{} ({!r}) rejected - {}".format(index, text, reason))
    return lines


def main():
    tokens = ["1.0", "3.0", "0.5", "-2.0", "abc", "2.5", "10", "4.25"]
    radii, errors = parse_radii(tokens)
    print(format_table(radii))
    for line in report_errors(errors):
        print(line)
    for index, running in cumulative_totals(radii):
        print("after sphere {}: total volume {:.4f}".format(index, running))
    index, radius, volume = largest_sphere(radii)
    print("largest: sphere {} with radius {:.4f} and volume {:.4f}".format(index, radius, volume))
    threshold = calculate_sphere_volume(2.0)
    for index, volume in spheres_above(radii, threshold):
        print("sphere {} exceeds the reference volume {:.4f} at {:.4f}".format(index, threshold, volume))


if __name__ == "__main__":
    main()

