import os
import tempfile


def append_to_file(filepath, content):
    """Append content to filepath; return True on success, False on failure."""
    try:
        with open(filepath, 'a', encoding='utf-8') as handle:
            handle.write(content)
    except OSError:
        return False
    return True


def validate_lines(lines):
    """Return a list of problem descriptions for entries that are not strings."""
    problems = []
    for position, line in enumerate(lines):
        if not isinstance(line, str):
            problems.append('entry %d is %s, not str' % (position, type(line).__name__))
    return problems


def append_numbered_lines(filepath, lines, start=1):
    """Append each line prefixed by its number. Returns True only if fully written."""
    problems = validate_lines(lines)
    if problems:
        raise TypeError('; '.join(problems))
    chunks = []
    for number, line in enumerate(lines, start):
        chunks.append('%4d  %s\n' % (number, line.rstrip('\n')))
    return append_to_file(filepath, ''.join(chunks))


def read_numbered(filepath):
    """Read the file back as (number, text) pairs; empty list if unreadable."""
    try:
        with open(filepath, 'r', encoding='utf-8') as handle:
            raw = handle.read().splitlines()
    except OSError:
        return []
    pairs = []
    for number, text in enumerate(raw, 1):
        pairs.append((number, text))
    return pairs


def format_report(results):
    """Turn (label, ok) results into a printable, numbered report."""
    width = max((len(label) for label, _ in results), default=0)
    rows = []
    for index, (label, ok) in enumerate(results, 1):
        rows.append('%d. %-*s %s' % (index, width, label, 'OK' if ok else 'FAILED'))
    return '\n'.join(rows)


def main():
    workdir = tempfile.mkdtemp(prefix='append_demo_')
    target = os.path.join(workdir, 'test.txt')
    jobs = [
        (target, 'Hello\n'),
        (target, 'Second line\n'),
        (os.path.join(workdir, 'missing_dir', 'file.txt'), 'Data'),
        ('/nonexistent/path/file.txt', 'Data'),
    ]
    results = []
    for attempt, (path, content) in enumerate(jobs, 1):
        ok = append_to_file(path, content)
        results.append(('attempt %d -> %s' % (attempt, path), ok))

    poem = ['roses are red', 'violets are blue', 42]
    try:
        append_numbered_lines(target, poem)
    except TypeError as error:
        results.append(('numbered append rejected', False))
        print('validation error:', error)

    results.append(('numbered append', append_numbered_lines(target, poem[:2], start=3)))
    print(format_report(results))
    print('--- contents of %s ---' % target)
    for number, text in read_numbered(target):
        print('%3d | %s' % (number, text))


if __name__ == '__main__':
    main()

