import math

AXIS_NAMES = ("x", "y", "z")


def validate_point(point, label="point"):
    if not isinstance(point, (tuple, list)):
        raise TypeError(f"{label} must be a tuple of three numbers")
    if len(point) != 3:
        raise ValueError(f"{label} must have exactly 3 coordinates, got {len(point)}")
    coords = []
    for axis, value in enumerate(point):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError(f"{label}.{AXIS_NAMES[axis]} must be a number, got {value!r}")
        coords.append(float(value))
    return tuple(coords)


def distance_3d(p1, p2):
    a = validate_point(p1, "p1")
    b = validate_point(p2, "p2")
    total = 0.0
    for axis, start in enumerate(a):
        delta = b[axis] - start
        total += delta * delta
    return math.sqrt(total)


def path_length(points):
    checked = [validate_point(p, f"points[{i}]") for i, p in enumerate(points)]
    total = 0.0
    for index, current in enumerate(checked):
        if index > 0:
            total += distance_3d(checked[index - 1], current)
    return total


def nearest_neighbour(target, candidates):
    if not candidates:
        raise ValueError("candidates must not be empty")
    best_index = 0
    best_distance = distance_3d(target, candidates[0])
    for index, candidate in enumerate(candidates):
        current = distance_3d(target, candidate)
        if current < best_distance:
            best_index, best_distance = index, current
    return best_index, best_distance


def format_point(point):
    coords = validate_point(point)
    parts = []
    for axis, value in enumerate(coords):
        parts.append(f"{AXIS_NAMES[axis]}={value:g}")
    return "(" + ", ".join(parts) + ")"


def distance_report(origin, targets):
    lines = [f"origin: {format_point(origin)}"]
    for index, target in enumerate(targets):
        d = distance_3d(origin, target)
        lines.append(f"  [{index}] {format_point(target)} -> {d:.5f}")
    winner, winner_distance = nearest_neighbour(origin, targets)
    lines.append(f"nearest: [{winner}] {format_point(targets[winner])} at {winner_distance:.5f}")
    return "\n".join(lines)


def main():
    print(distance_3d((0, 0, 0), (1, 1, 1)))
    print(distance_3d((1, 2, 3), (1, 2, 4)))

    origin = (0, 0, 0)
    targets = [(1, 1, 1), (1, 2, 4), (-3, 0, 4), (0.5, 0.5, 0.5)]
    print(distance_report(origin, targets))

    route = [origin] + targets
    print(f"route length: {path_length(route):.5f}")
    for index, point in enumerate(route):
        if index > 0:
            print(f"leg {index}: {format_point(route[index - 1])} -> {format_point(point)}")


if __name__ == "__main__":
    main()

