def validate_event(event, label="event"):
    if not isinstance(event, (tuple, list)) or len(event) != 2:
        raise ValueError(f"{label} must be a pair of times, got {event!r}")
    for index in range(len(event)):
        if not isinstance(event[index], int) or isinstance(event[index], bool):
            field = "start_time" if index == 0 else "end_time"
            raise ValueError(f"{label} {field} must be an integer, got {event[index]!r}")
    if event[0] > event[1]:
        raise ValueError(f"{label} ends before it starts: {event!r}")
    return tuple(event)


def check_event_overlap(event1, event2):
    start1, end1 = validate_event(event1, "event1")
    start2, end2 = validate_event(event2, "event2")
    return start1 < end2 and start2 < end1


def find_overlapping_pairs(events):
    pairs = []
    for i in range(len(events)):
        for j in range(i + 1, len(events)):
            if check_event_overlap(events[i], events[j]):
                pairs.append((i, j))
    return pairs


def assign_tracks(events):
    tracks = []
    assignment = [0] * len(events)
    for index in range(len(events)):
        target = len(tracks)
        for track_number in range(len(tracks)):
            if all(not check_event_overlap(events[index], events[other]) for other in tracks[track_number]):
                target = track_number
                break
        if target == len(tracks):
            tracks.append([])
        tracks[target].append(index)
        assignment[index] = target
    return assignment


def overlap_span(event1, event2):
    if not check_event_overlap(event1, event2):
        return None
    return (max(event1[0], event2[0]), min(event1[1], event2[1]))


def format_time(minutes):
    hours, rest = divmod(minutes % (24 * 60), 60)
    return f"{hours:02d}:{rest:02d}"


def format_event(event):
    return f"{format_time(event[0])}-{format_time(event[1])}"


def busiest_event(events):
    conflict_counts = [0] * len(events)
    for left, right in find_overlapping_pairs(events):
        conflict_counts[left] += 1
        conflict_counts[right] += 1
    best_index, best_count = -1, -1
    for index in range(len(conflict_counts)):
        if conflict_counts[index] > best_count:
            best_index, best_count = index, conflict_counts[index]
    return best_index, best_count


def build_report(events):
    lines = []
    tracks = assign_tracks(events)
    for index in range(len(events)):
        lines.append(f"{index + 1}. {format_event(events[index])} [track {tracks[index] + 1}]")
    pairs = find_overlapping_pairs(events)
    if not pairs:
        lines.append("No overlaps found.")
        return lines
    for left, right in pairs:
        span = overlap_span(events[left], events[right])
        lines.append(
            f"Events {left + 1} and {right + 1} overlap during {format_event(span)}"
        )
    index, count = busiest_event(events)
    lines.append(f"Most conflicted: event {index + 1} with {count} clash(es)")
    return lines


def main():
    schedule = [(10, 20), (15, 25), (30, 45), (40, 50), (44, 60), (90, 95)]
    for line in build_report(schedule):
        print(line)


if __name__ == "__main__":
    main()

