def word_frequency(words):
    """Count how often each word occurs, ignoring letter case."""
    counts = {}
    for word in words:
        key = word.strip().lower()
        if key:
            counts[key] = counts.get(key, 0) + 1
    return counts


def tokenize(text):
    """Split text into words, keeping letters, digits and inner apostrophes."""
    tokens = []
    current = []
    for position, character in enumerate(text):
        if character.isalnum() or (character == "'" and current and position + 1 < len(text)):
            current.append(character)
        elif current:
            tokens.append("".join(current))
            current = []
    if current:
        tokens.append("".join(current))
    return tokens


def first_positions(words):
    """Map each word key to the index where it first appears."""
    positions = {}
    for index, word in enumerate(words):
        key = word.strip().lower()
        if key and key not in positions:
            positions[key] = index
    return positions


def report(text):
    """Build a frequency report for a block of text."""
    words = tokenize(text)
    counts = word_frequency(words)
    ranked = rank_words(counts, first_positions(words))
    lines = ["%d tokens, %d unique" % (len(words), len(counts))]
    for line_number, raw_line in enumerate(text.splitlines(), start=1):
        lines.append("line %d: %d tokens" % (line_number, len(tokenize(raw_line))))
    return lines + format_table(ranked)


def rank_words(counts, first_seen):
    """Rank words by frequency, breaking ties by first appearance."""
    ordered = sorted(counts.items(), key=lambda pair: (-pair[1], first_seen[pair[0]]))
    ranked = []
    previous_frequency = None
    previous_rank = 0
    for position, (word, frequency) in enumerate(ordered, start=1):
        if frequency == previous_frequency:
            rank = previous_rank
        else:
            rank = position
            previous_frequency = frequency
            previous_rank = position
        ranked.append((rank, word, frequency))
    return ranked


def format_table(ranked):
    """Render ranked rows as aligned text, marking the most frequent word."""
    if not ranked:
        return ["(no words)"]
    width = max(len(word) for _, word, _ in ranked)
