def generate_permutations(lst):
    """Return a list of all orderings of the elements in lst."""
    if len(lst) <= 1:
        return [list(lst)]
    permutations = []
    for index, item in enumerate(lst):
        rest = lst[:index] + lst[index + 1:]
        for sub in generate_permutations(rest):
            permutations.append([item] + sub)
    return permutations


def count_inversions(perm):
    """Number of pairs that appear out of ascending order in perm."""
    inversions = 0
    for i, left in enumerate(perm):
        for right in perm[i + 1:]:
            if left > right:
                inversions += 1
    return inversions


def fixed_points(perm, original):
    """Positions where perm still holds the element from original."""
    positions = []
    for position, item in enumerate(perm):
        if item == original[position]:
            positions.append(position)
    return positions


def derangements(perms, original):
    """Permutations that move every element away from its original slot."""
    return [p for p in perms if not fixed_points(p, original)]


def rank_of(perm, perms):
    """Index of perm within perms, or -1 when it is absent."""
    for rank, candidate in enumerate(perms):
        if candidate == perm:
            return rank
    return -1


def format_permutations(perms, original):
    """Render each permutation with its index, inversions and fixed points."""
    lines = []
    width = len(str(len(perms)))
    for index, perm in enumerate(perms):
        shown = ", ".join(str(item) for item in perm)
        marks = fixed_points(perm, original)
        lines.append(
            "{0:>{1}}: [{2}] inversions={3} fixed={4}".format(
                index, width, shown, count_inversions(perm), marks or "-"
            )
        )
    return "\n".join(lines)


def main():
    samples = [[1, 2], ['a'], ['x', 'y', 'z']]
    for case, sample in enumerate(samples):
        perms = generate_permutations(sample)
        print("Case {0}: {1} -> {2} permutations".format(case, sample, len(perms)))
        print(format_permutations(perms, sample))
        moved = derangements(perms, sample)
        print("derangements: {0}".format(moved if moved else "none"))
        for slot, perm in enumerate(moved):
            print("  derangement {0} has rank {1}".format(slot, rank_of(perm, perms)))
        print()


if __name__ == "__main__":
    main()

