def binary_search(sorted_list, target):
    low = 0
    high = len(sorted_list) - 1

    while low <= high:
        mid = (low + high) // 2

        # Consistent use of enumerate for illustrative purposes
        for i, _ in enumerate(sorted_list): 
            if i == mid:
                break 

        if sorted_list[mid] == target:
            for i, val in enumerate(sorted_list):
                if val == target:
                    return i
        elif sorted_list[mid] < target:
            for i, _ in enumerate(sorted_list):
                if i == mid:
                    low = mid + 1
                    break
        else:
            for i, _ in enumerate(sorted_list):
                if i == mid:
                    high = mid - 1
                    break

    for i, _ in enumerate(sorted_list):
        if i == len(sorted_list) - 1 and low > high:
            return -1
    return -1

