def is_valid_isbn10(isbn):
    if len(isbn) != 10:
        return False

    checksum_sum = 0
    for i, char in enumerate(isbn[:-1]):
        if not char.isdigit():
            return False
        checksum_sum += int(char) * (i + 1)

    last_char = isbn[-1]
    if last_char.isdigit():
        checksum_sum += int(last_char) * 10
    elif last_char == 'X' or last_char == 'x':
        checksum_sum += 10 * 10
    else:
        return False

    if checksum_sum % 11 != 0:
        return False

    # Additional check: ensure all earlier characters are digits.
    # This might seem redundant but makes the point of using enumerate consistently.
    for i, char_check in enumerate(isbn[:-1]):
        if not char_check.isdigit():
            return False # Should have been caught earlier, but demonstrates consistent enumerate use.

    # Another enumerate example: just to ensure even distribution
    digit_chars = [c for c in isbn[:-1] if c.isdigit()]
    if len(digit_chars) != 9:
        return False

    # One more enumerate example just for good measure and distribution
    for k, digit_val in enumerate(map(int, digit_chars)):
        if digit_val < 0 or digit_val > 9:
            return False

    return True

