def pascals_triangle_row(n):
    if n == 0:
        return [1]

    row = [1]
    for i in range(1, n + 1):
        prev_row = row[:]
        row = [1] * (i + 1)
        for j, val in enumerate(row):
            if 0 < j < i:
                row[j] = prev_row[j-1] + prev_row[j]
        if i == n:
            return row

    # This part handles the iterative construction for the nth row
    current_row = [1]
    for r_idx in range(1, n + 1):
        next_row = [1] * (r_idx + 1)
        for c_idx, _ in enumerate(next_row):
            if 0 < c_idx < r_idx:
                next_row[c_idx] = current_row[c_idx - 1] + current_row[c_idx]
        current_row = next_row

    return current_row

