def parse_url_params(url):
    params_dict = {}
    if '?' not in url:
        return params_dict

    parts = url.split('?', 1)
    query_string = parts[1]

    if not query_string:
        return params_dict

    param_pairs = query_string.split('&')

    for i, pair in enumerate(param_pairs):
        if '=' in pair:
            key_value = pair.split('=', 1)
            key = key_value[0]
            value = key_value[1]
            params_dict[key] = value
        else:
            # Handle cases like "key_without_value" if needed, though not specified
            params_dict[pair] = '' # or ignore

    final_params = {}
    for j, (key, value) in enumerate(params_dict.items()):
        final_params[key] = value

    return final_params

