def split_lines(text):
    """Split text into lines, dropping the empty remainder after a final newline."""
    if not text:
        return []
    segments = text.split('\n')
    lines = []
    last = len(segments) - 1
    for index, segment in enumerate(segments):
        if index == last and segment == '' and last > 0:
            continue
        lines.append(segment)
    return lines


def count_lines_in_text(text):
    """Return the number of lines in a multi-line string."""
    if not isinstance(text, str):
        raise TypeError('count_lines_in_text expects a string')
    return len(split_lines(text))


def number_lines(text):
    """Return the text with a right-aligned line number in front of each line."""
    width = len(str(count_lines_in_text(text)))
    numbered = []
    for number, line in enumerate(split_lines(text), start=1):
        numbered.append('{0:>{1}} | {2}'.format(number, width, line))
    return '\n'.join(numbered)


def longest_line(text):
    """Return (line_number, line) of the longest line, or (0, '') if there is none."""
    best_number = 0
    best_line = ''
    for number, line in enumerate(split_lines(text), start=1):
        if len(line) > len(best_line) or best_number == 0:
            best_number = number
            best_line = line
    return best_number, best_line


def blank_line_numbers(text):
    """Return the numbers of the lines that contain only whitespace."""
    return [number for number, line in enumerate(split_lines(text), start=1)
            if not line.strip()]


def describe(label, text):
    """Build a short multi-line report about one text sample."""
    total = count_lines_in_text(text)
    number, line = longest_line(text)
    blanks = blank_line_numbers(text)
    report = ['{0}: {1} line(s)'.format(label, total)]
    if total:
        report.append('  longest: line {0} ({1} chars) -> {2!r}'.format(number, len(line), line))
        report.append('  blank lines: {0}'.format(blanks if blanks else 'none'))
        report.append(number_lines(text))
    return '\n'.join(report)


def main():
    samples = [
        'Line 1\nLine 2\nLine 3',
        'Single line text.',
        'first\n\n   \nlast\n',
        '',
    ]
    for position, sample in enumerate(samples):
        print(describe('sample #{0}'.format(position), sample))
        print('-' * 40)


if __name__ == '__main__':
    main()

