import random


def validate_flips(flips):
    """Return the flip string uppercased, rejecting anything that is not H or T."""
    if not isinstance(flips, str):
        raise TypeError("flips must be a string")
    cleaned = flips.strip().upper()
    for position, symbol in enumerate(cleaned):
        if symbol not in ("H", "T"):
            raise ValueError("invalid flip %r at position %d" % (symbol, position))
    return cleaned


def longest_coin_flip_streak(flips):
    """Length of the longest run of identical consecutive flips."""
    sequence = validate_flips(flips)
    longest = 0
    current = 0
    previous = ""
    for index, symbol in enumerate(sequence):
        if index and symbol == previous:
            current += 1
        else:
            current = 1
        previous = symbol
        if current > longest:
            longest = current
    return longest


def streak_segments(flips):
    """Split the sequence into (start, symbol, length) runs, in order."""
    sequence = validate_flips(flips)
    segments = []
    for index, symbol in enumerate(sequence):
        if segments and segments[-1][1] == symbol:
            start, run_symbol, length = segments[-1]
            segments[-1] = (start, run_symbol, length + 1)
        else:
            segments.append((index, symbol, 1))
    return segments


def longest_segment(flips):
    """The first run that reaches the maximum length."""
    best = None
    for segment in streak_segments(flips):
        if best is None or segment[2] > best[2]:
            best = segment
    return best


def format_report(flips):
    """Human readable breakdown of every run plus the winning streak."""
    segments = streak_segments(flips)
    if not segments:
        return "no flips recorded (longest streak: 0)"
    lines = []
    for number, (start, symbol, length) in enumerate(segments, start=1):
        lines.append("run %d: %s x%d starting at index %d" % (number, symbol, length, start))
    start, symbol, length = longest_segment(flips)
    lines.append("longest streak: %d (%s at index %d)" % (length, symbol, start))
    return "\n".join(lines)


def simulate_flips(count, seed=None):
    """Generate a random sequence of `count` coin flips."""
    if count < 0:
        raise ValueError("count must be non-negative")
    rng = random.Random(seed)
    return "".join(rng.choice("HT") for _ in range(count))


def main():
    samples = ["HHHTTTHHHH", "HTHTHT", "", simulate_flips(20, seed=7)]
    for case, sample in enumerate(samples, start=1):
        print("case %d: %r -> %d" % (case, sample, longest_coin_flip_streak(sample)))
        print(format_report(sample))
        print()


if __name__ == "__main__":
    main()

