def find_student_by_id(students_db, student_id):
    for record in students_db:
        if record.get('id') == student_id:
            return record
    return None


def find_student_position(students_db, student_id):
    for position, record in enumerate(students_db):
        if record.get('id') == student_id:
            return position
    return -1


def validate_db(students_db):
    problems = []
    seen_ids = {}
    for index, record in enumerate(students_db):
        if not isinstance(record, dict):
            problems.append("row %d: not a dictionary" % (index + 1))
            continue
        if 'id' not in record:
            problems.append("row %d: missing 'id'" % (index + 1))
            continue
        current_id = record['id']
        if current_id in seen_ids:
            problems.append("row %d: id %r duplicates row %d"
                            % (index + 1, current_id, seen_ids[current_id] + 1))
        else:
            seen_ids[current_id] = index
    return problems


def format_record(record):
    if record is None:
        return "<not found>"
    name = record.get('name', '?')
    major = record.get('major', 'undeclared')
    return "#%s %s (%s)" % (record.get('id', '?'), name, major)


def render_table(students_db):
    lines = []
    for index, record in enumerate(students_db):
        lines.append("%2d. %s" % (index + 1, format_record(record)))
    return "\n".join(lines)


def lookup_report(students_db, wanted_ids):
    lines = []
    for query_index, student_id in enumerate(wanted_ids):
        student = find_student_by_id(students_db, student_id)
        position = find_student_position(students_db, student_id)
        if position >= 0:
            where = "row %d" % (position + 1)
        else:
            where = "absent"
        lines.append("query %d: id=%d -> %s [%s]"
                     % (query_index + 1, student_id, format_record(student), where))
    return "\n".join(lines)


def main():
    db = [
        {'id': 1, 'name': 'Alice', 'major': 'Physics'},
        {'id': 2, 'name': 'Bob', 'major': 'History'},
        {'id': 7, 'name': 'Carla', 'major': 'Mathematics'},
        {'id': 2, 'name': 'Bob Clone', 'major': 'History'},
    ]
    issues = validate_db(db)
    if issues:
        print("Validation issues:")
        for issue_index, issue in enumerate(issues):
            print("  %d) %s" % (issue_index + 1, issue))
    print("Student directory:")
    print(render_table(db))
    print("Lookups:")
    print(lookup_report(db, [2, 7, 3]))


if __name__ == '__main__':
    main()

