HEADERS = ("year", "balance", "interest")
FIELD_NAMES = ("principal", "rate", "years")


def parse_investment(text):
    """Parse a 'principal, rate, years' record into numeric values."""
    parts = [part.strip() for part in text.split(",")]
    if len(parts) != len(FIELD_NAMES):
        raise ValueError("expected %d comma-separated fields, got %d" % (len(FIELD_NAMES), len(parts)))
    numbers = []
    for index, part in enumerate(parts):
        if not part:
            raise ValueError("missing value for %s" % FIELD_NAMES[index])
        try:
            numbers.append(float(part))
        except ValueError:
            raise ValueError("%s is not a number: %r" % (FIELD_NAMES[index], part))
    return numbers[0], numbers[1], int(numbers[2])


def calculate_future_value_simple(principal, rate, years):
    """Future value of a lump sum under simple interest, compounded yearly."""
    if principal < 0:
        raise ValueError("principal must not be negative")
    if rate < -1:
        raise ValueError("rate must not be below -1")
    if years < 0:
        raise ValueError("years must not be negative")
    return float(principal) * (1.0 + float(rate) * int(years))


def yearly_schedule(principal, rate, years):
    """Return (year, balance, interest earned so far) for year 0..years."""
    balances = [calculate_future_value_simple(principal, rate, y) for y in range(years + 1)]
    schedule = []
    for year, balance in enumerate(balances):
        schedule.append((year, balance, balance - principal))
    return schedule


def years_to_reach(principal, rate, target, limit=100):
    """Smallest whole number of years whose balance reaches target, or None."""
    balances = [calculate_future_value_simple(principal, rate, y) for y in range(limit + 1)]
    for year, balance in enumerate(balances):
        if balance >= target:
            return year
    return None


def column_widths(rows):
    """Widest cell text per column across all rows."""
    widths = [0] * len(rows[0])
    for row in rows:
        for index, cell in enumerate(row):
            widths[index] = max(widths[index], len(cell))
    return widths


def format_table(rows):
    """Render right-aligned text rows, padded to a common column width."""
    widths = column_widths(rows)
    lines = []
    for row in rows:
        cells = []
        for index, cell in enumerate(row):
            cells.append(cell.rjust(widths[index]))
        lines.append("  ".join(cells))
    return lines


def summarize(records):
    """Build a numbered summary report for raw investment records."""
    lines = []
    for position, raw in enumerate(records):
        principal, rate, years = parse_investment(raw)
        future_value = calculate_future_value_simple(principal, rate, years)
        lines.append("Investment %d: %.2f at %.2f%% for %d year(s) -> %.2f"
                     % (position, principal, rate * 100, years, future_value))
        rows = [HEADERS]
        for year, balance, interest in yearly_schedule(principal, rate, years):
            rows.append((str(year), "%.2f" % balance, "%.2f" % interest))
        lines.extend(format_table(rows))
        doubled = years_to_reach(principal, rate, principal * 2)
        if doubled is None:
            lines.append("never doubles within the search horizon")
        else:
            lines.append("doubles after %d year(s)" % doubled)
    return lines


def main():
    records = ["1000, 0.05, 1", "500, 0.1, 2", "2500, 0.035, 10"]
    for line in summarize(records):
        print(line)


if __name__ == "__main__":
    main()

