    return value


def find_hashtag_spans(text):
    """Return (start_index, hashtag_body) pairs for every hashtag in text."""
    _require_text(text)
    spans = []
    for i in range(len(text)):
        if text[i] != '#':
            continue
        j = i + 1
        while j < len(text) and text[j].isalnum():
            j += 1
        if j > i + 1:
            spans.append((i, text[i + 1:j]))
    return spans


def extract_hashtags(text):
    """Return the bodies of all hashtags found in text, in order of appearance."""
    return [body for _start, body in find_hashtag_spans(text)]


def frequency_table(tags):
    """Group tags case-insensitively, keeping the casing of the first occurrence."""
    counts = {}
    samples = {}
    first_seen = {}
    for position in range(len(tags)):
        key = tags[position].lower()
        counts[key] = counts.get(key, 0) + 1
        if key not in first_seen:
            first_seen[key] = position
            samples[key] = tags[position]
    ordered = sorted(counts, key=lambda key: (-counts[key], first_seen[key]))
    return [(key, counts[key], samples[key]) for key in ordered]


def unique_hashtags(text):
    """Return one representative casing per distinct hashtag, first-appearance order."""
    seen = set()
    representatives = []
    for tag in extract_hashtags(text):
        key = tag.lower()
        if key not in seen:
            seen.add(key)
            representatives.append(tag)
    return representatives


def format_frequency_lines(table):
    """Render the rows of a frequency table as ranked report lines."""
    lines = []
    for rank in range(len(table)):
        (key, count, sample) = table[rank]
        lines.append("    %d. #%s (%d occurrence(s), key=%s)" % (rank + 1, sample, count, key))
    return lines


def format_report(text):
    spans = find_hashtag_spans(text)
    lines = ["text: " + text]
    if not spans:
        lines.append("  no hashtags found")
        return "\n".join(lines)
    for number in range(len(spans)):
        (start, tag) = spans[number]
        lines.append("  %d) %-12s column %d" % (number + 1, tag, start + 1))
    lines.append("  distinct hashtags, most frequent first:")
    lines.extend(format_frequency_lines(frequency_table(extract_hashtags(text))))
    return "\n".join(lines)


def main():
    samples = [
        'This is a #test with #Python.',
        'No hashtags here!',
        '#Sun #sun #SUN and #rain2026, but # alone and #! are not tags.',
    ]
    for index in range(len(samples)):
        print("--- sample %d ---" % (index + 1))
        print(format_report(samples[index]))
        print("  extract_hashtags -> %r" % (extract_hashtags(samples[index]),))
        print("  unique_hashtags  -> %r" % (unique_hashtags(samples[index]),))


if __name__ == "__main__":
    main()

