DIGITS = "0123456789abcdefghijklmnopqrstuvwxyz"

DIGIT_VALUES = {}
for value, ch in enumerate(DIGITS):
    DIGIT_VALUES[ch] = value


def digit_value(ch):
    """Return the numeric value of a single digit character."""
    value = DIGIT_VALUES.get(ch.lower())
    if value is None:
        raise ValueError(f"{ch!r} is not a usable digit")
    return value


def validate(num_str, base):
    """Raise ValueError if num_str is not a legal number in the given base."""
    if not isinstance(base, int) or not 2 <= base <= 36:
        raise ValueError(f"base must be an integer between 2 and 36, got {base!r}")
    if not num_str:
        raise ValueError("num_str must contain at least one digit")
    for position, ch in enumerate(num_str):
        if digit_value(ch) >= base:
            raise ValueError(f"digit {ch!r} at position {position} is invalid in base {base}")


def base_n_to_base_10(num_str, base):
    """Convert num_str, written in the given base, to a base-10 integer."""
    validate(num_str, base)
    last = len(num_str) - 1
    total = 0
    for index, ch in enumerate(num_str):
        total += digit_value(ch) * base ** (last - index)
    return total


def expansion(num_str, base):
    """Describe the conversion as a sum of digit * base**power terms."""
    last = len(num_str) - 1
    terms = []
    for index, ch in enumerate(num_str):
        terms.append(f"{digit_value(ch)}*{base}^{last - index}")
    return " + ".join(terms)


def build_rows(cases):
    """Turn (num_str, base) pairs into printable table rows."""
    rows = [("#", "input", "base", "expansion", "base-10")]
    for number, case in enumerate(cases):
        num_str, base = case
        value = base_n_to_base_10(num_str, base)
        rows.append((str(number + 1), num_str, str(base), expansion(num_str, base), str(value)))
    return rows


def column_widths(rows):
    """Return the width of the widest cell in each column."""
    widths = [len(cell) for cell in rows[0]]
    for row in rows[1:]:
        for column, cell in enumerate(row):
            widths[column] = max(widths[column], len(cell))
    return widths


def format_row(row, widths):
    """Pad each cell of a row to its column width and join the cells."""
    padded = []
    for column, cell in enumerate(row):
        padded.append(cell.ljust(widths[column]))
    return "  ".join(padded).rstrip()


def render_table(rows):
    """Render rows as columns padded to a common width, with a header rule."""
    widths = column_widths(rows)
    header = format_row(rows[0], widths)
    lines = [header, "-" * len(header)]
    for row in rows[1:]:
        lines.append(format_row(row, widths))
    return "\n".join(lines)


def main():
    cases = [("101", 2), ("A", 16), ("777", 8), ("zz", 36), ("2024", 10)]
    print(render_table(build_rows(cases)))


if __name__ == "__main__":
    main()

