def validate_square(matrix):
    """Raise ValueError unless matrix is a non-empty list of equal-length rows."""
    if not isinstance(matrix, list) or not matrix:
        raise ValueError("matrix must be a non-empty list of rows")
    n = len(matrix)
    for i, row in enumerate(matrix):
        if not isinstance(row, list):
            raise ValueError("row %d is not a list" % i)
        if len(row) != n:
            raise ValueError("row %d has length %d, expected %d" % (i, len(row), n))
    return n


def rotate_matrix_90_clockwise(matrix):
    """Rotate a square matrix 90 degrees clockwise in place and return it."""
    n = validate_square(matrix)
    for i, row in enumerate(matrix):
        for j in range(i + 1, n):
            row[j], matrix[j][i] = matrix[j][i], row[j]
    for row in matrix:
        row.reverse()
    return matrix


def column_widths(matrix):
    """Width needed by each column when the cells are rendered as text."""
    widths = [0] * len(matrix)
    for row in matrix:
        for j, value in enumerate(row):
            widths[j] = max(widths[j], len(str(value)))
    return widths


def format_matrix(matrix):
    """Render a matrix as aligned text rows."""
    widths = column_widths(matrix)
    lines = []
    for row in matrix:
        cells = []
        for j, value in enumerate(row):
            cells.append(str(value).rjust(widths[j]))
        lines.append("[ " + "  ".join(cells) + " ]")
    return "\n".join(lines)


def find_mismatches(result, expected):
    """List (row, column) positions where two equally shaped matrices differ."""
    bad = []
    for i, got_row in enumerate(result):
        for j, got in enumerate(got_row):
            if got != expected[i][j]:
                bad.append((i, j))
    return bad


def main():
    cases = [
        ("2x2", [[1, 2], [3, 4]], [[3, 1], [4, 2]]),
        ("3x3", [[1, 2, 3], [4, 5, 6], [7, 8, 9]], [[7, 4, 1], [8, 5, 2], [9, 6, 3]]),
        ("wide cells", [[10, 200], [3000, 4]], [[3000, 10], [4, 200]]),
    ]
    for label, matrix, expected in cases:
        original = format_matrix(matrix)
        rotated = rotate_matrix_90_clockwise(matrix)
        print("%s, before:" % label)
        print(original)
