def validate_numbers(numbers):
    """Return the input as a list of floats, rejecting non-numeric entries."""
    if not isinstance(numbers, (list, tuple)):
        raise TypeError("numbers must be a list or tuple")
    cleaned = []
    for index, value in enumerate(numbers):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("element %d is not a number: %r" % (index, value))
        cleaned.append(float(value))
    return cleaned


def split_by_trim(values, num_to_exclude):
    """Split sorted values into (low outliers, kept values, high outliers)."""
    ordered = sorted(values)
    cut = max(num_to_exclude, 0)
    upper_start = len(ordered) - cut
    low, kept, high = [], [], []
    for position, value in enumerate(ordered):
        if position < cut:
            low.append(value)
        elif position >= upper_start:
            high.append(value)
        else:
            kept.append(value)
    return low, kept, high


def calculate_average_no_outliers(numbers, num_to_exclude):
    """Average the numbers after dropping the n smallest and n largest."""
    values = validate_numbers(numbers)
    _, kept, _ = split_by_trim(values, num_to_exclude)
    if not kept:
        return 0.0
    return sum(kept) / len(kept)


def describe_outliers(low, high):
    """Describe each removed value together with the end it came from."""
    parts = []
    for rank, value in enumerate(low, start=1):
        parts.append("low #%d = %g" % (rank, value))
    for rank, value in enumerate(high, start=1):
        parts.append("high #%d = %g" % (rank, value))
    return ", ".join(parts) if parts else "none"


def format_report(label, numbers, num_to_exclude):
    """Build a multi-line report for one dataset."""
    values = validate_numbers(numbers)
    low, kept, high = split_by_trim(values, num_to_exclude)
    lines = ["%s: %d values, excluding %d from each end" %
             (label, len(values), num_to_exclude)]
    lines.append("  removed: " + describe_outliers(low, high))
    for rank, value in enumerate(kept, start=1):
        lines.append("  kept %d: %g" % (rank, value))
    lines.append("  average: %.4f" % calculate_average_no_outliers(numbers, num_to_exclude))
    return "\n".join(lines)


def main():
    datasets = [
        ([1, 2, 3, 100], 1),
        ([10, 20, 30, 40, 50], 0),
        ([4.5, -2, 7, 7, 1, 19], 2),
        ([5, 6], 1),
        ([8, 9, 10], 5),
    ]
    for case_number, (numbers, num_to_exclude) in enumerate(datasets, start=1):
        print(format_report("Case %d" % case_number, numbers, num_to_exclude))
        print()


if __name__ == "__main__":
    main()

