import sys


def validate_components(components):
    """Check that the input really is a sequence of strings."""
    if not isinstance(components, (list, tuple)):
        raise TypeError("components must be a list or tuple of strings")
    for index, component in enumerate(components):
        if not isinstance(component, str):
            raise TypeError(
                "component %d is %s, expected str"
                % (index, type(component).__name__)
            )


def split_segments(path):
    """Return the non-empty segments of a path string."""
    return [segment for segment in path.split('/') if segment]


def resolve_segments(segments, absolute):
    """Collapse '.' and '..' entries, keeping leading '..' on relative paths."""
    stack = []
    for segment in segments:
        if segment == '.':
            continue
        if segment == '..':
            if stack and stack[-1] != '..':
                stack.pop()
            elif not absolute:
                stack.append('..')
        else:
            stack.append(segment)
    return stack


def join_path_components(components):
    """Join path components with exactly one '/' between them."""
    validate_components(components)
    absolute = False
    segments = []
    for index, raw in enumerate(components):
        if index == 0 and raw.startswith('/'):
            absolute = True
        segments.extend(split_segments(raw))
    joined = '/'.join(resolve_segments(segments, absolute))
    if absolute:
        return '/' + joined
    return joined


def describe_segments(segments):
    """Return numbered lines naming each level of a split path."""
    lines = []
    for index, segment in enumerate(segments):
        lines.append("  %d. %s" % (index + 1, segment))
    return lines


def common_prefix(paths):
    """Return the longest path shared by all of the given joined paths."""
    segment_lists = [split_segments(path) for path in paths]
    prefix = []
    for index, segment in enumerate(segment_lists[0]):
        if any(index >= len(other) or other[index] != segment
               for other in segment_lists[1:]):
            break
        prefix.append(segment)
    root = '/' if all(path.startswith('/') for path in paths) else ''
    return root + '/'.join(prefix)


def relative_path(base, target):
    """Return the path of target expressed relative to base."""
    base_segments = split_segments(base)
    target_segments = split_segments(target)
    shared = 0
    for index, segment in enumerate(base_segments):
        if index >= len(target_segments) or target_segments[index] != segment:
            break
        shared = index + 1
    ups = ['..'] * (len(base_segments) - shared)
    return '/'.join(ups + target_segments[shared:]) or '.'


def main(argv):
    specs = argv[1:] or [line for line in sys.stdin if line.split()]
    paths = [join_path_components(spec.split()) for spec in specs]
    for index, path in enumerate(paths):
        print("%d: %s" % (index + 1, path))
        for line in describe_segments(split_segments(path)):
            print(line)
    if len(paths) > 1:
        shared = common_prefix(paths)
        print("common: %s" % shared)
        for path in paths:
            print("  %s -> %s" % (path, relative_path(shared, path)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

