        if any(index >= len(other) or other[index] != segment_lists[0][index]
               for other in segment_lists[1:]):
            break
        prefix.append(segment_lists[0][index])
    root = '/' if all(path.startswith('/') for path in paths) else ''
    return root + '/'.join(prefix)


def relative_path(base, target):
    """Return the path of target expressed relative to base."""
    base_segments = split_segments(base)
    target_segments = split_segments(target)
    shared = 0
    for index in range(len(base_segments)):
        if index >= len(target_segments) or target_segments[index] != base_segments[index]:
            break
        shared = index + 1
    ups = ['..'] * (len(base_segments) - shared)
    return '/'.join(ups + target_segments[shared:]) or '.'


def main(argv):
    specs = argv[1:] or [line for line in sys.stdin if line.split()]
    paths = [join_path_components(spec.split()) for spec in specs]
    for index in range(len(paths)):
        print("%d: %s" % (index + 1, paths[index]))
        for line in describe_segments(split_segments(paths[index])):
            print(line)
    if len(paths) > 1:
        shared = common_prefix(paths)
        print("common: %s" % shared)
        for path in paths:
            print("  %s -> %s" % (path, relative_path(shared, path)))
    return 0


if __name__ == '__main__':
    sys.exit(main(sys.argv))

