def validate_series(data):
    """Check that every entry of the series is a real number, returning floats."""
    clean = []
    for index, value in enumerate(data):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("data[%d] is not a number: %r" % (index, value))
        clean.append(float(value))
    return clean


def calculate_sma_fixed_window(data, window_size):
    """Simple moving average over a fixed window; empty if window exceeds data."""
    if not isinstance(window_size, int) or isinstance(window_size, bool):
        raise TypeError("window_size must be an int")
    if window_size < 1:
        raise ValueError("window_size must be positive")
    series = validate_series(data)
    if window_size > len(series):
        return []
    averages = []
    running = 0.0
    for index, value in enumerate(series):
        running += value
        if index >= window_size:
            running -= series[index - window_size]
        if index >= window_size - 1:
            averages.append(running / window_size)
    return averages


def trend_labels(averages):
    """Describe how each moving average moved relative to the previous one."""
    labels = []
    for index, average in enumerate(averages):
        if index == 0:
            labels.append("start")
        elif average > averages[index - 1]:
            labels.append("up")
        elif average < averages[index - 1]:
            labels.append("down")
        else:
            labels.append("flat")
    return labels


def peak_window(averages, window_size):
    """Locate the highest moving average and the data index where it ends."""
    best = 0
    for position, average in enumerate(averages):
        if average > averages[best]:
            best = position
    return best + window_size - 1, averages[best]


def format_report(data, window_size):
    """Build a per-point text report of the moving average and its trend."""
    averages = calculate_sma_fixed_window(data, window_size)
    if not averages:
        return ["window %d is larger than the %d point series" % (window_size, len(data))]
    labels = trend_labels(averages)
    lines = []
    for index, value in enumerate(data):
        position = index - (window_size - 1)
        if position < 0:
            lines.append("%2d  value=%8.2f  sma=%8s" % (index, value, "-"))
        else:
            lines.append("%2d  value=%8.2f  sma=%8.2f  %s"
                         % (index, value, averages[position], labels[position]))
    end_index, best = peak_window(averages, window_size)
    lines.append("peak sma %.2f ends at index %d" % (best, end_index))
    return lines


def main():
    datasets = [
        ([10, 20, 30, 40, 50], 3),
        ([1, 2, 3, 4], 2),
        ([5, 3, 3, 9, 8, 8, 2], 4),
        ([7, 7], 5),
    ]
    for data, window_size in datasets:
        print("data=%s window=%d" % (data, window_size))
        print("  sma = %s" % (calculate_sma_fixed_window(data, window_size),))
        for line in format_report(data, window_size):
            print("  " + line)
        print()


if __name__ == "__main__":
    main()

