MONTH_NAMES = [
    "January", "February", "March", "April", "May", "June",
    "July", "August", "September", "October", "November", "December",
]
MONTH_LENGTHS = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]


def is_leap_year(year):
    if year % 400 == 0:
        return True
    if year % 100 == 0:
        return False
    return year % 4 == 0


def parse_years(text):
    years = []
    for position, token in enumerate(text.split(), start=1):
        try:
            years.append(int(token))
        except ValueError:
            raise ValueError("token %d (%r) is not an integer" % (position, token))
    return years


def month_lengths(year):
    lengths = list(MONTH_LENGTHS)
    if is_leap_year(year):
        lengths[1] = 29
    return lengths


def day_of_year(year, month, day):
    if not 1 <= month <= 12:
        raise ValueError("month out of range: %d" % month)
    total = 0
    for index, length in enumerate(month_lengths(year), start=1):
        if index == month:
            if not 1 <= day <= length:
                raise ValueError("day out of range for month %d: %d" % (month, day))
            return total + day
        total += length


def calendar_lines(year):
    lines = []
    for index, length in enumerate(month_lengths(year)):
        lines.append("%2d %-9s %2d days" % (index + 1, MONTH_NAMES[index], length))
    return lines


def leap_years_in(start, end):
    return [year for year in range(start, end + 1) if is_leap_year(year)]


def report(years):
    lines = []
    for number, year in enumerate(years, start=1):
        verdict = "leap" if is_leap_year(year) else "common"
        lines.append("%d. %d is a %s year (%d days)" % (number, year, verdict, 365 + is_leap_year(year)))
    return lines


def main():
    years = parse_years("2000 1900 2024 2023 1600")
    for line in report(years):
        print(line)

    print("\nCalendar for 2024:")
    for line in calendar_lines(2024):
        print(line)

    print("\nLeap years 1896-1912:")
    for offset, year in enumerate(leap_years_in(1896, 1912)):
        print("  [%d] %d" % (offset, year))

    for label, (y, m, d) in enumerate([(2024, 3, 1), (2023, 3, 1)]):
        print("case %d: day %d of %d" % (label, day_of_year(y, m, d), y))


if __name__ == "__main__":
    main()

