def validate_date(date_str):
    parts = date_str.split('-')
    if len(parts) != 3:
        raise ValueError("date must look like 'YYYY-MM-DD': %r" % date_str)
    expected_widths = (4, 2, 2)
    for index, part in enumerate(parts):
        if len(part) != expected_widths[index] or not part.isdigit():
            raise ValueError("bad field %d in date %r" % (index + 1, date_str))
