def character_frequency(text):
    """Count characters in `text`, ignoring case and whitespace."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    counts = {}
    for char in text:
        if char.isspace():
            continue
        key = char.lower()
        counts[key] = counts.get(key, 0) + 1
    return counts


def first_positions(text):
    """Map each counted character to the index where it first appears."""
    positions = {}
    for index, char in enumerate(text):
        if char.isspace():
            continue
        key = char.lower()
        if key not in positions:
            positions[key] = index
    return positions


def ranked_characters(text):
    """Characters sorted by descending count, ties broken by first appearance."""
    counts = character_frequency(text)
    positions = first_positions(text)
    return sorted(counts.items(), key=lambda item: (-item[1], positions[item[0]]))


def format_report(text, top=None):
    """Build a human readable frequency report for `text`."""
    ranking = ranked_characters(text)
    if top is not None:
        ranking = ranking[:top]
    total = sum(count for _, count in ranking)
    lines = ["Report for {!r} ({} counted characters)".format(text, total)]
    for rank, (char, count) in enumerate(ranking, start=1):
        share = 100.0 * count / total if total else 0.0
        bar = "#" * count
        lines.append("{:>2}. {} {:>3}  {:5.1f}%  {}".format(rank, char, count, share, bar))
    return "\n".join(lines)


def compare_texts(texts):
    """Return, for every text, the characters it shares with the previous one."""
    frequencies = [character_frequency(text) for text in texts]
    shared = []
    for position, counts in enumerate(frequencies):
        if position == 0:
            shared.append([])
            continue
        previous = frequencies[position - 1]
        shared.append(sorted(key for key in counts if key in previous))
    return shared


def main():
    samples = ["Hello World", "Python", "Mississippi river"]
    for number, sample in enumerate(samples, start=1):
        print("=== sample {} ===".format(number))
        print(character_frequency(sample))
        print(format_report(sample, top=4))
    overlaps = compare_texts(samples)
    for position, common in enumerate(overlaps):
        if position == 0:
            continue
        print("{} shares with {}: {}".format(
            samples[position], samples[position - 1], ", ".join(common) or "nothing"))


if __name__ == "__main__":
    main()

